      for (const file of result.files) io.stdout(`${file.path}: ${file.bytes} bytes`);
      io.stdout(`bundle: ${result.files.length} files, ${result.totalBytes} bytes`);
      return 0;
    } catch (error) {
      io.stderr(`tally publish: ${(error as Error).message}`);
      return 2;
    }
