import { execFile, spawn } from 'node:child_process';
import { promisify } from 'node:util';
import { resolve } from 'node:path';
import type { IntegrationState } from '../schema/types.js';
import type { IntegrationOnboarding, OnboardingContext, OnboardingResult } from './types.js';

export type EntireOnboardingCommand = (file: string, args: string[], options: {
  cwd: string;
  interactive?: boolean;
}) => Promise<{ stdout: string }>;

const command: EntireOnboardingCommand = async (file, args, options) => {
  if (!options.interactive) return promisify(execFile)(file, args, { cwd: options.cwd, timeout: 120_000, encoding: 'utf8' });
  // Entire owns its login and keyring; Tally neither reads nor copies its tokens.
  await new Promise<void>((done, fail) => {
    const child = spawn(file, args, { cwd: options.cwd, stdio: 'inherit' });
    child.once('error', fail);
    child.once('exit', code => code === 0 ? done() : fail(new Error('Entire login did not complete')));
  });
  return { stdout: '' };
};

const SETTINGS_FILES = ['.entire/settings.json', '.entire/.gitignore', '.claude/settings.json', '.codex/hooks.json', '.codex/config.toml', '.gitignore'];
const json = (text: string): Record<string, unknown> => {
  const parsed: unknown = JSON.parse(text);
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('Unreadable Entire status');
  return parsed as Record<string, unknown>;
};

export interface EntireOnboardingOptions {
  cwd?: string;
  command?: EntireOnboardingCommand;
}

export class EntireOnboarding implements IntegrationOnboarding {
  private cwd: string;
  private readonly command: EntireOnboardingCommand;
  constructor(options: EntireOnboardingOptions = {}) {
    this.cwd = resolve(options.cwd ?? process.cwd());
    this.command = options.command ?? command;
  }
  private async run(file: string, args: string[], interactive = false): Promise<string> {
    return (await this.command(file, args, { cwd: this.cwd, interactive })).stdout.replace(/\r?\n$/, '');
  }
  private async loggedIn(): Promise<boolean> {
    return json(await this.run('entire', ['auth', 'status', '--json'])).logged_in === true;
  }
  private async graphInstalled(): Promise<boolean> {
    return /^\s*graph\s+/m.test(await this.run('entire', ['plugin', 'list']));
  }
  private async status(): Promise<Record<string, unknown>> {
    return json(await this.run('entire', ['status', '--json']));
  }
  async check(): Promise<IntegrationState> {
    try {
      await this.run('entire', ['--version']);
      if (!await this.loggedIn()) return { status: 'missing', detail: 'Entire login is needed; run entire login.' };
      if (!await this.graphInstalled()) return { status: 'missing', detail: 'Entire graph plugin is missing; run entire plugin install graph.' };
      if ((await this.status()).enabled !== true) return { status: 'missing', detail: 'Entire capture is not enabled in this repository.' };
      return { status: 'ok', detail: 'Entire login, graph plugin and repository capture are available.' };
    } catch { return { status: 'missing', detail: 'Entire is unavailable; install instructions and sign-up: https://entire.io.' }; }
  }
  async connect(context: OnboardingContext): Promise<IntegrationState> {
    this.cwd = resolve(context.repoRoot ?? this.cwd);
    try {
      await this.run('entire', ['--version']);
      if (!await this.loggedIn()) {
        context.ui.print('Entire needs its own login. No account? Sign up at https://entire.io or skip for now.');
        if (!await context.ui.confirm('Run entire login to connect this machine?')) return { status: 'off', detail: 'Entire login skipped.' };
        await this.run('entire', ['login'], true);
        if (!await this.loggedIn()) throw new Error('Login not verified');
      }
      if (!await this.graphInstalled()) {
        if (!await context.ui.confirm('Install the Entire graph plugin for code-impact sizing?')) return { status: 'off', detail: 'Entire graph installation skipped.' };
        await this.run('entire', ['plugin', 'install', 'graph']);
        if (!await this.graphInstalled()) throw new Error('Graph plugin not available');
      }
      return { status: 'ok', detail: 'Entire login and graph plugin verified.' };
    } catch { return { status: 'missing', detail: 'Entire connection did not complete; sign-up/install instructions: https://entire.io.' }; }
  }
  async configure(context: OnboardingContext): Promise<OnboardingResult> {
    const off = (detail: string): OnboardingResult => {
      context.ui.print(`${detail} Entire will be off: sizing uses code search and escalation has no Entire checkpoint handoff.`);
      return { enabled: false, state: { status: 'off', detail } };
    };
    const connection = await this.connect(context);
    if (connection.status !== 'ok') return off(connection.detail ?? 'Entire skipped.');
    try {
      const root = await this.run('git', ['rev-parse', '--show-toplevel']);
      if (resolve(root) !== this.cwd) return off('Entire setup needs the target repository root; no capture settings were changed.');
      let status = await this.status();
      const agents = new Set(Array.isArray(status.agents) ? status.agents.map(a => String(a).toLowerCase().replace(/ /g, '-')) : []);
      const required = [...new Set(context.config.tiers.map(t => t.harness))].filter(a => a === 'codex' || a === 'claude-code');
      if (status.enabled !== true || required.some(agent => !agents.has(agent))) {
        // A dirty checkout may contain unrelated or pre-existing settings changes. Never stage them.
        if (await this.run('git', ['status', '--porcelain'])) return off('Entire capture setup needs a clean checkout so existing edits remain untouched.');
        context.ui.print(`Enable Entire capture in ${this.cwd}. It may add or update: ${SETTINGS_FILES.join(', ')} and local Git hooks.`);
        context.ui.print('Settings must be committed to the default branch for worker worktrees to inherit them. Codex hooks need trusting once via /hooks. Telemetry stays off; no summaries are generated.');
        if (!await context.ui.confirm('Enable these repository capture settings? No commit or push yet.')) return off('Entire repository setup declined.');
        const primary = required[0] ?? 'claude-code';
        if (status.enabled !== true) {
          await this.run('entire', ['enable', '--agent', primary, '--telemetry=false', '--project', '--no-init-repo', '--skip-initial-commit']);
          agents.add(primary);
        }
        for (const agent of required) if (!agents.has(agent)) await this.run('entire', ['agent', 'add', agent]);
        status = await this.status();
        if (status.enabled !== true) throw new Error('Capture was not enabled');
        const lines = (await this.run('git', ['status', '--porcelain', '--untracked-files=all'])).split('\n').filter(Boolean);
        const files = lines.map(line => line.slice(3));
        if (files.some(file => !SETTINGS_FILES.includes(file))) return off('Entire generated unexpected files; review them before publishing. Nothing was committed or pushed.');
        if (files.length) {
          context.ui.print(`Generated settings to publish: ${files.join(', ')}.`);
          const branch = await this.run('git', ['branch', '--show-current']);
          const remoteHead = await this.run('git', ['symbolic-ref', '--short', 'refs/remotes/origin/HEAD']).catch(() => '');
          const defaultBranch = remoteHead.startsWith('origin/') ? remoteHead.slice('origin/'.length) : null;
          if (!defaultBranch || branch !== defaultBranch) return off('Capture is enabled locally, but settings are not on the default branch; publish them through your normal review process, then rerun init.');
          const local = await this.run('git', ['rev-parse', 'HEAD']);
          const remote = await this.run('git', ['rev-parse', `refs/remotes/origin/${defaultBranch}`]);
          if (local !== remote) return off('Default branch has unpublished commits; Entire setup will not publish unrelated work.');
          if (!await context.ui.confirm(`Commit only these settings and push to origin/${defaultBranch}? Entire Git hooks may also publish checkpoint/session evidence.`)) return off('Publishing settings declined; local capture settings remain for review.');
          if (await this.run('git', ['branch', '--show-current']) !== defaultBranch || await this.run('git', ['rev-parse', 'HEAD']) !== local) {
            return off('Checkout moved while awaiting approval; no settings were committed or pushed.');
          }
          await this.run('git', ['add', '--', ...files]);
          await this.run('git', ['commit', '-m', 'chore: enable Entire capture for Tally workers', '--', ...files]);
          const setupCommit = await this.run('git', ['rev-parse', 'HEAD']);
          if (await this.run('git', ['rev-parse', `${setupCommit}^`]) !== local) return off('Setup commit has an unexpected base; no push was attempted.');
          await this.run('git', ['push', 'origin', `${setupCommit}:refs/heads/${defaultBranch}`]);
        }
      }
      if (required.includes('codex')) context.ui.print('In Codex started inside this repository, open /hooks and trust the Entire capture hooks once. Tally cannot approve them for you.');
      // Local enablement alone is insufficient: future workers inherit the default-branch files.
      const pending = await this.run('git', ['status', '--porcelain', '--', ...SETTINGS_FILES]);
      if (pending) return off('Capture settings are still uncommitted; Entire remains off until they are published on the default branch.');
      const published = json(await this.run('git', ['show', 'refs/remotes/origin/HEAD:.entire/settings.json']));
      if (published.enabled !== true) return off('Entire capture is not enabled on the remote default branch yet.');
      for (const agent of required) {
        const file = agent === 'codex' ? '.codex/hooks.json' : '.claude/settings.json';
        const settings = await this.run('git', ['show', `refs/remotes/origin/HEAD:${file}`]);
        if (!/\bentire\s+hooks\b/.test(settings)) return off(`The default branch has no Entire ${agent} hooks yet.`);
      }
      if (required.includes('codex') && !await context.ui.confirm('Have you trusted the Entire hooks via /hooks in Codex for this repository?')) {
        return off('Codex hook trust is not confirmed; no worker was started.');
      }
      return { enabled: true, state: { status: 'ok', detail: 'Entire login, graph and repository capture configured; generated summaries remain opt-in and off by default.' } };
    } catch { return off('Entire setup could not be verified. Any generated files remain for review; no further changes were attempted.'); }
  }
}

import type { IntegrationState, TallyConfig } from '../schema/types.js';

export interface OnboardingUi {
  print(message: string): void;
  /** Default-no confirmation; an unattended init must not imply consent. */
  confirm(question: string): Promise<boolean>;
  /** Returns a zero-based index, or null when the user skips. */
  select(question: string, choices: string[]): Promise<number | null>;
}

export interface OnboardingContext {
  config: TallyConfig;
  ui: OnboardingUi;
  /** Actual target root, independent of the CLI process's working directory. */
  repoRoot?: string;
}

export interface OnboardingResult {
  enabled: boolean;
  state: IntegrationState;
  /** Proposed configuration only; the init owner performs the final write. */
  budget?: TallyConfig['budget'];
}

export interface IntegrationOnboarding {
  check(): Promise<IntegrationState>;
  connect(context: OnboardingContext): Promise<IntegrationState>;
  configure(context: OnboardingContext): Promise<OnboardingResult>;
}
import { Ajv2020 } from 'ajv/dist/2020.js';
import {
  CfoaiBudgetAdapter, cfoaiMonthColumn, checkCfoaiConnection, createCfoaiClient, loginCfoai,
  type CfoaiMcpClient,
} from '../adapters/cfoai.js';
import type { IntegrationState } from '../schema/types.js';
import type { IntegrationOnboarding, OnboardingContext, OnboardingResult } from './types.js';

type ObjectValue = Record<string, unknown>;
const object = (value: unknown): ObjectValue => value && typeof value === 'object' && !Array.isArray(value)
  ? value as ObjectValue : {};
const text = (value: unknown): string | undefined => typeof value === 'string' && value.trim() ? value : undefined;
const https = (value: unknown): string | undefined => {
  try {
    const url = new URL(String(value));
    return url.protocol === 'https:' && !url.username && !url.password ? url.href : undefined;
  } catch { return undefined; }
};

function payload(result: unknown): ObjectValue {
  const r = object(result);
  if (r.isError === true) throw new Error('cfo.ai refused the operation');
  if (r.structuredContent) return object(r.structuredContent);
  const blocks = Array.isArray(r.content) ? r.content : [];
  for (const block of blocks) {
    const b = object(block);
    if (b.type === 'text' && typeof b.text === 'string') {
      try { return object(JSON.parse(b.text)); } catch { /* Try the next content block. */ }
    }
  }
  throw new Error('cfo.ai returned an unreadable response');
}

async function choose(context: OnboardingContext, question: string, values: ObjectValue[], name: (v: ObjectValue) => string): Promise<ObjectValue | null> {
  if (values.length === 1) return values[0]!;
  if (!values.length) return null;
  const index = await context.ui.select(question, values.map(name));
  return index === null ? null : values[index] ?? null;
}

export interface CfoaiOnboardingOptions {
  client?: () => CfoaiMcpClient;
  check?: () => Promise<IntegrationState>;
  login?: () => Promise<unknown>;
  now?: () => Date;
}

/** No init-file writes, no other harness's credentials, and no model edits without consent. */
export class CfoaiOnboarding implements IntegrationOnboarding {
  private readonly options: CfoaiOnboardingOptions;
  constructor(options: CfoaiOnboardingOptions = {}) { this.options = options; }

  async check(): Promise<IntegrationState> {
    try { return await (this.options.check ?? checkCfoaiConnection)(); }
    catch { return { status: 'missing', detail: 'cfo.ai is unavailable; run tally login cfoai.' }; }
  }

  async connect(context: OnboardingContext): Promise<IntegrationState> {
    const current = await this.check();
    if (current.status === 'ok') return current;
    context.ui.print('cfo.ai needs a Tally connection. No account? Sign up at https://app.cfo.ai; you can skip for now.');
    if (!await context.ui.confirm('Open the browser to connect Tally to cfo.ai?')) {
      return { status: 'off', detail: 'cfo.ai skipped; the tally.yaml budget remains available.' };
    }
    try {
      await (this.options.login ?? loginCfoai)();
      return await this.check();
    } catch {
      return { status: 'missing', detail: 'cfo.ai login did not complete; run tally login cfoai to retry.' };
    }
  }

  async configure(context: OnboardingContext): Promise<OnboardingResult> {
    const off = (detail: string): OnboardingResult => ({
      enabled: false, state: { status: 'off', detail },
      budget: { source: 'config', usd: context.config.budget.usd },
    });
    const connection = await this.connect(context);
    if (connection.status !== 'ok') {
      context.ui.print(connection.detail ?? 'cfo.ai skipped.');
      return { ...off(connection.detail ?? 'cfo.ai unavailable'), state: connection };
    }
    const client = (this.options.client ?? createCfoaiClient)();
    try {
      await client.connect();
      const listed = await client.listTools();
      const tools = new Map(listed.tools.map(tool => [tool.name, tool]));
      const call = async (name: string, args: ObjectValue): Promise<ObjectValue> => {
        const tool = tools.get(name);
        if (!tool) throw new Error(`Missing ${name}`);
        // Refuse an unvalidated write if a server does not publish its edit schema.
        if (name.startsWith('edit_') && !tool.inputSchema) throw new Error('Missing edit schema');
        if (tool.inputSchema) {
          const validator = new Ajv2020({ strict: false, allErrors: true }).compile(tool.inputSchema);
          if (!validator(args)) throw new Error(`Incompatible ${name} schema`);
        }
        return payload(await client.callTool(name, args));
      };
      const orgs = await call('list_orgs', {});
      const workspace = await choose(context, 'Choose a cfo.ai workspace (or skip)',
        Array.isArray(orgs.orgs) ? orgs.orgs.map(object) : [], v => `${v.name} (${v.org_id})`);
      if (!workspace) return off('cfo.ai skipped: no workspace selected. Sign up at https://app.cfo.ai.');
      const orgId = text(workspace.org_id) ?? (typeof workspace.org_id === 'number' ? String(workspace.org_id) : undefined);
      if (!orgId) throw new Error('Workspace has no ID');
      const scenarioResult = await call('inspect_scenarios', { org_id: orgId, list: {} });
      const scenarioObject = await choose(context, 'Choose a cfo.ai scenario (or skip)',
        Array.isArray(scenarioResult.scenarios) ? scenarioResult.scenarios.map(object) : [], v => String(v.display_name));
      if (!scenarioObject) return off('cfo.ai skipped: no scenario selected.');
      const scenario = text(scenarioObject.display_name);
      if (!scenario) throw new Error('Scenario has no name');
      const existing = context.config.budget.cfoai;
      const table = existing?.table ?? 'Tally agent budget';
      const detailTable = existing?.spendDetailTable ?? 'Tally spend detail';
      const budgetRow = existing?.budgetRow ?? 'Agent budget';
      const spendRow = existing?.spendRow ?? 'Agent spend';
      const remainingRow = existing?.remainingRow ?? 'Budget remaining';
      const tierSpendRows = Object.fromEntries(context.config.tiers.map(tier => [
        tier.name, existing?.tierSpendRows?.[tier.name] ?? `Tier spend - ${tier.name}`,
      ]));
      const runSpendRow = existing?.runSpendRow ?? 'Run spend - current';
      const cumulativeRunSpendRow = existing?.cumulativeRunSpendRow ?? 'Run spend - cumulative';
      const scope = { org_id: orgId, scenario };
      const inspect = async (): Promise<ObjectValue[]> => {
        const result = await call('inspect_table_blocks', { ...scope, list: { target: [table, detailTable] } });
        if (!Array.isArray(result.blocks)) throw new Error('Missing table discovery');
        return result.blocks.map(object);
      };
      let blocks = await inspect();
      const find = (name: string) => {
        const matches = blocks.filter(b => b.display_name === name);
        if (matches.length > 1) throw new Error('Ambiguous table');
        return matches[0];
      };
      const now = (this.options.now ?? (() => new Date()))();
      const month = cfoaiMonthColumn(now);
      const budgetRows = [budgetRow, spendRow, remainingRow];
      const detailRows = [...Object.values(tierSpendRows), runSpendRow, cumulativeRunSpendRow];
      const missing = [!find(table) ? table : null, !find(detailTable) ? detailTable : null].filter((x): x is string => x !== null);
      if (missing.length) {
        context.ui.print(`Create on page Tally in ${workspace.name}, scenario ${scenario}, monthly USD columns starting ${month}:`);
        if (missing.includes(table)) context.ui.print(`${table}: ${budgetRow} = $${context.config.budget.usd}; ${spendRow} = $0; ${remainingRow} = ${budgetRow} - ${spendRow} (formula).`);
        if (missing.includes(detailTable)) context.ui.print(`${detailTable}: ${detailRows.join(', ')} = $0 each.`);
        context.ui.print('Existing tables and spend are not reset. New tables get their own variables.');
        if (!await context.ui.confirm('Create these missing cfo.ai tables?')) return off('cfo.ai skipped: table creation declined.');
        const end = `${now.getUTCFullYear() + 1}-12-31`;
        for (const name of missing) {
          const rows = name === table ? budgetRows : detailRows;
          const create: ObjectValue = {
            name, page: 'Tally', columns: [{ time: 'MONTH' }],
            rows: rows.map(variable => ({ variable, new: true })),
            variables: rows.map(target => ({ target, currency: 'USD', format: 'CURRENCY' })),
            window: { start: `${month}-01`, end, granularity: 'MONTH' },
          };
          // Inputs apply only to the new table's current month; never reset an existing table.
          create.values = { columns: [month], rows: rows.filter(row => row !== remainingRow).map(row => [row, row === budgetRow ? context.config.budget.usd : 0]) };
          if (name === table) create.rows = [
            { variable: budgetRow, new: true }, { variable: spendRow, new: true },
            { variable: remainingRow, new: true, formula: `\`${budgetRow}\` - \`${spendRow}\`` },
          ];
          const receipt = await call('edit_table_blocks', { ...scope, create });
          if (receipt.status !== 'applied') throw new Error('Creation not applied');
        }
        blocks = await inspect();
      }
      const budgetBlock = find(table);
      const detailBlock = find(detailTable);
      for (const [block, rows] of [[budgetBlock, budgetRows], [detailBlock, detailRows]] as const) {
        if (!block) throw new Error('Created table not found');
        const layout = object(block.layout);
        const names = new Set(Array.isArray(layout.rows) ? layout.rows.map(row => object(row).display_name) : []);
        if (rows.some(row => !names.has(row))) throw new Error('Existing table lacks required rows');
        const columns = Array.isArray(layout.columns) ? layout.columns.map(object) : [];
        if (!columns.some(c => c.time === 'MONTH' || (c.grain === 'MONTH' && String(c.dimension).startsWith('Date')))) throw new Error('Table needs monthly Date columns');
      }
      const pageUrl = https(object(budgetBlock!.page).url);
      const tableUrl = https(budgetBlock!.url);
      const spendDetailTableUrl = https(detailBlock!.url);
      if (!pageUrl || !tableUrl || !spendDetailTableUrl) throw new Error('Missing discovered HTTPS table/page URL');
      const cfoai = { orgId, scenario, table, budgetRow, spendRow, remainingRow,
        spendDetailTable: detailTable, tierSpendRows, runSpendRow, cumulativeRunSpendRow,
        pageUrl, tableUrl, spendDetailTableUrl };
      // Verify the adapter can read the chosen budget before proposing budget.source=cfoai.
      const budgetClient = (this.options.client ?? createCfoaiClient)();
      const adapter = new CfoaiBudgetAdapter({ client: budgetClient, config: cfoai, now: () => now });
      try { await adapter.remainingNanos(); } finally { await budgetClient.close(); }
      return { enabled: true, state: { status: 'ok', detail: `cfo.ai configured for ${workspace.name}, ${scenario}.` },
        budget: { source: 'cfoai', usd: context.config.budget.usd, cfoai } };
    } catch {
      context.ui.print('cfo.ai setup could not be verified; using the local budget. You can rerun onboarding to retry; existing model data was not reset.');
      return off('cfo.ai setup incomplete; local budget selected.');
    } finally { await client.close().catch(() => undefined); }
  }
}

