export function backlogPath(config: TallyConfig, configPath: string): string | null {
  if (config.backlog.source !== 'file' || config.backlog.file === undefined) return null;
  return configRelative(configPath, config.backlog.file);
}

function defaultRunner(file: string, args: string[]) {
  return runCommand(file, args);
}

interface AoProjectResponse {
  project?: {
    config?: unknown;
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function quoteShell(value: string): string {
  return `'${value.replaceAll("'", "'\\''")}'`;
}

function withWorkerAutoMode(config: unknown): Record<string, unknown> {
  const base = isRecord(config) ? { ...config } : {};
  const worker = isRecord(base.worker) ? { ...base.worker } : {};
  const agentConfig = isRecord(worker.agentConfig) ? { ...worker.agentConfig } : {};
  agentConfig.permissions = 'auto';
  worker.agentConfig = agentConfig;
  base.worker = worker;
  return base;
}

function quoteJsonForShell(value: unknown): string {
  return quoteShell(JSON.stringify(value));
}

export function workerAutoModeFixCommand(projectId: string, projectConfig: unknown): string {
  const fixed = withWorkerAutoMode(projectConfig);
  return `ao project set-config ${projectId} --config-json ${quoteJsonForShell(fixed)}`;
}

export function workerPermissionMode(projectConfig: unknown): string | null {
  if (!isRecord(projectConfig)) return null;
  const worker = isRecord(projectConfig.worker) ? projectConfig.worker : {};
  const workerAgentConfig = isRecord(worker.agentConfig) ? worker.agentConfig : {};
  const workerPermission = workerAgentConfig.permissions;
  if (typeof workerPermission === 'string') return workerPermission;
  return null;
}

export interface WorkerPermissionCheck {
  ok: boolean;
  mode: string | null;
  detail: string;
  fix: string;
}

export function checkWorkerAutoMode(projectId: string, projectConfig: unknown): WorkerPermissionCheck {
  const mode = workerPermissionMode(projectConfig);
  const fix = workerAutoModeFixCommand(projectId, projectConfig);
  if (mode === 'auto') {
    return { ok: true, mode, detail: 'worker permission mode is auto', fix };
  }
  const label = mode ?? 'unset';
  return {
    ok: false,
    mode,
    detail: `worker permission mode is ${label}; unattended Tally workers can stall before setup, edits, tests, or commits`,
    fix,
  };
}

function postCreateCommands(projectConfig: unknown): string[] {
  if (!isRecord(projectConfig)) return [];
  const value = projectConfig.postCreate;
  if (Array.isArray(value)) return value.filter((item): item is string => typeof item === 'string');
  return [];
}

function withPostCreateCommand(config: unknown, command: string): Record<string, unknown> {
  const base = isRecord(config) ? { ...config } : {};
  const commands = postCreateCommands(base);
  base.postCreate = commands.includes(command) ? commands : [...commands, command];
  return base;
}

export function setupPostCreateFixCommand(projectId: string, projectConfig: unknown, setupCommand: string): string {
  return `ao project set-config ${projectId} --config-json ${quoteJsonForShell(withPostCreateCommand(projectConfig, setupCommand))}`;
}

export interface SetupPostCreateCheck {
  ok: boolean;
  detail: string;
  fix: string;
}

export function checkSetupPostCreate(projectId: string, projectConfig: unknown, setupCommand: string | undefined): SetupPostCreateCheck | null {
  if (!setupCommand) return null;
  const fix = setupPostCreateFixCommand(projectId, projectConfig, setupCommand);
  if (postCreateCommands(projectConfig).includes(setupCommand)) {
    return { ok: true, detail: `post-create runs setup command: ${setupCommand}`, fix };
  }
  return {
    ok: false,
    detail: `test.setupCommand is "${setupCommand}", but AO project postCreate does not run it before the worker starts`,
    fix,
  };
}

function sessionModeProblems(config: TallyConfig): string[] {
  return config.tiers.flatMap((tier, index) => {
    if (tier.sessionMode === 'tui') return [];
    const path = `tiers[${index}].sessionMode`;
    if (tier.sessionMode === 'chat') {
      return [`${path} is "chat"; real Tally workers need sessionMode: tui so unattended shell work does not route through chat approval prompts`];
    }
    return [`${path} is required for real runs; set sessionMode: tui after proving the harness can run unattended`];
  });
}

function parseAoProject(stdout: string): AoProjectResponse {
  return JSON.parse(stdout) as AoProjectResponse;
}

export async function validateRealRunConfig(config: TallyConfig, configPath: string, runner: PreflightRunner = defaultRunner): Promise<void> {
  if (runner === defaultRunner) runner = (file, args) => runCommand(file, args, { aoBin: config.repo.aoBin ? configRelative(configPath, config.repo.aoBin) : undefined });
  const problems: string[] = [];
  if (!config.repo.aoProject) problems.push('repo.aoProject is required for real runs so AO knows where to spawn workers');
  const resolvedRepo = repoPath(config, configPath);
  if (!existsSync(resolvedRepo)) problems.push(`repo.path does not exist: ${resolvedRepo}`);
  const resolvedBacklog = backlogPath(config, configPath);
  if (resolvedBacklog && !existsSync(resolvedBacklog)) problems.push(`backlog.file does not exist: ${resolvedBacklog}`);
  problems.push(...sessionModeProblems(config));
  if (config.repo.aoProject) {
    let project: AoProjectResponse | null = null;
    try {
      project = parseAoProject((await runner('ao', ['project', 'get', config.repo.aoProject, '--json'])).stdout);
    } catch (error) {
      if (error instanceof CommandError) throw error;
      problems.push(
        `repo.aoProject "${config.repo.aoProject}" is not registered in AO; fix: ao project add --path ${resolvedRepo} --id ${config.repo.aoProject}`,
      );
    }
    if (project) {
      const permission = checkWorkerAutoMode(config.repo.aoProject, project.project?.config);
      if (!permission.ok) {
        problems.push(`${permission.detail}; fix: ${permission.fix}`);
      }
      const setup = checkSetupPostCreate(config.repo.aoProject, project.project?.config, config.test.setupCommand);
      if (setup && !setup.ok) {
        problems.push(`${setup.detail}; fix: ${setup.fix}`);
      }
    }
  }
  if (problems.length > 0) throw new ConfigError(configPath, problems);
}
import { CommandError, runCommand } from '../adapters/command.js';
import { existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { checkCfoaiConnection } from '../adapters/cfoai.js';
import { loadConfig } from './config.js';
import { loadEnv } from './env.js';
import { checkSetupPostCreate, checkWorkerAutoMode } from './preflight.js';

export type DoctorStatus = 'connected' | 'missing' | 'broken';

export interface DoctorLine {
  product: string;
  status: DoctorStatus;
  detail: string;
  fix: string | null;
}

export type DoctorRunner = (file: string, args: string[], options?: { cwd?: string }) => Promise<{ stdout: string; stderr: string }>;

export interface DoctorOptions {
  runner?: DoctorRunner;
  env?: Record<string, string>;
  cfoaiCheck?: typeof checkCfoaiConnection;
  configPath?: string;
}

async function commandLine(product: string, runner: DoctorRunner, file: string, args: string[], fix: string): Promise<DoctorLine> {
  try {
    await runner(file, args);
    return { product, status: 'connected', detail: 'ok', fix: null };
  } catch (e) {
    const code = (e as { code?: unknown }).code;
    const status: DoctorStatus = code === 'ENOENT' ? 'missing' : 'broken';
    return { product, status, detail: e instanceof CommandError ? e.message : status === 'missing' ? `${file} not found` : `${file} failed`, fix: file === 'ao' && status === 'missing' ? 'set TALLY_AO_BIN to the installed AO executable path' : fix };
  }
}

async function aoWorkerModeLine(configPath: string, runner: DoctorRunner): Promise<DoctorLine | null> {
  if (!existsSync(configPath)) return null;
  const config = loadConfig(configPath);
  const projectId = config.repo.aoProject;
  if (!projectId) {
    return {
      product: 'AO worker auto mode',
      status: 'missing',
      detail: 'repo.aoProject is required before Tally can check worker permissions',
      fix: 'add repo.aoProject to tally.yaml',
    };
  }
  try {
    const output = await runner('ao', ['project', 'get', projectId, '--json']);
    const payload = JSON.parse(output.stdout) as { project?: { config?: unknown } };
    const check = checkWorkerAutoMode(projectId, payload.project?.config);
    return {
      product: 'AO worker auto mode',
      status: check.ok ? 'connected' : 'broken',
      detail: check.detail,
      fix: check.ok ? null : check.fix,
    };
  } catch (error) {
    if (error instanceof CommandError && error.code === 'ENOENT') return { product: 'AO worker auto mode', status: 'missing', detail: error.message, fix: 'set TALLY_AO_BIN to the installed AO executable path' };
    return {
      product: 'AO worker auto mode',
      status: 'missing',
      detail: `repo.aoProject "${projectId}" is not registered in AO`,
      fix: `ao project add --path ${config.repo.path} --id ${projectId}`,
    };
  }
}

async function aoSetupPostCreateLine(configPath: string, runner: DoctorRunner): Promise<DoctorLine | null> {
  if (!existsSync(configPath)) return null;
  const config = loadConfig(configPath);
  if (!config.test.setupCommand) return null;
  const projectId = config.repo.aoProject;
  if (!projectId) {
    return {
      product: 'AO setup post-create',
      status: 'missing',
      detail: 'repo.aoProject is required before Tally can check setup post-create',
      fix: 'add repo.aoProject to tally.yaml',
    };
  }
  try {
    const output = await runner('ao', ['project', 'get', projectId, '--json']);
    const payload = JSON.parse(output.stdout) as { project?: { config?: unknown } };
    const check = checkSetupPostCreate(projectId, payload.project?.config, config.test.setupCommand)!;
    return {
      product: 'AO setup post-create',
      status: check.ok ? 'connected' : 'broken',
      detail: check.detail,
      fix: check.ok ? null : check.fix,
    };
  } catch (error) {
    if (error instanceof CommandError && error.code === 'ENOENT') return { product: 'AO setup post-create', status: 'missing', detail: error.message, fix: 'set TALLY_AO_BIN to the installed AO executable path' };
    return {
      product: 'AO setup post-create',
      status: 'missing',
      detail: `repo.aoProject "${projectId}" is not registered in AO`,
      fix: `ao project add --path ${config.repo.path} --id ${projectId}`,
    };
  }
}

export async function runDoctor(options: DoctorOptions = {}): Promise<DoctorLine[]> {
  const config = options.configPath && existsSync(options.configPath) ? loadConfig(options.configPath) : null;
  const runner = options.runner ?? ((file, args, commandOptions) => runCommand(file, args, {
    ...commandOptions,
    aoBin: config?.repo.aoBin ? resolve(dirname(options.configPath!), config.repo.aoBin) : undefined,
  }));
  const env = options.env ?? { ...loadEnv(), ...process.env };
  const cfoaiCheck = options.cfoaiCheck ?? checkCfoaiConnection;
  const lines: DoctorLine[] = [];
  lines.push(await commandLine('AO daemon', runner, 'ao', ['status'], 'ao start'));
  if (options.configPath) {
    const workerMode = await aoWorkerModeLine(options.configPath, runner);
    if (workerMode) lines.push(workerMode);
    const setupPostCreate = await aoSetupPostCreateLine(options.configPath, runner);
    if (setupPostCreate) lines.push(setupPostCreate);
  }
  lines.push(await commandLine('GitHub CLI', runner, 'gh', ['auth', 'status'], 'gh auth login'));
  lines.push(await commandLine('Entire CLI', runner, 'entire', ['--version'], 'pipx install entire'));
  lines.push(await commandLine('Entire graph plugin', runner, 'entire', ['graph', '--help'], 'entire enable'));
  if (config?.integrations.entire) {
    const cwd = resolve(dirname(options.configPath!), config.repo.path);
    try {
      const output = await runner('entire', ['status', '--json'], { cwd });
      const enabled = JSON.parse(output.stdout).enabled === true;
      lines.push({ product: 'Entire repository', status: enabled ? 'connected' : 'missing', detail: enabled ? `Entire is enabled in ${cwd}` : `Entire is not enabled in ${cwd}`, fix: enabled ? null : `cd ${JSON.stringify(cwd)} && entire enable` });
    } catch (error) {
      lines.push({ product: 'Entire repository', status: 'broken', detail: error instanceof Error ? error.message : 'Entire status failed', fix: `cd ${JSON.stringify(cwd)} && entire enable` });
    }
  }
  lines.push(
    env.NEATLOGS_API_KEY
      ? { product: 'neatlogs key', status: 'connected', detail: 'NEATLOGS_API_KEY is set', fix: null }
      : {
          product: 'neatlogs key',
          status: 'missing',
          detail: 'NEATLOGS_API_KEY is missing from ~/.tally/.env',
          fix: "mkdir -p ~/.tally && printf 'NEATLOGS_API_KEY=...\\n' >> ~/.tally/.env",
        },
  );
  const cfoai = await cfoaiCheck();
  lines.push({
    product: 'cfo.ai',
    status: cfoai.status === 'ok' ? 'connected' : 'missing',
    detail: cfoai.detail ?? (cfoai.status === 'ok' ? 'Tally cached token works' : 'Tally cfo.ai token is missing or unusable'),
    fix: cfoai.status === 'ok' ? null : 'tally login cfoai',
  });
  return lines;
}

/**
 * The shared contract between the engine, the CFO agent and the dashboard.
 *
 * Every type here has a matching JSON Schema in this folder
 * (`*.schema.json`). Change both together and bump SCHEMA_VERSION when a
 * change is not backwards compatible.
 *
 * Money is stored as integer nanos of USD (1 USD = 1_000_000_000), the unit
 * the Agent Orchestrator usage endpoint reports. Config files use plain USD.
 */

export const SCHEMA_VERSION = 1;

export type TaskSize = 'small' | 'medium' | 'large';

/** Outcome of one attempt. `stopped` means the watcher killed it at its ceiling. */
export type AttemptResult = 'passed' | 'failed' | 'stopped' | 'error';

/** How the cost on a row was obtained. */
export type CostSource =
  /** tokens x list price from tally.yaml (the default, comparable across harnesses) */
  | 'list-price'
  /** the Agent Orchestrator's own estimate, used only when no list price is configured */
  | 'ao-estimate'
  /** a dry-run or demo attempt that spent nothing */
  | 'simulated';

/** How an escalated attempt received the earlier attempt's work. */
export type Handoff = 'none' | 'restart' | 'entire-handoff';

export interface TokenUsage {
  /** Input tokens billed at the full input price. Includes cache writes. */
  uncachedInput: number;
  /** Input tokens read from cache. */
  cachedInput: number;
  output: number;
  /** uncachedInput + cachedInput + output */
  total: number;
}

/** One row per attempt. A task that escalates has two rows. */
export interface LedgerRow {
  schemaVersion: 1;
  /** `${runId}:${taskId}:${attempt}` */
  attemptId: string;
  runId: string;
  taskId: string;
  taskTitle: string;
  /** 1 for the first attempt, 2 for the escalation. */
  attempt: number;
  size: TaskSize;
  /** Name of the tier in tally.yaml that ran this attempt. */
  tier: string;
  model: string;
  harness: string;
  /** Agent Orchestrator session id; null for simulated attempts. */
  sessionId: string | null;
  /** Native Entire/Codex session id, separate from the AO worker session. */
  entireSessionId?: string | null;
  branch: string | null;
  /** Effective comparison base at attempt start, including an inherited failed branch. */
  baseCommit?: string | null;
  tokens: TokenUsage;
  estimatedCostNanos: number;
  costSource: CostSource;
  /** Snapshot of the configured rates used for this attempt, not a retrospective repricing. */
  price?: TierPrice;
  /** Source, verification status and limitations of the cost estimate. */
  priceNote?: string;
  /** Spend ceiling that applied to this attempt. */
  ceilingNanos: number;
  result: AttemptResult;
  /** Short explanation of the result, e.g. "2 tests failing" or "ceiling crossed". */
  resultReason: string | null;
  scopeWarnings?: string[];
  /** attemptId of the attempt this one took over from, if it is an escalation. */
  escalatedFrom: string | null;
  handoff: Handoff;
  /** Exact context included in the worker prompt; null for an initial attempt. */
  handoffText?: string | null;
  prUrl: string | null;
  /** Neatlogs trace id for the routing or escalation decision that created this attempt. */
  traceId: string | null;
  traceUrl: string | null;
  /** Verified worker-session trace, distinct from the CFO decision trace. */
  workerTraceId?: string | null;
  workerTraceUrl?: string | null;
  checkpointId: string | null;
  checkpointUrl: string | null;
  /** The CFO agent's one-sentence reason for choosing this tier. */
  decision: string;
  startedAt: string;
  endedAt: string | null;
}

export type Ledger = LedgerRow[];

export type RunMode = 'tally' | 'baseline';
export type RunStatus = 'running' | 'finished' | 'interrupted';
export type TaskStatus = 'pending' | 'running' | 'passed' | 'failed' | 'skipped';
export type BudgetSource = 'config' | 'cfoai';

export type IntegrationName = 'neatlogs' | 'entire' | 'cfoai' | 'github' | 'slack';
/** `off` = switched off in config, `missing` = on but not usable, `error` = failed during the run. */
export type IntegrationStatus = 'ok' | 'off' | 'missing' | 'error';

export interface IntegrationState {
  status: IntegrationStatus;
  /** What Tally does instead, or what went wrong. */
  detail: string | null;
}

export interface TaskImpact {
  source: 'entire-graph' | 'code-search' | 'scripted' | 'none';
  query: string;
  nodes: Array<{ id: string; kind: 'target' | 'caller' | 'coChange' | 'test'; symbol?: string; weight?: number }>;
  edges: Array<{ from: string; to: string; kind: 'calls' | 'changesWith' | 'tests' }>;
  totals: { filesTouched: number; dependents: number; testsPresent: boolean; nodes: number; edges: number };
  truncated: boolean;
}

export interface TaskState {
  taskId: string;
  title: string;
  issueNumber: number | null;
  issueUrl: string | null;
  /** null until the sizer has run. */
  size: TaskSize | null;
  impact?: TaskImpact;
  changedFiles?: string[];
  status: TaskStatus;
  /** Why a task is failed or skipped, e.g. "not started: no budget". */
  statusReason: string | null;
  attempts: number;
  /** Tier of the latest attempt. */
  tier: string | null;
  model: string | null;
  spentNanos: number;
  escalated: boolean;
  prUrl: string | null;
}

export interface RunState {
  schemaVersion: 1;
  runId: string;
  mode: RunMode;
  repeat?: number;
  /** True when workers were simulated and nothing was spent. */
  dryRun: boolean;
  status: RunStatus;
  /** The repository the run worked on, as written in tally.yaml. */
  repo: string;
  backlog?: { source: 'github-issues' | 'file'; issueLabel?: string; file?: string };
  /** Commit every task branched from. */
  baseCommit: string | null;
  startedAt: string;
  updatedAt: string;
  endedAt: string | null;
  budget: {
    source: BudgetSource;
    /** Origin of this run's effective limit, distinct from spend accounting. */
    limitSource?: BudgetSource | 'cli';
    systemOfRecord?: 'ledger' | 'cfoai';
    cfoai?: { pageUrl?: string; tableUrl?: string };
    limitNanos: number;
    /** Always the sum of estimatedCostNanos over this run's ledger rows. */
    spentNanos: number;
  };
  tasks: TaskState[];
  integrations: Record<IntegrationName, IntegrationState>;
}

export interface TierPrice {
  inputUsdPerMTok: number;
  cachedInputUsdPerMTok: number;
  outputUsdPerMTok: number;
}

export interface Tier {
  /** Free-form label, e.g. cheap / middle / top. Referenced by ledger rows. */
  name: string;
  /** Any harness the Agent Orchestrator supports. */
  harness: string;
  /** AO session interface for real workers. TUI is required for unattended shell work. */
  sessionMode?: 'chat' | 'tui';
  /** Model id as the provider names it, e.g. a gateway alias such as nova-lite. */
  model: string;
  /** Who serves and bills the model, e.g. anthropic, openai, litellm, bedrock. */
  provider: string;
  /** Configured base list price used for normalized token-cost estimates. */
  price: TierPrice;
  /** Optional operator-supplied provenance; recorded alongside Tally's verification. */
  priceNote?: string;
  /** Share of the size ceiling this tier may spend, in (0, 1]. */
  ceilingFraction: number;
}

export interface TallyConfig {
  version: 1;
  repo: {
    /** Local checkout, relative to tally.yaml. */
    path: string;
    /** owner/name on GitHub, when issues or PRs are used. */
    slug?: string;
    baseBranch: string;
    /** Agent Orchestrator project id, when it differs from the default for the checkout. */
    aoProject?: string;
    /** AO CLI fallback path, relative to tally.yaml; PATH and TALLY_AO_BIN take precedence. */
    aoBin?: string;
    /** Let the worker push/open its own PR. Defaults to false; Tally publishes after verification. */
    workerPublishesPr?: boolean;
    blockOutOfScopeChanges?: boolean;
  };
  test: {
    /** Run in the task's checkout; exit code 0 means the task passed. */
    command: string;
    /** Run once per fresh checkout before the test command. */
    setupCommand?: string;
    timeoutSec?: number;
  };
  backlog: {
    source: 'github-issues' | 'file';
    issueLabel?: string;
    /** YAML backlog file, relative to tally.yaml. */
    file?: string;
  };
  /** Ordered from cheapest to strongest. Escalation moves one step right. */
  tiers: Tier[];
  ceilings: {
    /** What the strongest tier may spend on a task of each size, in USD. */
    bySizeUsd: Record<TaskSize, number>;
  };
  budget: {
    source: BudgetSource;
    /** The budget, or the fallback when the cfo.ai scenario cannot be read. */
    usd: number;
    cfoai?: {
      /** cfo.ai org/workspace id, e.g. "<cfoai-org-id>". */
      orgId?: string;
      scenario?: string;
      table?: string;
      budgetRow?: string;
      spendRow?: string;
      remainingRow?: string;
      spendDetailTable?: string;
      spendDetailTableUrl?: string;
      tierSpendRows?: Record<string, string>;
      runSpendRow?: string;
      cumulativeRunSpendRow?: string;
      tableUrl?: string;
      pageUrl?: string;
      serverUrl?: string;
    };
  };
  concurrency?: number;
  entire?: {
    /** Off by default: generation may export session content to Entire's summary provider. */
    generatedSummaries?: boolean;
  };
  integrations: Record<'neatlogs' | 'entire' | 'cfoai' | 'slack', boolean>;
}
import { existsSync, readFileSync } from 'node:fs';
import { parse as parseYaml } from 'yaml';
import { validateConfig, type TallyConfig } from '../schema/index.js';

export class ConfigError extends Error {
  constructor(
    readonly path: string,
    readonly problems: string[],
  ) {
    super(`${path}: ${problems.join('; ')}`);
    this.name = 'ConfigError';
  }
}

/** Reads and validates tally.yaml. Everything about the target repository comes from here. */
export function loadConfig(path: string): TallyConfig {
  if (!existsSync(path)) throw new ConfigError(path, ['file not found; run `tally init` to create it']);
  let parsed: unknown;
  try {
    parsed = parseYaml(readFileSync(path, 'utf8'));
  } catch (e) {
    throw new ConfigError(path, [`not valid YAML: ${(e as Error).message}`]);
  }
  const result = validateConfig(parsed);
  if (!result.ok) throw new ConfigError(path, result.errors);
  return parsed as TallyConfig;
}
import { existsSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { parse as parseYaml } from 'yaml';
import { validateChangedFiles, validateTaskImpact, type AttemptResult, type Handoff, type TaskImpact, type TaskSize, type TallyConfig, type TokenUsage } from '../schema/index.js';

export interface ScriptedAttempt {
  tier?: string;
  result: AttemptResult;
  resultReason: string | null;
  tokens: TokenUsage;
  handoff: Exclude<Handoff, 'none'> | null;
  decision: string | null;
  changedFiles?: string[];
}

export interface BacklogTask {
  taskId: string;
  title: string;
  body: string;
  issueNumber: number | null;
  issueUrl: string | null;
  size: TaskSize;
  /** Scripted attempt outcomes for dry runs. Defaults to one passed attempt. */
  outcomes: AttemptResult[];
  /** Richer dry-run script, when the backlog provides one. */
  scriptedAttempts?: ScriptedAttempt[];
  /** Deliberate first-attempt ceiling for demos; escalation uses normal tier ceilings. */
