 81	  async configure(context: OnboardingContext): Promise<OnboardingResult> {
 82	    const off = (detail: string): OnboardingResult => {
 83	      context.ui.print(`${detail} Entire will be off: sizing uses code search and escalation has no Entire checkpoint handoff.`);
 84	      return { enabled: false, state: { status: 'off', detail } };
 85	    };
 86	    const connection = await this.connect(context);
 87	    if (connection.status !== 'ok') return off(connection.detail ?? 'Entire skipped.');
 88	    try {
 89	      const root = await this.run('git', ['rev-parse', '--show-toplevel']);
 90	      if (resolve(root) !== this.cwd) return off('Entire setup needs the target repository root; no capture settings were changed.');
 91	      let status = await this.status();
 92	      const agents = new Set(Array.isArray(status.agents) ? status.agents.map(a => String(a).toLowerCase().replace(/ /g, '-')) : []);
 93	      const required = [...new Set(context.config.tiers.map(t => t.harness))].filter(a => a === 'codex' || a === 'claude-code');
 94	      if (status.enabled !== true || required.some(agent => !agents.has(agent))) {
 95	        // A dirty checkout may contain unrelated or pre-existing settings changes. Never stage them.
 96	        if (await this.run('git', ['status', '--porcelain'])) return off('Entire capture setup needs a clean checkout so existing edits remain untouched.');
 97	        context.ui.print(`Enable Entire capture in ${this.cwd}. It may add or update: ${SETTINGS_FILES.join(', ')} and local Git hooks.`);
 98	        context.ui.print('Settings must be committed to the default branch for worker worktrees to inherit them. Codex hooks need trusting once via /hooks. Telemetry stays off; no summaries are generated.');
 99	        if (!await context.ui.confirm('Enable these repository capture settings? No commit or push yet.')) return off('Entire repository setup declined.');
100	        const primary = required[0] ?? 'claude-code';
101	        if (status.enabled !== true) {
102	          await this.run('entire', ['enable', '--agent', primary, '--telemetry=false', '--project', '--no-init-repo', '--skip-initial-commit']);
103	          agents.add(primary);
104	        }
105	        for (const agent of required) if (!agents.has(agent)) await this.run('entire', ['agent', 'add', agent]);
106	        status = await this.status();
107	        if (status.enabled !== true) throw new Error('Capture was not enabled');
108	        const lines = (await this.run('git', ['status', '--porcelain', '--untracked-files=all'])).split('\n').filter(Boolean);
109	        const files = lines.map(line => line.slice(3));
110	        if (files.some(file => !SETTINGS_FILES.includes(file))) return off('Entire generated unexpected files; review them before publishing. Nothing was committed or pushed.');
111	        if (files.length) {
112	          context.ui.print(`Generated settings to publish: ${files.join(', ')}.`);
113	          const branch = await this.run('git', ['branch', '--show-current']);
114	          const remoteHead = await this.run('git', ['symbolic-ref', '--short', 'refs/remotes/origin/HEAD']).catch(() => '');
115	          const defaultBranch = remoteHead.startsWith('origin/') ? remoteHead.slice('origin/'.length) : null;
116	          if (!defaultBranch || branch !== defaultBranch) return off('Capture is enabled locally, but settings are not on the default branch; publish them through your normal review process, then rerun init.');
117	          const local = await this.run('git', ['rev-parse', 'HEAD']);
118	          const remote = await this.run('git', ['rev-parse', `refs/remotes/origin/${defaultBranch}`]);
119	          if (local !== remote) return off('Default branch has unpublished commits; Entire setup will not publish unrelated work.');
120	          if (!await context.ui.confirm(`Commit only these settings and push to origin/${defaultBranch}? Entire Git hooks may also publish checkpoint/session evidence.`)) return off('Publishing settings declined; local capture settings remain for review.');
121	          if (await this.run('git', ['branch', '--show-current']) !== defaultBranch || await this.run('git', ['rev-parse', 'HEAD']) !== local) {
122	            return off('Checkout moved while awaiting approval; no settings were committed or pushed.');
123	          }
124	          await this.run('git', ['add', '--', ...files]);
125	          await this.run('git', ['commit', '-m', 'chore: enable Entire capture for Tally workers', '--', ...files]);
126	          const setupCommit = await this.run('git', ['rev-parse', 'HEAD']);
127	          if (await this.run('git', ['rev-parse', `${setupCommit}^`]) !== local) return off('Setup commit has an unexpected base; no push was attempted.');
128	          await this.run('git', ['push', 'origin', `${setupCommit}:refs/heads/${defaultBranch}`]);
129	        }
130	      }
131	      if (required.includes('codex')) context.ui.print('In Codex started inside this repository, open /hooks and trust the Entire capture hooks once. Tally cannot approve them for you.');
132	      // Local enablement alone is insufficient: future workers inherit the default-branch files.
133	      const pending = await this.run('git', ['status', '--porcelain', '--', ...SETTINGS_FILES]);
134	      if (pending) return off('Capture settings are still uncommitted; Entire remains off until they are published on the default branch.');
135	      const published = json(await this.run('git', ['show', 'refs/remotes/origin/HEAD:.entire/settings.json']));
136	      if (published.enabled !== true) return off('Entire capture is not enabled on the remote default branch yet.');
137	      for (const agent of required) {
138	        const file = agent === 'codex' ? '.codex/hooks.json' : '.claude/settings.json';
139	        const settings = await this.run('git', ['show', `refs/remotes/origin/HEAD:${file}`]);
140	        if (!/\bentire\s+hooks\b/.test(settings)) return off(`The default branch has no Entire ${agent} hooks yet.`);
141	      }
142	      if (required.includes('codex') && !await context.ui.confirm('Have you trusted the Entire hooks via /hooks in Codex for this repository?')) {
143	        return off('Codex hook trust is not confirmed; no worker was started.');
144	      }
145	      return { enabled: true, state: { status: 'ok', detail: 'Entire login, graph and repository capture configured; generated summaries remain opt-in and off by default.' } };
146	    } catch { return off('Entire setup could not be verified. Any generated files remain for review; no further changes were attempted.'); }
147	  }
