118	export class GitWorktreeResolver implements WorktreePort {
119	  async commitWorkInProgress(repoPath: string, branch: string): Promise<string | null> {
120	    const cwd = await this.checkoutPathFor(repoPath, branch);
121	    if (!cwd) return null;
122	    const status = await execFileAsync('git', ['status', '--porcelain'], { cwd });
123	    if (!status.stdout.trim()) return null;
124	    await execFileAsync('git', ['add', '-A'], { cwd });
125	    await execFileAsync('git', ['commit', '-m', 'wip: preserve Tally ceiling-stopped task edits'], { cwd });
126	    return this.commitFor(repoPath, branch);
127	  }
128	  async commitFor(repoPath: string, branch: string): Promise<string | null> {
129	    const { stdout } = await execFileAsync('git', ['rev-parse', '--verify', '--end-of-options', `${branch}^{commit}`], { cwd: repoPath });
130	    return stdout.trim();
131	  }
132	  async checkoutPathFor(repoPath: string, branch: string): Promise<string | null> {
133	    const { stdout } = await execFileAsync('git', ['worktree', 'list', '--porcelain'], { cwd: repoPath });
134	    let worktree: string | null = null;
135	    for (const line of stdout.split('\n')) {
136	      if (line.startsWith('worktree ')) {
137	        worktree = line.slice('worktree '.length);
138	        continue;
139	      }
140	      if (line === `branch refs/heads/${branch}` || line === `branch refs/remotes/origin/${branch}`) return worktree;
141	    }
142	    return null;
143	  }
144	}
