176	  const trace = hasPort(overrides, 'trace') ? overrides.trace : config.integrations.neatlogs ? new NeatlogsTraceAdapter() : undefined;
177	  const cfoai = hasPort(overrides, 'cfoai')
178	    ? overrides.cfoai
179	    : config.integrations.cfoai || config.budget.source === 'cfoai'
180	      ? new CfoaiBudgetAdapter({ config: config.budget.cfoai })
181	      : undefined;
182	  const entireCheckpoints =
183	    config.integrations.entire && (!hasPort(overrides, 'handoff') || !hasPort(overrides, 'checkpoints'))
184	      ? new EntireCheckpointAdapter({ repoPath, generatedSummaries: config.entire?.generatedSummaries })
185	      : undefined;
186	  const handoff = overrides.handoff ?? entireCheckpoints;
187	  const checkpoints = overrides.checkpoints ?? entireCheckpoints;
188	  const recall = overrides.recall ?? (config.integrations.entire ? new EntireCheckpointRecallAdapter({ repoPath }) : undefined);
189	  return {
190	    ...(hasPort(overrides, 'workerTraceDrain') ? { workerTraceDrain: overrides.workerTraceDrain } : config.integrations.neatlogs && !hasPort(overrides, 'trace') ? { workerTraceDrain: new NeatlogsWorkerSpoolAdapter() } : {}),
