192	    intake: overrides.intake ?? new ConfigBacklogIntake(),
193	    signals: overrides.signals ?? (config.integrations.entire ? new EntireSizingAdapter({ repoPath }) : nullSignals),
194	    worker: overrides.worker ?? ao,
