416	async function runSingleAttempt(input: {
417	  runId: string;
418	  task: BacklogTask;
419	  attempt: number;
420	  tier: Tier;
421	  ceilingNanos: number | null;
422	  decision: string;
423	  escalatedFrom: string | null;
424	  handoff: LedgerRow['handoff'];
425	  handoffSummary: string | null;
