433	  requiredBaseCommit?: string;
434	  continueBranch?: string | null;
435	  continueSessionId?: string | null;
436	  onChangedFiles?: (files: string[]) => void;
437	  onStartupError?: (row: LedgerRow) => Promise<void>;
438	  onProgress?: (costNanos: number) => void;
439	  retrySuffix?: string;
440	}): Promise<LedgerRow> {
441	  const startedAt = input.now().toISOString();
442	  const repoPath = resolve(dirname(input.configPath), input.config.repo.path);
443	  const attemptBase = input.requiredBaseCommit ?? (input.dryRun ? null : await input.ports.worktrees.commitFor?.(repoPath, input.continueBranch ?? input.config.repo.baseBranch).catch(() => null) ?? input.baseCommit ?? null);
