453	    prompt: promptFor(input.task, input.config, input.tier, input.handoffSummary, input.runId, input.attempt),
454	    aoProject: input.config.repo.aoProject,
455	    continueBranch: input.continueBranch,
456	    continueSessionId: input.continueSessionId,
457	  });
