459	  let ceilingStopStarted = false;
460	  input.onProgress?.(0);
461	  const reportUsage = (value: LiveUsage | null) => {
462	    if (value) input.onProgress?.(checkCeiling(value, { sessionId: started.sessionId, tier: input.tier, ceilingNanos: null }).costNanos);
463	    else input.onProgress?.(0);
464	    return value;
