466	  const sourceUsage = input.ports.usage as FinalUsagePort;
467	  const usage: FinalUsagePort = {
468	    usageFor: async (id) => reportUsage(await sourceUsage.usageFor(id)),
469	    settledUsageFor: async (id) => reportUsage(await (sourceUsage.settledUsageFor?.(id) ?? sourceUsage.usageFor(id))),
470	  };
471	  const watcher = new CeilingWatcher({ usage, sessions: {
472	    stop: async (sessionId, reason) => {
473	      ceilingStopStarted = true;
474	      await input.ports.sessions.stop(sessionId, reason);
475	    },
476	  }, trace: input.ports.trace });
477	  const abort = new AbortController();
478	  const watched = watcher.watch(
479	    { sessionId: started.sessionId, tier: input.tier, ceilingNanos: input.ceilingNanos },
480	    { signal: abort.signal, intervalMs: input.dryRun ? 1 : 5000 },
481	  );
482	  const worker = input.ports.worker.wait(started.sessionId, { timeoutMs: input.config.test.timeoutSec ? input.config.test.timeoutSec * 1000 : undefined });
483	  let result: AttemptResult = 'error';
484	  let resultReason: string | null = null;
485	  let workerResult: WorkerResult | null = null;
486	  let tokens: TokenUsage | null = null;
487	  let estimatedCostNanos = 0;
488	  let costSource: LedgerRow['costSource'] = 'list-price';
489	  let prUrl: string | null = null;
490	  let checkpointId: string | null = null;
491	  let checkpointUrl: string | null = null;
492	  let scopeWarnings: string[] = [];
493	  let entireSessionId: string | null = null;
494	  let workerTraceId: string | null = null;
495	  let resolvedCheckoutPath: string | null = null;
496	
497	  try {
498	  let first = await Promise.race([watched.then((verdict) => ({ kind: 'watch' as const, verdict })), worker.then((result) => ({ kind: 'worker' as const, result }))]);
499	  // Killing can resolve the worker poll before the watcher records its stop verdict.
500	  if (first.kind === 'worker' && ceilingStopStarted) first = { kind: 'watch', verdict: await watched };
501	  if (first.kind === 'watch' && first.verdict.action === 'stop') {
502	    stopped = first.verdict.stopped;
503	    abort.abort();
504	    if (!input.dryRun) workerResult = await worker;
505	    result = 'stopped';
506	    resultReason = first.verdict.reason;
507	    tokens = first.verdict.tokens;
508	    estimatedCostNanos = first.verdict.costNanos;
509	    costSource = input.dryRun ? 'simulated' : first.verdict.costSource;
510	    if (!input.dryRun) {
511	      const branch = workerResult?.branch ?? started.branch;
512	      const wip = branch ? await input.ports.worktrees.commitWorkInProgress?.(repoPath, branch) : null;
513	      resultReason += wip ? `; work in progress committed as ${wip}` : '; stopped before any edits; next attempt starts clean';
514	    }
515	  } else {
516	    abort.abort();
517	    workerResult = first.kind === 'worker' ? first.result : await worker;
518	    const completionPort = usage;
519	    const completionUsage = input.dryRun ? null : await (completionPort.settledUsageFor?.(started.sessionId) ?? completionPort.usageFor(started.sessionId));
520	    if (!input.dryRun && (workerResult.status === 'never_started' || ((workerResult.status === 'idle' || workerResult.status === 'terminated') && !(completionUsage?.tokens.total)))) {
521	      result = 'error';
522	      resultReason = 'worker never started';
523	    } else if (workerResult.status === 'experiment_stop') {
524	      result = 'stopped';
525	      resultReason = workerResult.resultReason ?? 'stopped: experiment cap reached';
526	    } else if (workerResult.status === 'needs_input' || workerResult.status === 'timeout') {
527	      result = 'error';
528	      resultReason = workerResult.resultReason ?? (workerResult.status === 'timeout' ? 'worker exceeded wall-clock limit' : 'worker asked for input');
529	    } else {
530	      let checkoutPath = workerResult.checkoutPath ?? started.checkoutPath;
531	      const branch = workerResult.branch ?? started.branch;
532	      if (!input.dryRun && !checkoutPath && branch) {
533	        checkoutPath = await input.ports.worktrees.checkoutPathFor(resolve(dirname(input.configPath), input.config.repo.path), branch);
534	      }
535	      resolvedCheckoutPath = checkoutPath;
536	      if (!input.dryRun && (!checkoutPath || !branch)) {
537	        result = 'error';
538	        resultReason = 'could not locate worker checkout';
539	      } else if (!input.dryRun && (await input.ports.publisher.commitsAhead({ checkoutPath: checkoutPath!, branch: branch!, config: input.config })) <= 0) {
540	        result = 'failed';
541	        resultReason = 'no changes made';
542	      } else {
543	        const verification = await input.ports.verifier.verify({
544	          checkoutPath,
545	          branch,
546	          repoPath: resolve(dirname(input.configPath), input.config.repo.path),
547	          config: input.config,
548	        });
549	        result = verification.passed ? 'passed' : 'failed';
550	        resultReason = verification.reason;
551	        if (verification.passed && !input.dryRun) {
552	          scopeWarnings = outOfScopeFiles(input.task, await input.ports.publisher.changedFiles({ checkoutPath: checkoutPath!, branch: branch!, config: input.config, baseCommit: attemptBase }));
553	          if (scopeWarnings.length && input.config.repo.blockOutOfScopeChanges) {
554	            result = 'error';
555	            resultReason = `out-of-scope changes: ${scopeWarnings.join(', ')}`;
556	          } else if (input.config.repo.workerPublishesPr) {
557	            prUrl = workerResult.prUrl;
558	            if (!prUrl) {
559	              result = 'failed';
560	              resultReason = 'worker finished without opening a PR';
561	            }
562	          } else {
563	            try {
564	              prUrl = await input.ports.publisher.publishPr({
565	                checkoutPath: checkoutPath!,
566	                branch: branch!,
567	                config: input.config,
568	                task: input.task,
569	                runId: input.runId,
570	                attempt: input.attempt,
571	                scopeWarnings,
572	              });
573	            } catch (error) {
574	              result = 'failed';
575	              const message = error instanceof Error ? error.message : String(error);
576	              resultReason = `PR publish failed: ${message}`;
577	            }
578	          }
579	        }
580	      }
581	    }
582	  }
583	  if (!input.dryRun && input.ports.checkpoints) {
584	    const branch = workerResult?.branch ?? started.branch;
585	    const checkoutPath = resolvedCheckoutPath ?? workerResult?.checkoutPath ?? started.checkoutPath ?? (branch
586	      ? await input.ports.worktrees.checkoutPathFor(resolve(dirname(input.configPath), input.config.repo.path), branch).catch(() => null)
587	      : null);
588	    try {
589	      const checkpoint = await input.ports.checkpoints.checkpointFor({ sessionId: started.sessionId, branch, checkoutPath });
590	      checkpointId = checkpoint?.checkpointId ?? null;
591	      checkpointUrl = checkpoint?.checkpointUrl ?? null;
592	      entireSessionId = checkpoint?.entireSessionId ?? null;
593	    } catch {
594	      checkpointId = null;
595	      checkpointUrl = null;
596	    }
597	    if (!entireSessionId) {
598	      entireSessionId = await input.ports.checkpoints.sessionIdFor?.({ sessionId: started.sessionId, branch, checkoutPath }).catch(() => null) ?? null;
599	    }
600	  }
601	  } catch (error) {
602	    result = 'error';
603	    resultReason = error instanceof Error ? error.message : String(error);
604	  } finally {
605	    abort.abort();
606	    if (!stopped) {
607	      try {
608	        await input.ports.sessions.stop(started.sessionId, `Tally attempt finished: ${result}`);
609	      } catch (error) {
610	        throw new Error(`could not close worker ${started.sessionId}: ${error instanceof Error ? error.message : String(error)}`);
611	      }
612	    }
613	    await watched;
614	  }
615	  const usagePort = usage;
616	  const finalUsage = usagePort.settledUsageFor ? await usagePort.settledUsageFor(started.sessionId) : await usagePort.usageFor(started.sessionId);
617	  if (finalUsage) {
618	    const finalCheck = checkCeiling(finalUsage, { sessionId: started.sessionId, tier: input.tier, ceilingNanos: input.ceilingNanos });
619	    tokens = finalCheck.tokens;
620	    estimatedCostNanos = finalCheck.costNanos;
621	    costSource = input.dryRun ? 'simulated' : finalCheck.costSource;
622	  }
623	  if (!input.dryRun && input.config.integrations.neatlogs && input.tier.harness === 'codex') {
624	    const branch = workerResult?.branch ?? started.branch;
625	    const checkoutPath = resolvedCheckoutPath ?? workerResult?.checkoutPath ?? started.checkoutPath ?? (branch
626	      ? await input.ports.worktrees.checkoutPathFor(resolve(dirname(input.configPath), input.config.repo.path), branch).catch(() => null) : null);
627	    await input.ports.workerTraceDrain?.drainWorker({ checkoutPath, entireSessionId }).catch(() => {});
628	    if (entireSessionId) workerTraceId = await input.ports.workerTraceReader?.verifyFor({
629	      runId: input.runId, taskId: input.task.taskId, attempt: input.attempt, nativeSessionId: entireSessionId,
630	    }).catch(() => null) ?? null;
631	  }
632	
633	  if (!input.dryRun && input.onChangedFiles) {
634	    const branch = workerResult?.branch ?? started.branch;
635	    if (branch) {
636	      // AO removes the worker worktree on close; its branch survives in the shared repository.
637	      const files = await input.ports.publisher.changedFiles({ checkoutPath: repoPath, branch, config: input.config, baseCommit: attemptBase }).catch(() => null);
638	      if (files !== null) input.onChangedFiles(files);
639	    }
640	  }
641	  if (input.dryRun && input.onChangedFiles && input.ports.worker.changedFilesFor) {
642	    const files = await input.ports.worker.changedFilesFor(started.sessionId);
643	    if (files !== null) input.onChangedFiles(files);
644	  }
645	
646	  return {
647	    schemaVersion: SCHEMA_VERSION,
648	    attemptId: attemptId(input.runId, input.task.taskId, input.attempt) + (input.retrySuffix ?? ''),
649	    runId: input.runId,
650	    taskId: input.task.taskId,
651	    taskTitle: input.task.title,
652	    attempt: input.attempt,
653	    size: input.task.size,
654	    tier: input.tier.name,
655	    model: input.tier.model,
656	    harness: input.tier.harness,
657	    sessionId: started.sessionId,
658	    entireSessionId,
659	    branch: input.dryRun ? null : (workerResult?.branch ?? started.branch),
660	    baseCommit: attemptBase,
661	    tokens: tokens ?? zeroTokens(),
662	    estimatedCostNanos,
663	    costSource,
664	    price: { ...input.tier.price },
665	    priceNote: `${input.dryRun ? 'Simulated usage; no spend. ' : ''}${tierPriceNote(input.tier)}`,
666	    ceilingNanos: input.ceilingNanos ?? 0,
667	    result,
668	    resultReason,
669	    scopeWarnings,
670	    escalatedFrom: input.escalatedFrom,
671	    handoff: input.handoff,
672	    handoffText: input.handoffSummary,
673	    prUrl: input.dryRun ? null : prUrl,
674	    traceId: input.traceId,
675	    traceUrl: null,
676	    workerTraceId,
677	    workerTraceUrl: null,
678	    checkpointId,
679	    checkpointUrl,
680	    decision: input.decision,
681	    startedAt,
682	    endedAt: input.now().toISOString(),
683	  };
684	}
