316	  async writeCumulativeActualSpend(runSpendNanos: number): Promise<void> {
317	    await this.ensureReady();
318	    try {
319	      if (this.runBaseSpendNanos === null) this.runBaseSpendNanos = await this.currentSpendNanos();
320	      const total = this.runBaseSpendNanos + runSpendNanos;
321	      const usd = Number(nanosToUsd(total).toFixed(9));
322	      const result = await this.client.callTool('edit_table_blocks', {
323	        ...this.scopeArgs(),
324	        update: {
325	          target: this.config.table,
326	          values: { columns: [this.monthColumn()], rows: [[this.config.spendRow, usd]] },
327	        },
328	      });
329	      if (!successfulEdit(result)) {
330	        throw new Error('cfo.ai did not apply the spend update');
331	      }
332	      const readBack = usdToNanos(await this.readUsd(this.config.spendRow));
333	      if (Math.abs(readBack - total) > 1) {
334	        throw new Error('cfo.ai spend read-back did not match the applied update');
335	      }
336	    } catch (e) {
337	      this.statusState = { status: 'error', detail: `write failed: ${(e as Error).message}; actual spend is retained in the run CSV fallback.` };
