342	  async writeSpendDetail(input: CfoaiSpendDetailInput): Promise<CfoaiSpendDetailResult> {
343	    await this.ensureReady();
344	    const runTotals = new Map<string, number>();
345	    const skippedTiers = new Set<string>();
346	    for (const attempt of input.attempts) {
347	      const row = this.config.tierSpendRows[attempt.tier];
348	      if (!row) {
349	        skippedTiers.add(attempt.tier);
350	        continue;
351	      }
352	      runTotals.set(row, (runTotals.get(row) ?? 0) + attempt.costNanos);
353	    }
354	    const mappedRows = [...new Set(Object.values(this.config.tierSpendRows))];
355	    if (this.baseDetailSpendNanos === null) {
356	      await this.loadBaseDetailSpend(mappedRows);
357	    }
358	    const updates = new Map<string, number>();
359	    for (const row of mappedRows) {
360	      updates.set(row, this.baseDetailSpendNanos!.get(row) ?? 0);
361	    }
362	    for (const [row, runSpend] of runTotals) {
363	      updates.set(row, (updates.get(row) ?? 0) + runSpend);
364	    }
365	    updates.set(this.config.runSpendRow, input.cumulativeRunSpendNanos);
366	    updates.set(this.config.cumulativeRunSpendRow, (this.runBaseSpendNanos ?? (await this.currentSpendNanos())) + input.cumulativeRunSpendNanos);
367	
368	    await this.writeRows(this.config.spendDetailTable, updates);
369	    await this.verifyRows(this.config.spendDetailTable, updates);
370	    await this.verifyAgentSpendMatchesTierRows(mappedRows, skippedTiers.size === 0);
371	
372	    const notes: string[] = [];
373	    if (skippedTiers.size > 0) notes.push(`Skipped cfo.ai spend detail for unmapped tiers: ${[...skippedTiers].join(', ')}.`);
374	    if (this.seededDetailGapNanos > 0) notes.push(`Seeded ${formatUsd(this.seededDetailGapNanos)} of prior Agent spend into ${mappedRows[0]}.`);
375	    this.setOkStatus(notes.join(' ') || undefined);
376	    return { skippedTiers: [...skippedTiers] };
377	  }
