484	function successfulEdit(value: unknown): boolean {
485	  if (isRecord(value) && value.isError === true) return false;
486	  const parsed = unwrapToolResult(value);
487	  return isRecord(parsed) && (parsed.status === 'applied' || (parsed.status === 'no_op' && parsed.reason === 'already_satisfied'));
488	}
489	
490	function extractUsd(value: unknown, row: string, column: string): number {
491	  const parsed = unwrapToolResult(value);
492	  const tabular = findTabularNumber(parsed, row, column);
493	  if (tabular !== null) return tabular;
494	  const candidates = [
495	    isRecord(parsed) ? parsed.value : undefined,
496	    isRecord(parsed) ? parsed.values : undefined,
497	  ];
498	  for (const candidate of candidates) {
499	    const found = findNumber(candidate, row, column);
500	    if (found !== null) return found;
501	  }
502	  throw new Error(`cfo.ai response did not include ${row} / ${column}`);
503	}
504	
505	function findNumber(value: unknown, row: string, column: string): number | null {
506	  if (typeof value === 'number' && Number.isFinite(value)) return value;
507	  if (typeof value === 'string' && value.trim() !== '' && Number.isFinite(Number(value))) return Number(value);
508	  if (Array.isArray(value)) {
509	    if (value.length >= 2 && value[0] === row) {
510	      const direct = findNumber(value[1], row, column);
511	      if (direct !== null) return direct;
512	    }
513	    for (const item of value) {
514	      const found = findNumber(item, row, column);
515	      if (found !== null) return found;
516	    }
517	  }
518	  if (isRecord(value)) {
519	    if (row in value) {
520	      const found = findNumber(value[row], row, column);
521	      if (found !== null) return found;
522	    }
523	    if (column in value) {
524	      const found = findNumber(value[column], row, column);
525	      if (found !== null) return found;
526	    }
527	    for (const item of Object.values(value)) {
528	      const found = findNumber(item, row, column);
529	      if (found !== null) return found;
530	    }
531	  }
532	  return null;
533	}
534	
535	function findTabularNumber(value: unknown, row: string, column: string): number | null {
536	  if (!isRecord(value) || !Array.isArray(value.rows)) return null;
537	  const columns = Array.isArray(value.columns) ? value.columns : [];
538	  for (const candidate of value.rows) {
539	    if (!isRecord(candidate)) continue;
540	    const displayName = typeof candidate.display_name === 'string' ? candidate.display_name : typeof candidate.name === 'string' ? candidate.name : null;
541	    if (displayName !== row) continue;
542	    const values = Array.isArray(candidate.values) ? candidate.values : [];
543	    const index = columnIndex(columns, column);
544	    const cell = values[index >= 0 ? index : 0];
545	    const direct = isRecord(cell) && 'value' in cell ? cell.value : cell;
546	    return exactNumber(direct);
547	  }
548	  return null;
549	}
550	
551	function columnIndex(columns: unknown[], column: string): number {
552	  return columns.findIndex((candidate) => {
553	    if (!isRecord(candidate)) return false;
554	    const ref = typeof candidate.ref === 'string' ? candidate.ref : '';
555	    const displayName = typeof candidate.display_name === 'string' ? candidate.display_name : '';
556	    return ref.startsWith(column) || displayName === column;
557	  });
558	}
559	
560	function exactNumber(value: unknown): number | null {

561	  if (typeof value === 'number' && Number.isFinite(value)) return value;
562	  if (typeof value === 'string' && value.trim() !== '' && Number.isFinite(Number(value))) return Number(value);
563	  return null;
564	}
565	
566	function unwrapToolResult(value: unknown): unknown {
567	  if (isRecord(value)) {
568	    if ('structuredContent' in value) return value.structuredContent;
569	    if ('toolResult' in value) return value.toolResult;
570	    const content = value.content;
571	    if (Array.isArray(content)) {
572	      const text = content.find((item) => isRecord(item) && item.type === 'text' && typeof item.text === 'string');
573	      if (isRecord(text) && typeof text.text === 'string') {
574	        try {
575	          return JSON.parse(text.text) as unknown;
576	        } catch {
577	          return text.text;
578	        }
579	      }
580	    }
581	  }
582	  return value;
583	}
584	
585	function isRecord(value: unknown): value is Record<string, unknown> {
586	  return typeof value === 'object' && value !== null;
587	}
588	
589	function openInBrowser(url: URL): Promise<void> {
590	  const command = process.platform === 'darwin' ? 'open' : process.platform === 'win32' ? 'cmd' : 'xdg-open';
591	  const args = process.platform === 'win32' ? ['/c', 'start', String(url)] : [String(url)];
592	  return new Promise((resolve, reject) => {
593	    const child = spawn(command, args, { stdio: 'ignore', detached: true });
594	    child.once('error', reject);
595	    child.once('spawn', () => {
596	      child.unref();
597	      resolve();
598	    });
599	  });
600	}
