 30	type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
 31	
 32	function parseJson(stdout: string): Json {
 33	  try {
 34	    return JSON.parse(stdout) as Json;
 35	  } catch {
 36	    return null;
 37	  }
 38	}
 39	
 40	function objects(value: Json): Array<Record<string, Json>> {
 41	  if (Array.isArray(value)) return value.filter((item): item is Record<string, Json> => typeof item === 'object' && item !== null && !Array.isArray(item));
 42	  if (typeof value !== 'object' || value === null || Array.isArray(value)) return [];
 43	  for (const key of ['results', 'matches', 'symbols']) {
 44	    const list = value[key];
 45	    if (Array.isArray(list)) return objects(list);
 46	  }
 47	  return [value];
 48	}
 49	
 50	function stringField(value: Record<string, Json>, names: string[]): string | null {
 51	  for (const name of names) {
 52	    const found = value[name];
 53	    if (typeof found === 'string' && found.trim() !== '') return found;
 54	  }
 55	  return null;
 56	}
 57	
 58	function countField(value: Json, name: string): number {
 59	  if (typeof value !== 'object' || value === null || Array.isArray(value)) return 0;
 60	  const direct = value[name];
 61	  if (typeof direct === 'number' && Number.isFinite(direct)) return direct;
 62	  if (typeof direct === 'object' && direct !== null && !Array.isArray(direct)) {
 63	    const total = direct.total;
 64	    if (typeof total === 'number' && Number.isFinite(total)) return total;
 65	  }
 66	  return 0;
 67	}
 68	
 69	function record(value: Json): Record<string, Json> {
 70	  return value !== null && typeof value === 'object' && !Array.isArray(value) ? value : {};
 71	}
 72	
 73	function entries(value: Json, group: string): Array<Record<string, Json>> {
 74	  return objects(record(record(value)[group] ?? null).entries ?? []);
 75	}
 76	
 77	function looksLikeTest(path: string): boolean {
 78	  return /(^|[/\\])(__tests__|tests?|spec)([/\\])|[._-](test|spec)\.[cm]?[jt]sx?$|test_.*\.py$/i.test(path);
 79	}
 80	
 81	function words(text: string): string[] {
 82	  const explicit = [...text.matchAll(/`([^`]+)`/g)].map((match) => match[1]!).filter(Boolean);
 83	  const plain = text.match(/[A-Za-z][A-Za-z0-9_-]{3,}/g) ?? [];
 84	  return [...new Set([...explicit, ...plain].map((word) => word.replace(/[^\w./-]/g, '')).filter((word) => word.length >= 4))].slice(0, 8);
 85	}
