 87	export class EntireSizingAdapter implements SizingSignalsPort {
 88	  private readonly repoPath: string;
 89	  private readonly runner: CommandRunner;
 90	  private readonly topSymbols: number;
 91	  private graphStatus: IntegrationState = {
 92	    status: 'missing',
 93	    detail: 'Entire graph has not succeeded yet. Falling back to code search. Fix: run `entire enable` in this repository.',
 94	  };
 95	
 96	  constructor(options: EntireSizingOptions) {
 97	    this.repoPath = options.repoPath;
 98	    this.runner = options.runner ?? new ShellCommandRunner();
 99	    this.topSymbols = options.topSymbols ?? 3;
100	  }
101	
102	  async signalsFor(task: TaskInput): Promise<SizingSignals | null> {
103	    const query = `${task.title}\n${task.body}`.trim();
104	    if (query === '') return null;
105	    try {
106	      const signals = await this.entireGraphSignals(query);
107	      this.graphStatus = { status: 'ok', detail: null };
108	      return signals;
109	    } catch (e) {
110	      this.graphStatus = {
111	        status: 'missing',
112	        detail: `Entire graph is unavailable (${(e as Error).message}). Falling back to code search. Fix: run \`entire enable\` in this repository.`,
113	      };
114	      return this.codeSearchSignals(query);
115	    }
116	  }
117	
118	  status(): IntegrationState {
119	    return this.graphStatus;
120	  }
121	
122	  private async entireGraphSignals(query: string): Promise<SizingSignals> {
123	    await this.runner.run('entire', ['graph', 'index', '--repo', this.repoPath]);
124	    const search = await this.runner.run('entire', [
125	      'graph',
126	      'search',
127	      '--repo',
128	      this.repoPath,
129	      '--profile',
130	      'full',
131	      '--format',
132	      'json',
133	      '--query',
134	      query,
135	    ]);
136	    const hits = objects(parseJson(search.stdout)).filter((hit) => hit.section !== 'related' &&
137	      (typeof hit.score !== 'number' || hit.score > 0) && stringField(hit, ['qualified_name', 'symbol', 'symbol_name', 'name']));
138	    const files = new Set<string>();
139	    const nodes = new Map<string, TaskImpact['nodes'][number]>();
140	    const edges = new Map<string, TaskImpact['edges'][number]>();
141	    let callers = 0;
142	    let coChanges = 0;
143	    let truncated = false;
144	    const addNode = (path: string | null, kind: TaskImpact['nodes'][number]['kind'], weight: number, symbol?: string): string | null => {
145	      const id = path ? this.repoRelative(path) : null;
146	      if (!id) return null;
147	      const previous = nodes.get(id);
148	      const priority = { target: 4, test: 3, caller: 2, coChange: 1 };
149	      const candidate = { id, kind, weight, ...(symbol ? { symbol } : {}) };
150	      if (!previous || priority[kind] > priority[previous.kind]) nodes.set(id, candidate);
151	      else if (weight > (previous.weight ?? 0)) nodes.set(id, { ...previous, weight });
152	      return id;
153	    };
154	    const addEdge = (from: string, to: string, kind: TaskImpact['edges'][number]['kind']) => {
155	      if (from !== to) edges.set(`${from}:${to}:${kind}`, { from, to, kind });
156	    };
157	    for (const [index, hit] of hits.entries()) {
158	      const hitFile = stringField(hit, ['file_path', 'file', 'path']);
159	      const symbol = stringField(hit, ['qualified_name', 'symbol', 'symbol_name', 'name'])!;
160	      const target = addNode(hitFile, hitFile && looksLikeTest(hitFile) ? 'test' : 'target', typeof hit.score === 'number' ? hit.score : 100, symbol);
161	      if (!target) { truncated = true; continue; }
162	      files.add(target);
163	      // Size uses the full primary search spread; expensive impact probes stay bounded.
164	      if (index >= this.topSymbols) { truncated = true; continue; }
165	      const impact = parseJson((await this.runner.run('entire', ['graph', 'impact', '--repo', this.repoPath, '--symbol', symbol, '--format', 'json'])).stdout);
166	      callers += countField(impact, 'callers');
167	      coChanges += countField(impact, 'co_changes');
168	      for (const group of ['callers', 'co_changes']) {
169	        const connected = entries(impact, group);
170	        if (connected.length < countField(impact, group)) truncated = true;
171	        for (const entry of connected) {
172	          const endpoint = record(entry.endpoint ?? entry);
173	          const path = stringField(endpoint, ['file_path', 'file', 'path']);
174	          const test = path !== null && looksLikeTest(path);
175	          if (group === 'callers' && entry.depth !== undefined && entry.depth !== 1 && !test) { truncated = true; continue; }
176	          const kind = test ? 'test' : group === 'callers' ? 'caller' : 'coChange';
177	          const weight = typeof entry.weight === 'number' ? entry.weight : group === 'callers' ? 10 : 1;
178	          const id = addNode(path, kind, weight, stringField(endpoint, ['qualified_name', 'name']) ?? undefined);
179	          if (!id) { truncated = true; continue; }
180	          if (test) addEdge(id, target, 'tests');
181	          else if (group === 'callers') addEdge(id, target, 'calls');
182	          else addEdge(target, id, 'changesWith');
183	        }
184	      }
185	    }
186	    if (!files.size) throw new Error('graph search returned no target symbols');
187	    const totals = { filesTouched: files.size, dependents: callers + coChanges, testsPresent: [...nodes.keys()].some(looksLikeTest), nodes: nodes.size, edges: edges.size };
188	    return {
189	      filesTouched: totals.filesTouched, dependents: totals.dependents, testsPresent: totals.testsPresent,
190	      source: 'entire-graph',
191	      impact: capImpact({ source: 'entire-graph', query, nodes: [...nodes.values()], edges: [...edges.values()], totals, truncated }),
192	    };
193	  }
194	
195	  private repoRelative(path: string): string | null {
196	    const normalized = (isAbsolute(path) ? relative(resolve(this.repoPath), path) : path).replaceAll('\\', '/').replace(/^\.\//, '');
197	    return normalized && !normalized.startsWith('/') && !/^[A-Za-z]:/.test(normalized) && !normalized.split('/').includes('..') ? normalized : null;
198	  }
199	
200	  private async codeSearchSignals(query: string): Promise<SizingSignals | null> {
201	    const terms = words(query);
202	    if (terms.length === 0) return null;
203	    const files = new Set<string>();
204	    for (const term of terms) {
205	      try {
206	        const result = await this.runner.run('rg', ['-l', '--fixed-strings', term, this.repoPath]);
207	        for (const file of result.stdout.split(/\r?\n/)) {
208	          const path = this.repoRelative(file.trim());
209	          if (path) files.add(path);
210	        }
211	      } catch {
212	        // Some terms will not match; keep trying the rest.
213	      }
214	    }
215	    if (files.size === 0) return null;
216	    const totals = { filesTouched: files.size, dependents: 0, testsPresent: [...files].some(looksLikeTest), nodes: files.size, edges: 0 };
217	    return {
218	      filesTouched: totals.filesTouched, dependents: totals.dependents, testsPresent: totals.testsPresent,
219	      source: 'code-search',
220	      impact: capImpact({ source: 'code-search', query, nodes: [...files].map((id) => ({ id, kind: 'target', weight: 1 })), edges: [], totals, truncated: false }),
221	    };
222	  }
223	}

