 25	function stringValue(value: unknown): string | null {
 26	  if (typeof value === 'string') return value;
 27	  if (typeof value !== 'object' || value === null) return null;
 28	  const record = value as Record<string, unknown>;
 29	  const nested = record.value;
 30	  if (typeof nested === 'string') return nested;
 31	  if (typeof record.stringValue === 'string') return record.stringValue;
 32	  if (typeof record.intValue === 'number' || typeof record.intValue === 'string') return String(record.intValue);
 33	  if (typeof record.doubleValue === 'number') return String(record.doubleValue);
 34	  return null;
 35	}
 36	
 37	function numberValue(value: unknown): number | null {
 38	  if (typeof value === 'number' && Number.isFinite(value)) return value;
 39	  const text = stringValue(value);
 40	  if (text === null || text.trim() === '') return null;
 41	  const parsed = Number(text);
 42	  return Number.isFinite(parsed) ? parsed : null;
 43	}
 44	
 45	function attributesOf(span: unknown): Record<string, unknown> {
 46	  if (typeof span !== 'object' || span === null) return {};
 47	  const raw = (span as Record<string, unknown>).attributes;
 48	  if (Array.isArray(raw)) {
 49	    return Object.fromEntries(
 50	      raw
 51	        .map((entry) => {
 52	          if (typeof entry !== 'object' || entry === null) return null;
 53	          const key = (entry as Record<string, unknown>).key;
 54	          if (typeof key !== 'string') return null;
 55	          return [key, (entry as Record<string, unknown>).value];
 56	        })
 57	        .filter((entry): entry is [string, unknown] => entry !== null),
 58	    );
 59	  }
 60	  return typeof raw === 'object' && raw !== null ? (raw as Record<string, unknown>) : {};
 61	}
 62	
 63	function traceIdOf(trace: unknown): string | null {
 64	  if (typeof trace !== 'object' || trace === null) return null;
 65	  const record = trace as Record<string, unknown>;
 66	  return stringValue(record.id) ?? stringValue(record.traceId) ?? stringValue(record.trace_id);
 67	}
 68	
 69	function traceNameOf(trace: unknown): string | null {
 70	  if (typeof trace !== 'object' || trace === null) return null;
 71	  const record = trace as Record<string, unknown>;
 72	  return stringValue(record.traceName) ?? stringValue(record.name);
 73	}
 74	
 75	function observationFromName(name: string | null): Observation | null {
 76	  if (!name?.startsWith('tally.history.record ')) return null;
 77	  const fields = Object.fromEntries(
 78	    name
 79	      .slice('tally.history.record '.length)
 80	      .split(/\s+/)
 81	      .map((part) => part.split('='))
 82	      .filter((parts): parts is [string, string] => parts.length === 2 && parts[0] !== ''),
 83	  );
 84	  const size = fields.size;
 85	  const tier = fields.tier;
 86	  const result = fields.result;
 87	  const costNanos = Number(fields.cost_nanos);
 88	  if (size !== 'small' && size !== 'medium' && size !== 'large') return null;
 89	  if (!tier || !result || !Number.isFinite(costNanos) || costNanos < 0) return null;
 90	  return { size, tier, result, costNanos: Math.round(costNanos) };
 91	}
 92	
 93	function spansOf(body: unknown): unknown[] {
 94	  if (Array.isArray(body)) return body;
 95	  if (typeof body !== 'object' || body === null) return [];
 96	  const record = body as Record<string, unknown>;
 97	  if (Array.isArray(record.spans)) return record.spans;
 98	  if (Array.isArray(record.data)) return record.data;
 99	  if (typeof record.data === 'object' && record.data !== null && Array.isArray((record.data as Record<string, unknown>).spans)) {
100	    return (record.data as Record<string, unknown>).spans as unknown[];
101	  }
102	  return [];
103	}
104	
105	function tracesOf(body: unknown): unknown[] {
106	  if (Array.isArray(body)) return body;
107	  if (typeof body !== 'object' || body === null) return [];
108	  const record = body as Record<string, unknown>;
109	  if (Array.isArray(record.traces)) return record.traces;
110	  if (Array.isArray(record.data)) return record.data;
111	  if (typeof record.data === 'object' && record.data !== null && Array.isArray((record.data as Record<string, unknown>).traces)) {
112	    return (record.data as Record<string, unknown>).traces as unknown[];
113	  }
114	  return [];
115	}
116	
117	function observationFromSpan(span: unknown): Observation | null {
118	  if (typeof span !== 'object' || span === null) return null;
119	  const name = stringValue((span as Record<string, unknown>).name);
120	  const attrs = attributesOf(span);
121	  if (name !== 'tally.history.record' && stringValue(attrs['tally.history.kind']) !== 'attempt') return null;
122	  const size = stringValue(attrs['tally.history.size']) ?? stringValue(attrs.size);
123	  const tier = stringValue(attrs['tally.history.tier']) ?? stringValue(attrs.tier);
124	  const result = stringValue(attrs['tally.history.result']) ?? stringValue(attrs.result);
125	  const costNanos = numberValue(attrs['tally.history.cost_nanos']) ?? numberValue(attrs.costNanos);
126	  if (size !== 'small' && size !== 'medium' && size !== 'large') return null;
127	  if (!tier || !result || costNanos === null || costNanos < 0) return null;
128	  return { size, tier, result, costNanos: Math.round(costNanos) };
129	}
130	
131	function aggregate(observations: Observation[], size: TaskSize, tier: string): PriceStats | null {
132	  const matches = observations.filter((row) => row.size === size && row.tier === tier && row.result !== 'error');
133	  if (matches.length === 0) return null;
134	  return {
135	    attempts: matches.length,
136	    passRate: matches.filter((row) => row.result === 'passed').length / matches.length,
137	    avgCostNanos: Math.round(matches.reduce((sum, row) => sum + row.costNanos, 0) / matches.length),
138	  };
139	}
