 44	  async verifyFor(context: WorkerTraceReadContext): Promise<string | null> {
 45	    if (!this.env.NEATLOGS_TOKEN || !this.env.NEATLOGS_PROJECT_ID) return null;
 46	    for (let retry = 0; retry < this.retries; retry++) {
 47	      try {
 48	        const candidates = context.traceId ? [context.traceId] : await this.discover(context);
 49	        for (const id of candidates) {
 50	          if (!/^[0-9a-f]{32}$/i.test(id)) continue;
 51	          const detail = await this.read(`/traces/${id}`) as { data?: TraceRecord } | null;
 52	          if (!detail?.data || detail.data.traceId !== id || !matches(detail.data, context)) continue;
 53	          const spans = await this.read(`/traces/${id}/spans`) as { data?: { spans?: unknown[] } } | null;
 54	          // A trace-list stub/app shell is not delivery proof. Killed turns may have
 55	          // zero aggregate tokens yet still have readable tool spans.
 56	          if (Array.isArray(spans?.data?.spans) && spans.data.spans.length > 0) return id;
 57	        }
 58	      } catch { /* Network/auth/processing failure cannot establish delivery. */ }
 59	      if (retry + 1 < this.retries) await new Promise(resolve => setTimeout(resolve, this.retryDelayMs));
 60	    }
 61	    return null;
 62	  }
