 64	  private async discover(context: WorkerTraceReadContext): Promise<string[]> {
 65	    let cursor: string | undefined;
 66	    const ids: string[] = [];
 67	    for (let page = 0; page < 5; page++) {
 68	      const query = new URLSearchParams({ limit: '50', ...(cursor ? { cursor } : {}) });
 69	      const body = await this.read(`/traces?${query}`) as { data?: { traces?: TraceRecord[]; page?: { nextCursor?: string; hasMore?: boolean } } } | null;
 70	      if (!Array.isArray(body?.data?.traces)) break;
 71	      for (const trace of body.data.traces) if (matches(trace, context) && trace.traceId) ids.push(trace.traceId);
 72	      if (ids.length || !body.data.page?.hasMore || !body.data.page.nextCursor) break;
 73	      cursor = body.data.page.nextCursor;
 74	    }
 75	    return ids;
