    21	
    22	function matches(trace: TraceRecord, context: WorkerTraceReadContext): boolean {
    23	  const name = trace.workflowName ?? trace.traceName ?? '';
    24	  const correlation = /Tally run ([^,]+), task ([^,]+), attempt (\d+)(?:[:\s]|$)/.exec(name);
    25	  return trace.sessionId === context.nativeSessionId && correlation?.[1] === context.runId
    26	    && correlation[2] === context.taskId && Number(correlation[3]) === context.attempt;
    27	}
