566	function unwrapToolResult(value: unknown): unknown {
567	  if (isRecord(value)) {
568	    if ('structuredContent' in value) return value.structuredContent;
569	    if ('toolResult' in value) return value.toolResult;
570	    const content = value.content;
571	    if (Array.isArray(content)) {
572	      const text = content.find((item) => isRecord(item) && item.type === 'text' && typeof item.text === 'string');
573	      if (isRecord(text) && typeof text.text === 'string') {
574	        try {
575	          return JSON.parse(text.text) as unknown;
576	        } catch {
577	          return text.text;
578	        }
579	      }
580	    }
581	  }
582	  return value;
583	}
584	
585	function isRecord(value: unknown): value is Record<string, unknown> {
586	  return typeof value === 'object' && value !== null;
587	}
588	
589	function openInBrowser(url: URL): Promise<void> {
590	  const command = process.platform === 'darwin' ? 'open' : process.platform === 'win32' ? 'cmd' : 'xdg-open';
591	  const args = process.platform === 'win32' ? ['/c', 'start', String(url)] : [String(url)];
592	  return new Promise((resolve, reject) => {
593	    const child = spawn(command, args, { stdio: 'ignore', detached: true });
594	    child.once('error', reject);
595	    child.once('spawn', () => {
596	      child.unref();
597	      resolve();
598	    });
599	  });
600	}
601	
602	export async function loginCfoai(options: {
603	  config?: CfoaiBudgetConfig;
604	  tokenPath?: string;
605	  openUrl?: (url: URL) => Promise<void>;
606	  timeoutMs?: number;
607	} = {}): Promise<CfoaiLoginResult> {
608	  const normalized = normalizeCfoaiConfig(options.config);
609	  const tokenStore = new FileTokenStore(options.tokenPath);
610	  let resolveCode!: (code: string) => void;
611	  let rejectCode!: (error: Error) => void;
612	  const code = new Promise<string>((resolve, reject) => {
613	    resolveCode = resolve;
614	    rejectCode = reject;
615	  });
616	  const server = createServer((req, res) => {
617	    const url = new URL(req.url ?? '/', 'http://127.0.0.1');
618	    const received = url.searchParams.get('code');
619	    if (received) {
620	      res.writeHead(200, { 'content-type': 'text/plain' });
621	      res.end('cfo.ai is connected. You can close this tab.\n');
622	      resolveCode(received);
623	    } else {
624	      res.writeHead(400, { 'content-type': 'text/plain' });
625	      res.end('Missing OAuth code.\n');
626	      rejectCode(new Error('cfo.ai OAuth callback did not include a code'));
627	    }
628	  });
629	  await new Promise<void>((resolve, reject) => {
630	    server.once('error', reject);
631	    server.listen(0, '127.0.0.1', resolve);
632	  });
633	  const address = server.address();
634	  if (!address || typeof address === 'string') throw new Error('could not start local cfo.ai OAuth callback server');
635	  const provider = new CfoaiOAuthProvider(tokenStore, `http://127.0.0.1:${address.port}/callback`, options.openUrl ?? openInBrowser);
636	  const client = new SdkCfoaiMcpClient(normalized.serverUrl, provider);
637	  try {
638	    await client.connect().catch((error: unknown) => {
639	      if (provider.authorizationUrl) return;
640	      throw error;
641	    });
642	    if (!provider.authorizationUrl) {
643	      await client.listTools();
644	      await client.close();
645	      return { status: 'ok', tokenPath: tokenStore.tokenPath };
646	    }
647	    const timeout = new Promise<never>((_, reject) => {
648	      setTimeout(() => reject(new Error('timed out waiting for the cfo.ai browser approval')), options.timeoutMs ?? 120_000).unref();
649	    });
650	    const authorizationCode = await Promise.race([code, timeout]);
651	    await client.finishAuth(authorizationCode);
652	    await client.close();
653	    const verified = new SdkCfoaiMcpClient(normalized.serverUrl, provider);
654	    await verified.connect();
655	    await verified.listTools();
656	    await verified.close();
657	    return { status: 'ok', tokenPath: tokenStore.tokenPath };
658	  } finally {
659	    server.close();
660	  }
661	}
662	
663	export async function checkCfoaiConnection(options: CfoaiConnectionCheckOptions = {}): Promise<IntegrationState> {
664	  const normalized = normalizeCfoaiConfig(options.config);
665	  const tokenStore = new FileTokenStore(options.tokenPath);
666	  if (!options.client && !tokenStore.read().tokens) {
667	    return { status: 'missing', detail: `Tally has no cached cfo.ai token. ${CFOAI_FIX_COMMAND}` };
668	  }
669	  const client =
670	    options.client ??
671	    new SdkCfoaiMcpClient(normalized.serverUrl, new CfoaiOAuthProvider(tokenStore, undefined, async () => undefined));
672	  try {
673	    await client.connect();
674	    const listed = await client.listTools();
675	    const names = new Set(listed.tools.map((tool) => tool.name));
676	    for (const name of ['inspect_table_blocks', 'edit_table_blocks']) {
677	      if (!names.has(name)) throw new Error(`cfo.ai MCP tool ${name} is missing`);
678	    }
679	    await client.close();
680	    return { status: 'ok', detail: `Tally cached token works against ${normalized.serverUrl}` };
681	  } catch (e) {
682	    try {
683	      await client.close();
684	    } catch {
685	      // The connection was not open.
686	    }
687	    return { status: 'missing', detail: `${(e as Error).message}. ${CFOAI_FIX_COMMAND}` };
688	  }
689	}

