 40	export class NeatlogsTraceAdapter implements TracePort {
 41	  private readonly apiKey: string | null;
 42	  private readonly workflowName: string;
 43	  private readonly tags: string[];
 44	  private readonly sdkOverride: NeatlogsSdk | null | undefined;
 45	  private readonly loadSdk: () => Promise<NeatlogsSdk>;
 46	  private sdk: NeatlogsSdk | null = null;
 47	  private initStarted: Promise<void> | null = null;
 48	  private offReason: string | null = null;
 49	  private lastTraceIdValue: string | null = null;
 50	
 51	  constructor(options: NeatlogsTraceOptions = {}) {
 52	    const env = options.env ?? loadEnv();
 53	    this.apiKey = env.NEATLOGS_API_KEY || null;
 54	    this.workflowName = options.workflowName ?? DEFAULT_WORKFLOW;
 55	    this.tags = options.tags ?? ['tally', 'cfo-agent'];
 56	    this.sdkOverride = options.sdk;
 57	    this.loadSdk = options.loadSdk ?? importNeatlogs;
 58	    if (!this.apiKey) this.offReason = 'NEATLOGS_API_KEY is missing';
 59	  }
 60	
 61	  status(): IntegrationState {
 62	    return this.offReason ? { status: 'missing', detail: this.offReason } : { status: 'ok', detail: this.lastTraceIdValue };
 63	  }
 64	
 65	  lastTraceId(): string | null {
 66	    return this.lastTraceIdValue;
 67	  }
 68	
 69	  async span<T>(name: string, attributes: TraceAttributes, fn: (span: TraceSpan) => Promise<T>): Promise<T> {
 70	    const sdk = await this.ready();
 71	    if (!sdk) return fn({ set: () => {} });
 72	
 73	    const span: MutableSpan = {
 74	      attributes: { ...attributes },
 75	      set: (next) => Object.assign(span.attributes, next),
 76	    };
 77	    const sessionId = typeof attributes.sessionId === 'string' ? attributes.sessionId : undefined;
 78	    const safeAttributes = serialisable(attributes);
 79	    return sdk.trace({ name, kind: 'CHAIN', ...(sessionId ? { sessionId } : {}), input: safeAttributes, attributes: safeAttributes }, async () => {
 80	      const carrier: Record<string, string> = {};
 81	      sdk.injectTraceContext?.(carrier);
 82	      this.lastTraceIdValue = traceIdFromCarrier(carrier);
 83	      return fn(span);
 84	    });
 85	  }
 86	
 87	  async flush(): Promise<void> {
 88	    const sdk = await this.ready();
 89	    await sdk?.flush?.();
 90	  }
 91	
 92	  async shutdown(): Promise<void> {
 93	    const sdk = await this.ready();
 94	    await sdk?.flush?.();
 95	    await sdk?.shutdown?.();
 96	  }
 97	
 98	  private async ready(): Promise<NeatlogsSdk | null> {
 99	    if (this.sdk || this.offReason) return this.sdk;
100	    this.initStarted ??= this.initialise();
101	    await this.initStarted;
102	    return this.sdk;
103	  }
104	
105	  private async initialise(): Promise<void> {
106	    if (!this.apiKey) return;
107	    try {
108	      const sdk = this.sdkOverride === undefined ? await this.loadSdk() : this.sdkOverride;
109	      if (!sdk) {
110	        this.offReason = 'neatlogs SDK is not installed';
111	        return;
112	      }
113	      await sdk.init({ apiKey: this.apiKey, workflowName: this.workflowName, tags: this.tags });
114	      this.sdk = sdk;
115	      this.offReason = null;
116	    } catch {
117	      this.offReason = 'neatlogs SDK is not available';
118	      this.sdk = null;
119	    }
120	  }
121	}
  1	import { runCommand } from './command.js';
  2	import { isAbsolute, relative, resolve } from 'node:path';
  3	import { capImpact } from '../agent/impact.js';
  4	import type { SizingSignals, SizingSignalsPort, TaskInput } from '../agent/ports.js';
  5	import type { IntegrationState, TaskImpact } from '../schema/types.js';
  6	
  7	const execFileAsync = runCommand;
  8	
  9	export interface CommandResult {
 10	  stdout: string;
 11	}
 12	
 13	export interface CommandRunner {
 14	  run(command: string, args: string[], options?: { cwd?: string }): Promise<CommandResult>;
 15	}
 16	
 17	export interface EntireSizingOptions {
 18	  repoPath: string;
 19	  runner?: CommandRunner;
 20	  topSymbols?: number;
 21	}
 22	
 23	export class ShellCommandRunner implements CommandRunner {
 24	  async run(command: string, args: string[], options: { cwd?: string } = {}): Promise<CommandResult> {
 25	    const { stdout } = await execFileAsync(command, args, { cwd: options.cwd, maxBuffer: 10 * 1024 * 1024 });
 26	    return { stdout };
 27	  }
 28	}
 29	
 30	type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
 31	
 32	function parseJson(stdout: string): Json {
 33	  try {
 34	    return JSON.parse(stdout) as Json;
 35	  } catch {
 36	    return null;
 37	  }
 38	}
 39	
 40	function objects(value: Json): Array<Record<string, Json>> {
 41	  if (Array.isArray(value)) return value.filter((item): item is Record<string, Json> => typeof item === 'object' && item !== null && !Array.isArray(item));
 42	  if (typeof value !== 'object' || value === null || Array.isArray(value)) return [];
 43	  for (const key of ['results', 'matches', 'symbols']) {
 44	    const list = value[key];
 45	    if (Array.isArray(list)) return objects(list);
 46	  }
 47	  return [value];
 48	}
 49	
 50	function stringField(value: Record<string, Json>, names: string[]): string | null {
 51	  for (const name of names) {
 52	    const found = value[name];
 53	    if (typeof found === 'string' && found.trim() !== '') return found;
 54	  }
 55	  return null;
 56	}
 57	
 58	function countField(value: Json, name: string): number {
 59	  if (typeof value !== 'object' || value === null || Array.isArray(value)) return 0;
 60	  const direct = value[name];
 61	  if (typeof direct === 'number' && Number.isFinite(direct)) return direct;
 62	  if (typeof direct === 'object' && direct !== null && !Array.isArray(direct)) {
 63	    const total = direct.total;
 64	    if (typeof total === 'number' && Number.isFinite(total)) return total;
 65	  }
 66	  return 0;
 67	}
 68	
 69	function record(value: Json): Record<string, Json> {
 70	  return value !== null && typeof value === 'object' && !Array.isArray(value) ? value : {};
 71	}
 72	
 73	function entries(value: Json, group: string): Array<Record<string, Json>> {
 74	  return objects(record(record(value)[group] ?? null).entries ?? []);
 75	}
 76	
 77	function looksLikeTest(path: string): boolean {
 78	  return /(^|[/\\])(__tests__|tests?|spec)([/\\])|[._-](test|spec)\.[cm]?[jt]sx?$|test_.*\.py$/i.test(path);
 79	}
 80	
 81	function words(text: string): string[] {
 82	  const explicit = [...text.matchAll(/`([^`]+)`/g)].map((match) => match[1]!).filter(Boolean);
 83	  const plain = text.match(/[A-Za-z][A-Za-z0-9_-]{3,}/g) ?? [];
 84	  return [...new Set([...explicit, ...plain].map((word) => word.replace(/[^\w./-]/g, '')).filter((word) => word.length >= 4))].slice(0, 8);
 85	}
 86	
 87	export class EntireSizingAdapter implements SizingSignalsPort {
 88	  private readonly repoPath: string;
 89	  private readonly runner: CommandRunner;
 90	  private readonly topSymbols: number;
 91	  private graphStatus: IntegrationState = {
 92	    status: 'missing',
 93	    detail: 'Entire graph has not succeeded yet. Falling back to code search. Fix: run `entire enable` in this repository.',
 94	  };
 95	
 96	  constructor(options: EntireSizingOptions) {
 97	    this.repoPath = options.repoPath;
 98	    this.runner = options.runner ?? new ShellCommandRunner();
 99	    this.topSymbols = options.topSymbols ?? 3;
100	  }
101	
102	  async signalsFor(task: TaskInput): Promise<SizingSignals | null> {
103	    const query = `${task.title}\n${task.body}`.trim();
104	    if (query === '') return null;
105	    try {
106	      const signals = await this.entireGraphSignals(query);
107	      this.graphStatus = { status: 'ok', detail: null };
108	      return signals;
109	    } catch (e) {
110	      this.graphStatus = {
111	        status: 'missing',
112	        detail: `Entire graph is unavailable (${(e as Error).message}). Falling back to code search. Fix: run \`entire enable\` in this repository.`,
113	      };
114	      return this.codeSearchSignals(query);
115	    }
116	  }
117	
118	  status(): IntegrationState {
119	    return this.graphStatus;
120	  }
121	
122	  private async entireGraphSignals(query: string): Promise<SizingSignals> {
123	    await this.runner.run('entire', ['graph', 'index', '--repo', this.repoPath]);
124	    const search = await this.runner.run('entire', [
125	      'graph',
126	      'search',
127	      '--repo',
128	      this.repoPath,
129	      '--profile',
130	      'full',
131	      '--format',
132	      'json',
133	      '--query',
134	      query,
135	    ]);
136	    const hits = objects(parseJson(search.stdout)).filter((hit) => hit.section !== 'related' &&
137	      (typeof hit.score !== 'number' || hit.score > 0) && stringField(hit, ['qualified_name', 'symbol', 'symbol_name', 'name']));
138	    const files = new Set<string>();
139	    const nodes = new Map<string, TaskImpact['nodes'][number]>();
140	    const edges = new Map<string, TaskImpact['edges'][number]>();
141	    let callers = 0;
142	    let coChanges = 0;
143	    let truncated = false;
144	    const addNode = (path: string | null, kind: TaskImpact['nodes'][number]['kind'], weight: number, symbol?: string): string | null => {
145	      const id = path ? this.repoRelative(path) : null;
146	      if (!id) return null;
147	      const previous = nodes.get(id);
148	      const priority = { target: 4, test: 3, caller: 2, coChange: 1 };
149	      const candidate = { id, kind, weight, ...(symbol ? { symbol } : {}) };
150	      if (!previous || priority[kind] > priority[previous.kind]) nodes.set(id, candidate);
151	      else if (weight > (previous.weight ?? 0)) nodes.set(id, { ...previous, weight });
152	      return id;
153	    };
154	    const addEdge = (from: string, to: string, kind: TaskImpact['edges'][number]['kind']) => {
155	      if (from !== to) edges.set(`${from}:${to}:${kind}`, { from, to, kind });
156	    };
157	    for (const [index, hit] of hits.entries()) {
158	      const hitFile = stringField(hit, ['file_path', 'file', 'path']);
159	      const symbol = stringField(hit, ['qualified_name', 'symbol', 'symbol_name', 'name'])!;
160	      const target = addNode(hitFile, hitFile && looksLikeTest(hitFile) ? 'test' : 'target', typeof hit.score === 'number' ? hit.score : 100, symbol);
161	      if (!target) { truncated = true; continue; }
162	      files.add(target);
163	      // Size uses the full primary search spread; expensive impact probes stay bounded.
164	      if (index >= this.topSymbols) { truncated = true; continue; }
165	      const impact = parseJson((await this.runner.run('entire', ['graph', 'impact', '--repo', this.repoPath, '--symbol', symbol, '--format', 'json'])).stdout);
166	      callers += countField(impact, 'callers');
167	      coChanges += countField(impact, 'co_changes');
168	      for (const group of ['callers', 'co_changes']) {
169	        const connected = entries(impact, group);
170	        if (connected.length < countField(impact, group)) truncated = true;
171	        for (const entry of connected) {
172	          const endpoint = record(entry.endpoint ?? entry);
173	          const path = stringField(endpoint, ['file_path', 'file', 'path']);
174	          const test = path !== null && looksLikeTest(path);
175	          if (group === 'callers' && entry.depth !== undefined && entry.depth !== 1 && !test) { truncated = true; continue; }
176	          const kind = test ? 'test' : group === 'callers' ? 'caller' : 'coChange';
177	          const weight = typeof entry.weight === 'number' ? entry.weight : group === 'callers' ? 10 : 1;
178	          const id = addNode(path, kind, weight, stringField(endpoint, ['qualified_name', 'name']) ?? undefined);
179	          if (!id) { truncated = true; continue; }
180	          if (test) addEdge(id, target, 'tests');
181	          else if (group === 'callers') addEdge(id, target, 'calls');
182	          else addEdge(target, id, 'changesWith');
183	        }
184	      }
185	    }
186	    if (!files.size) throw new Error('graph search returned no target symbols');
187	    const totals = { filesTouched: files.size, dependents: callers + coChanges, testsPresent: [...nodes.keys()].some(looksLikeTest), nodes: nodes.size, edges: edges.size };
188	    return {
189	      filesTouched: totals.filesTouched, dependents: totals.dependents, testsPresent: totals.testsPresent,
190	      source: 'entire-graph',
191	      impact: capImpact({ source: 'entire-graph', query, nodes: [...nodes.values()], edges: [...edges.values()], totals, truncated }),
192	    };
193	  }
194	
195	  private repoRelative(path: string): string | null {
196	    const normalized = (isAbsolute(path) ? relative(resolve(this.repoPath), path) : path).replaceAll('\\', '/').replace(/^\.\//, '');
197	    return normalized && !normalized.startsWith('/') && !/^[A-Za-z]:/.test(normalized) && !normalized.split('/').includes('..') ? normalized : null;
198	  }
199	
200	  private async codeSearchSignals(query: string): Promise<SizingSignals | null> {
201	    const terms = words(query);
202	    if (terms.length === 0) return null;
203	    const files = new Set<string>();
204	    for (const term of terms) {
205	      try {
206	        const result = await this.runner.run('rg', ['-l', '--fixed-strings', term, this.repoPath]);
207	        for (const file of result.stdout.split(/\r?\n/)) {
208	          const path = this.repoRelative(file.trim());
209	          if (path) files.add(path);
210	        }
211	      } catch {
212	        // Some terms will not match; keep trying the rest.
213	      }
214	    }
215	    if (files.size === 0) return null;
216	    const totals = { filesTouched: files.size, dependents: 0, testsPresent: [...files].some(looksLikeTest), nodes: files.size, edges: 0 };
217	    return {
218	      filesTouched: totals.filesTouched, dependents: totals.dependents, testsPresent: totals.testsPresent,
219	      source: 'code-search',
220	      impact: capImpact({ source: 'code-search', query, nodes: [...files].map((id) => ({ id, kind: 'target', weight: 1 })), edges: [], totals, truncated: false }),
221	    };
222	  }
223	}

