  7	export type PublishCommand = (file: string, args: string[], options?: { cwd?: string }) => Promise<{ stdout: string; stderr: string }>;
  8	
  9	export interface WorkerBranchInput {
 10	  checkoutPath: string;
 11	  branch: string;
 12	  config: TallyConfig;
 13	  baseCommit?: string | null;
 14	}
 15	
 16	export interface PublishPrInput extends WorkerBranchInput {
 17	  task: BacklogTask;
 18	  runId: string;
 19	  attempt: number;
 20	  scopeWarnings?: string[];
 21	}
 22	
 23	export interface PublishPort {
 24	  commitsAhead(input: WorkerBranchInput): Promise<number>;
 25	  changedFiles(input: WorkerBranchInput): Promise<string[]>;
 26	  publishPr(input: PublishPrInput): Promise<string>;
 27	}
 28	
 29	function defaultCommand(file: string, args: string[], options?: { cwd?: string }) {
 30	  return execFileAsync(file, args, { cwd: options?.cwd });
 31	}
 32	
 33	function errorMessage(error: unknown): string {
 34	  const e = error as { stderr?: unknown; message?: unknown };
 35	  return typeof e.stderr === 'string' && e.stderr.trim() ? e.stderr.trim() : typeof e.message === 'string' ? e.message : String(error);
 36	}
 37	
 38	function prBody(input: PublishPrInput): string {
 39	  const issue = input.task.issueNumber ? `\n\nRefs #${input.task.issueNumber}` : '';
 40	  const warning = input.scopeWarnings?.length ? `\n\nScope warning: out-of-scope changes: ${input.scopeWarnings.join(', ')}` : '';
 41	  return [`Tally run ${input.runId}, task ${input.task.taskId}, attempt ${input.attempt}.`, '', input.task.body || '(No issue body was provided.)', issue, warning].filter((part, index) => index < 4 || part).join('\n');
 42	}
 43	
 44	export class GitHubPublisher implements PublishPort {
 45	  constructor(private readonly command: PublishCommand = defaultCommand) {}
 46	
 47	  async changedFiles(input: WorkerBranchInput): Promise<string[]> {
 48	    const base = input.baseCommit ?? `origin/${input.config.repo.baseBranch}`;
 49	    const { stdout } = await this.command('git', ['diff', '--name-only', '-z', '--end-of-options', base, input.branch, '--'], { cwd: input.checkoutPath });
 50	    return stdout.split('\0').filter(Boolean);
 51	  }
 52	
 53	  async commitsAhead(input: WorkerBranchInput): Promise<number> {
 54	    try {
 55	      const { stdout } = await this.command('git', ['rev-list', '--count', `origin/${input.config.repo.baseBranch}..HEAD`], { cwd: input.checkoutPath });
 56	      return Number.parseInt(stdout.trim(), 10) || 0;
 57	    } catch {
 58	      const { stdout } = await this.command('git', ['rev-list', '--count', `${input.config.repo.baseBranch}..HEAD`], { cwd: input.checkoutPath });
 59	      return Number.parseInt(stdout.trim(), 10) || 0;
 60	    }
 61	  }
 62	
 63	  async publishPr(input: PublishPrInput): Promise<string> {
 64	    if (!input.config.repo.slug) throw new Error('repo.slug is required to open a GitHub pull request');
 65	    await this.command('git', ['push', '-u', 'origin', `HEAD:${input.branch}`], { cwd: input.checkoutPath });
 66	    if (input.config.integrations.entire) await this.pushCheckpoints(input);
 67	    try {
 68	      const { stdout } = await this.command(
 69	        'gh',
 70	        [
 71	          'pr',
 72	          'create',
 73	          '--repo',
 74	          input.config.repo.slug,
 75	          '--head',
 76	          input.branch,
 77	          '--base',
 78	          input.config.repo.baseBranch,
 79	          '--title',
 80	          `${input.task.taskId}: ${input.task.title}`,
 81	          '--body',
 82	          prBody(input),
 83	        ],
 84	        { cwd: input.checkoutPath },
 85	      );
 86	      return stdout.trim();
 87	    } catch (error) {
 88	      const message = errorMessage(error);
 89	      if (!/already exists/i.test(message)) throw error;
 90	      const { stdout } = await this.command('gh', ['pr', 'view', '--repo', input.config.repo.slug, '--head', input.branch, '--json', 'url', '-q', '.url'], {
 91	        cwd: input.checkoutPath,
 92	      });
 93	      return stdout.trim();
 94	    }
 95	  }
 96	
 97	  private async pushCheckpoints(input: PublishPrInput): Promise<void> {
 98	    const options = { cwd: input.checkoutPath };
 99	    const { stdout: messages } = await this.command('git', [
100	      'log', '--format=%B', '--end-of-options', `origin/${input.config.repo.baseBranch}..${input.branch}`, '--',
101	    ], options);
102	    const ids = new Set(Array.from(messages.matchAll(/^Entire-Checkpoint:\s*([A-Za-z0-9]+)\s*$/gm), (match) => match[1]!));
103	    if (!ids.size) return;
104	    const { stdout: refsOutput } = await this.command('git', ['for-each-ref', '--format=%(refname)', 'refs/entire/checkpoints/'], options);
105	    const refs = refsOutput.trim().split(/\r?\n/).filter((ref) => ids.has(ref.split('/').at(-1)!));
106	    for (const id of ids) {
107	      if (!refs.some((ref) => ref.endsWith(`/${id}`))) throw new Error(`Entire checkpoint ref missing for ${id}`);
108	    }
109	    const { stdout: remotes } = await this.command('git', ['remote'], options);
110	    for (const remote of ['origin', ...(remotes.split(/\r?\n/).includes('entire') ? ['entire'] : [])]) {
111	      await this.command('git', ['push', remote, ...refs.map((ref) => `${ref}:${ref}`)], options);
112	    }
113	  }
114	}

