 47	  async changedFiles(input: WorkerBranchInput): Promise<string[]> {
 48	    const base = input.baseCommit ?? `origin/${input.config.repo.baseBranch}`;
 49	    const { stdout } = await this.command('git', ['diff', '--name-only', '-z', '--end-of-options', base, input.branch, '--'], { cwd: input.checkoutPath });
