 65	    await this.command('git', ['push', '-u', 'origin', `HEAD:${input.branch}`], { cwd: input.checkoutPath });
 66	    if (input.config.integrations.entire) await this.pushCheckpoints(input);
 67	    try {
 68	      const { stdout } = await this.command(
 69	        'gh',
 70	        [
 71	          'pr',
 72	          'create',
 73	          '--repo',
 74	          input.config.repo.slug,
 75	          '--head',
 76	          input.branch,
 77	          '--base',
 78	          input.config.repo.baseBranch,
 79	          '--title',
 80	          `${input.task.taskId}: ${input.task.title}`,
 81	          '--body',
 82	          prBody(input),
 83	        ],
 84	        { cwd: input.checkoutPath },
 85	      );
 86	      return stdout.trim();
 87	    } catch (error) {
 88	      const message = errorMessage(error);
 89	      if (!/already exists/i.test(message)) throw error;
 90	      const { stdout } = await this.command('gh', ['pr', 'view', '--repo', input.config.repo.slug, '--head', input.branch, '--json', 'url', '-q', '.url'], {
 91	        cwd: input.checkoutPath,
 92	      });
 93	      return stdout.trim();
 94	    }
