144	  const [name, ...extra] = positionals;
145	  if (name === undefined) return { kind: 'help' };
146	  if (!(COMMANDS as readonly string[]).includes(name)) {
147	    return { kind: 'error', message: `unknown command "${name}"; expected one of ${COMMANDS.join(', ')}` };
