109	export function parseCli(argv: string[]): ParsedCli {
110	  let parsed;
111	  try {
112	    parsed = parseArgs({
113	      args: argv,
114	      allowPositionals: true,
115	      options: {
116	        config: { type: 'string', default: 'tally.yaml' },
117	        'dry-run': { type: 'boolean', default: false },
118	        baseline: { type: 'boolean', default: false },
119	        budget: { type: 'string' },
120	        only: { type: 'string' },
121	        dashboard: { type: 'boolean', default: false },
122	        open: { type: 'boolean', default: false },
123	        port: { type: 'string' },
124	        plan: { type: 'boolean', default: false },
125	        live: { type: 'boolean', default: false },
126	        yes: { type: 'boolean', default: false },
127	        output: { type: 'string' },
128	        limit: { type: 'string' },
129	        keyword: { type: 'string' },
130	        repeats: { type: 'string' },
131	        out: { type: 'string' },
132	        runs: { type: 'string' },
133	        run: { type: 'string' },
134	        help: { type: 'boolean', short: 'h', default: false },
135	        version: { type: 'boolean', short: 'v', default: false },
136	      },
137	    });
138	  } catch (e) {
139	    return { kind: 'error', message: (e as Error).message };
140	  }
141	  const { values, positionals } = parsed;
142	  if (values.help) return { kind: 'help' };
143	  if (values.version) return { kind: 'version' };
144	  const [name, ...extra] = positionals;
145	  if (name === undefined) return { kind: 'help' };
146	  if (!(COMMANDS as readonly string[]).includes(name)) {
147	    return { kind: 'error', message: `unknown command "${name}"; expected one of ${COMMANDS.join(', ')}` };
148	  }
149	  if (name === 'login') {
150	    if (extra[0] !== 'cfoai') return { kind: 'error', message: 'login expects an integration: cfoai' };
151	    if (extra.length > 1) return { kind: 'error', message: `unexpected argument "${extra[1]}"` };
152	  } else if (name === 'traces') {
153	    if (extra.length !== 1 || extra[0] !== 'drain' || !values.run) return { kind: 'error', message: 'traces expects drain --run <id>' };
154	    if (!/^[a-zA-Z0-9_-]+$/.test(values.run)) return { kind: 'error', message: 'Invalid run id' };
155	    if (values['dry-run'] || values.plan) return { kind: 'error', message: 'traces drain verifies real delivery; --dry-run and --plan are not supported' };
156	  } else if (extra.length > 0) {
157	    return { kind: 'error', message: `unexpected argument "${extra[0]}"` };
158	  }
159	
160	  let budgetUsd: number | undefined;
161	  if (values.budget !== undefined) {
162	    budgetUsd = Number(values.budget);
163	    if (!Number.isFinite(budgetUsd) || budgetUsd <= 0) {
164	      return { kind: 'error', message: `--budget must be a positive number of USD, got "${values.budget}"` };
165	    }
166	  }
167	  let port: number | undefined;
168	  if (values.port !== undefined) {
169	    port = Number(values.port);
170	    if (!Number.isInteger(port) || port < 0 || port > 65535) {
171	      return { kind: 'error', message: `--port must be an integer from 0 to 65535, got "${values.port}"` };
172	    }
173	  }
174	  let limit: number | undefined;
175	  let repeats: number | undefined;
176	  if (values.repeats !== undefined) {
177	    repeats = Number(values.repeats);
178	    if (!Number.isInteger(repeats) || repeats < 1) return { kind: 'error', message: '--repeats must be a positive integer' };
179	  }
180	  if (values.limit !== undefined) {
181	    limit = Number(values.limit);
182	    if (!Number.isInteger(limit) || limit <= 0 || limit > 100) {
183	      return { kind: 'error', message: `--limit must be an integer from 1 to 100, got "${values.limit}"` };
184	    }
185	  }
186	  return {
187	    kind: 'command',
188	    command: name as Command,
189	    options: {
190	      config: values.config,
191	      dryRun: values['dry-run'],
192	      baseline: values.baseline,
193	      budgetUsd,
194	      only: values.only,
195	      dashboard: values.dashboard || values.open,
196	      port,
197	      plan: values.plan,
198	      live: values.live,
199	      ...(values.yes ? { yes: true } : {}),
200	      ...(repeats === undefined ? {} : { repeats }),
201	      loginTarget: name === 'login' ? 'cfoai' : undefined,
202	      output: values.output,
203	      limit,
204	      keyword: values.keyword,
205	      ...(values.out !== undefined ? { out: values.out } : {}),
206	      ...(values.runs !== undefined ? { runs: values.runs.split(',') } : {}),
207	      ...(values.run !== undefined ? { runId: values.run } : {}),
208	    },
209	  };
210	}
