214	async function runCommand(options: CliOptions, io: CliIO): Promise<number> {
215	  try {
216	    if (options.plan) {
217	      const budget = await readPlanBudget(loadConfig(options.config), { budgetUsd: options.budgetUsd });
218	      io.stdout(`budget: ${formatUsd(budget.limitNanos)} from ${budget.source === 'cfoai' ? 'cfo.ai' : 'tally.yaml'}`);
219	      const plan = await planTally({
220	        configPath: options.config,
221	        dryRun: options.dryRun,
222	        baseline: options.baseline,
223	        budgetUsd: options.budgetUsd,
224	        only: options.only,
225	      });
226	      for (const task of plan) {
227	        const route = task.skipped
228	          ? 'skip'
229	          : `${task.tier} ${task.harness}/${task.model} ceiling ${task.ceilingNanos === null ? 'none' : formatUsd(task.ceilingNanos)}`;
230	        io.stdout(`${task.taskId}: ${task.size} -> ${route}`);
231	        io.stdout(`  ${task.decision}`);
232	      }
