234	    }
235	    const result = await runTally({
236	      configPath: options.config,
237	      dryRun: options.dryRun,
238	      baseline: options.baseline,
239	      budgetUsd: options.budgetUsd,
240	      only: options.only,
241	    });
242	    io.stdout(`wrote ${result.runStatePath}`);
243	    io.stdout(`wrote ${result.ledgerPath}`);
244	    io.stdout(`updated ${result.latestRunDir}`);
245	    io.stdout(`finished ${result.runState.runId}: ${result.runState.tasks.length} tasks, ${result.ledger.length} attempts`);
246	    if (result.runState.tasks.length === 0 && result.runState.backlog?.source === 'github-issues') {
247	      const label = result.runState.backlog.issueLabel ?? 'tally';
248	      const quote = (value: string) => `'${value.replace(/'/g, "'\\''")}'`;
249	      io.stdout(`No matching open issues with label ${JSON.stringify(label)} in ${result.runState.repo}; nothing started. Label an issue with: gh issue edit <issue-number> --repo ${quote(result.runState.repo)} --add-label ${quote(label)}`);
250	    }
251	    printIntegrations(result, io);
252	    if (options.dashboard) await dashboardCommand(options, io);
253	    return 0;
254	  } catch (e) {
255	    return reportError('tally run', e, io);
256	  }
257	}
