 37	export class RunError extends Error {
 38	  constructor(readonly problems: string[]) {
 39	    super(problems.join('; '));
 40	    this.name = 'RunError';
 41	  }
 42	}
 43	
 44	export async function runTally(options: RunOptions | RealRunOptions): Promise<RunResult> {
 45	  const config = loadConfig(options.configPath);
 46	  if (!options.dryRun) await validateRealRunConfig(config, options.configPath, options.preflightRunner);
 47	  const ports = options.dryRun ? { ...createDryRunPorts({ config, configPath: options.configPath }), ...(options as RealRunOptions).ports } : (options as RealRunOptions).ports;
 48	  return runRealTally({ ...(options as RealRunOptions), ...(ports ? { ports } : {}) });
 49	}
 50	
 51	function demoConfigPath(live = false): string {
 52	  const file = live ? 'tally.live.yaml' : 'tally.yaml';
 53	  const candidates = [
 54	    resolve('demo', file),
 55	    fileURLToPath(new URL(`../demo/${file}`, import.meta.url)),
 56	    fileURLToPath(new URL(`../../demo/${file}`, import.meta.url)),
 57	  ];
 58	  return candidates.find((candidate) => existsSync(candidate)) ?? candidates[0]!;
 59	}
 60	
 61	export async function runDemo(options: Pick<RunOptions, 'outputDir' | 'latestRunDir' | 'now'> & { live?: boolean } = {}): Promise<RunResult> {
 62	  return runTally({
 63	    configPath: demoConfigPath(options.live),
 64	    dryRun: true,
 65	    baseline: false,
 66	    outputDir: options.outputDir,
 67	    latestRunDir: options.latestRunDir ?? DEFAULT_LATEST_RUN_DIR,
 68	    now: options.now,
 69	  });
 70	}
