 23	  tasks: number; passed: number; failed: number; skipped: number; attempts: number;
 24	  totalCostNanos: number; costPerPassedTaskNanos: number | null; passRate: number;
 25	  neatlogsSessionId: string | null;
 26	}
 27	interface ModeSummary {
 28	  runs: ExperimentRun[];
 29	  totalCostNanos: Spread; costPerPassedTaskNanos: Spread; passRate: Spread;
 30	}
