 35	export interface ExperimentSummary {
 36	  schemaVersion: 1; experimentId: string; status: 'running' | 'finished' | 'stopped';
 37	  real: boolean; repo: string; baseCommit: string; taskIds: string[]; repeatsPlanned: number;
 38	  startedAt: string; endedAt: string | null;
 39	  budget: { capNanos: number; spentNanos: number };
 40	  modes: Record<RunMode, ModeSummary>;
 41	  perTask: Array<{ taskId: string; baseline: TaskOutcome[]; tally: TaskOutcome[] }>;
 42	  comparison: { totalCostChangePct: number | null; costPerPassedTaskChangePct: number | null; passRateChangePoints: number | null; note: string };
 43	  reason?: string;
 44	}
 45	
 46	function spread(values: Array<number | null>): Spread {
 47	  // Undefined cost per pass must not disappear from the comparison.
 48	  if (!values.length || values.some((value) => value === null)) return { min: null, median: null, max: null };
 49	  const sorted = [...values as number[]].sort((a, b) => a - b);
 50	  const middle = Math.floor(sorted.length / 2);
 51	  return { min: sorted[0]!, median: sorted.length % 2 ? sorted[middle]! : (sorted[middle - 1]! + sorted[middle]!) / 2, max: sorted.at(-1)! };
 52	}
 53	function percent(before: number | null, after: number | null): number | null {
 54	  return before === null || after === null || before === 0 ? null : (after - before) / before * 100;
 55	}
 56	export function updateExperimentSummary(summary: ExperimentSummary, result: RunResult, repeat: number): void {
 57	  const run = result.runState;
 58	  const passed = run.tasks.filter((task) => task.status === 'passed').length;
 59	  const mode = summary.modes[run.mode];
 60	  mode.runs.push({ runId: run.runId, repeat, path: `/runs/${encodeURIComponent(run.runId)}/`, status: run.status,
 61	    tasks: run.tasks.length, passed, failed: run.tasks.filter((task) => task.status === 'failed').length,
 62	    skipped: run.tasks.filter((task) => task.status === 'skipped').length, attempts: run.tasks.reduce((sum, task) => sum + task.attempts, 0),
 63	    totalCostNanos: run.budget.spentNanos, costPerPassedTaskNanos: passed ? run.budget.spentNanos / passed : null,
 64	    passRate: run.tasks.length ? passed / run.tasks.length : 0,
 65	    neatlogsSessionId: run.integrations.neatlogs.status === 'ok' ? run.runId : null });
 66	  summary.budget.spentNanos += run.budget.spentNanos;
 67	  for (const task of run.tasks) {
 68	    const entry = summary.perTask.find((item) => item.taskId === task.taskId);
 69	    if (!entry) throw new RunError([`experiment backlog changed: unexpected task ${task.taskId}`]);
 70	    entry[run.mode].push({ runId: run.runId, repeat, tier: task.tier, model: task.model, result: task.status, attempts: task.attempts, costNanos: task.spentNanos });
 71	  }
 72	  for (const value of Object.values(summary.modes)) {
 73	    const finished = value.runs.filter((item) => item.status === 'finished');
 74	    value.totalCostNanos = spread(finished.map((item) => item.totalCostNanos));
 75	    value.costPerPassedTaskNanos = spread(finished.map((item) => item.costPerPassedTaskNanos));
 76	    value.passRate = spread(finished.map((item) => item.passRate));
 77	  }
 78	  const baseline = summary.modes.baseline;
 79	  const tally = summary.modes.tally;
 80	  summary.comparison.totalCostChangePct = percent(baseline.totalCostNanos.median, tally.totalCostNanos.median);
 81	  summary.comparison.costPerPassedTaskChangePct = percent(baseline.costPerPassedTaskNanos.median, tally.costPerPassedTaskNanos.median);
 82	  summary.comparison.passRateChangePoints = baseline.passRate.median === null || tally.passRate.median === null ? null : (tally.passRate.median - baseline.passRate.median) * 100;
 83	}
 84	export function writeExperimentSummary(path: string, summary: ExperimentSummary): void {
 85	  mkdirSync(dirname(path), { recursive: true });
 86	  const temporary = `${path}.tmp`;
 87	  writeFileSync(temporary, `${JSON.stringify(summary, null, 2)}\n`);
 88	  renameSync(temporary, path);
 89	}
