 92	export class ExperimentWorker implements WorkerPort, FinalUsagePort, SessionControlPort {
 93	  private readonly costs = new Map<string, number>();
 94	  private readonly inputs = new Map<string, WorkerStartInput>();
 95	  private readonly closed = new Set<string>();
 96	  reason: string | null = null;
 97	  constructor(private readonly ports: { worker: WorkerPort; usage: LiveUsagePort; sessions: SessionControlPort },
 98	    private readonly capNanos: number, private readonly spentBeforeNanos: number, private readonly intervalMs = 1000) {}
 99	  private get spent(): number { return this.spentBeforeNanos + [...this.costs.values()].reduce((sum, cost) => sum + cost, 0); }
100	  stopReason(): string | null { return this.reason ?? (this.spent >= this.capNanos ? EXPERIMENT_CAP_REASON : null); }
101	  async start(input: WorkerStartInput) {
102	    const reason = this.stopReason();
103	    if (reason) throw new RunError([reason]);
104	    const started = await this.ports.worker.start(input);
105	    this.inputs.set(started.sessionId, input);
106	    this.costs.set(started.sessionId, 0);
107	    return started;
108	  }
109	  private record(sessionId: string, usage: Awaited<ReturnType<LiveUsagePort['usageFor']>>) {
110	    const input = this.inputs.get(sessionId);
111	    if (usage && input) this.costs.set(sessionId, Math.max(this.costs.get(sessionId) ?? 0, checkCeiling(usage, { sessionId, tier: input.tier, ceilingNanos: null }).costNanos));
112	    return usage;
113	  }
114	  async usageFor(sessionId: string) { return this.record(sessionId, await this.ports.usage.usageFor(sessionId)); }
115	  async settledUsageFor(sessionId: string) {
116	    const port = this.ports.usage as FinalUsagePort;
117	    return this.record(sessionId, await (port.settledUsageFor?.(sessionId) ?? port.usageFor(sessionId)));
118	  }
119	  async stop(sessionId: string, reason: string) {
120	    if (this.closed.has(sessionId)) return;
121	    try { await this.ports.sessions.stop(sessionId, reason); }
122	    catch (error) { throw new RunError([`could not close experiment worker ${sessionId}: ${error instanceof Error ? error.message : String(error)}`]); }
123	    this.closed.add(sessionId);
124	  }
125	  async closeAll(reason: string): Promise<void> {
126	    for (const sessionId of this.inputs.keys()) {
127	      await this.stop(sessionId, reason);
128	      await this.settledUsageFor(sessionId);
129	    }
130	  }
131	  async wait(sessionId: string, options?: { timeoutMs?: number }): Promise<WorkerResult> {
132	    const abort = new AbortController();
133	    const watch = async (): Promise<WorkerResult | null> => {
134	      while (!abort.signal.aborted) {
135	        try { await this.usageFor(sessionId); }
136	        catch { this.reason = 'stopped: experiment usage unavailable'; }
137	        const reason = this.stopReason();
138	        if (reason) {
139	          this.reason = reason;
140	          await this.stop(sessionId, reason);
141	          return { status: 'experiment_stop', branch: null, checkoutPath: null, prUrl: null, resultReason: reason };
142	        }
143	        try { await delay(this.intervalMs, undefined, { signal: abort.signal }); } catch { return null; }
144	      }
145	      return null;
146	    };
147	    const watched = watch();
148	    let result: WorkerResult | null;
149	    try {
150	      result = await Promise.race([watched, this.ports.worker.wait(sessionId, options)]);
151	    } finally { abort.abort(); await watched; }
152	    if (!result) throw new RunError(['experiment watcher ended before worker completion']);
153	    return this.reason ? { ...result, status: 'experiment_stop', resultReason: this.reason } : result;
154	  }
155	}
