157	export interface ExperimentOptions {
158	  configPath: string; dryRun: boolean; repeats?: number; budgetUsd?: number; only?: string;
159	  runsDir?: string; now?: () => Date; baseCommit?: string;
160	  ports?: Partial<RealRunPorts>;
161	}
162	export async function runExperiment(options: ExperimentOptions): Promise<{ summary: ExperimentSummary; summaryPath: string }> {
163	  if (!options.dryRun) throw new RunError(['real experiments are parked; use --dry-run until real execution is explicitly enabled']);
164	  const repeats = options.repeats ?? 2;
165	  if (!Number.isInteger(repeats) || repeats < 1) throw new RunError(['--repeats must be a positive integer']);
166	  const configPath = resolve(options.configPath);
167	  const config = loadConfig(configPath);
168	  if (!options.dryRun && !config.test.timeoutSec) throw new RunError(['real experiments require test.timeoutSec for a bounded wall-clock wait']);
169	  const repoPath = resolve(dirname(configPath), config.repo.path);
170	  let baseCommit = options.baseCommit;
171	  if (!baseCommit) {
172	    try { baseCommit = (await execFileAsync('git', ['rev-parse', '--verify', '--end-of-options', `${config.repo.baseBranch}^{commit}`], { cwd: repoPath })).stdout.trim(); }
173	    catch { throw new RunError([`could not determine experiment base commit in ${repoPath}`]); }
174	  }
175	  if (!/^[a-f0-9]{40}$/.test(baseCommit)) throw new RunError(['experiment base must be a full Git commit SHA']);
176	  const intake = options.ports?.intake ?? new ConfigBacklogIntake();
177	  const tasks = (await intake.tasks(config, configPath)).filter((task) => options.only === undefined || task.taskId === options.only || String(task.issueNumber) === options.only);
178	  if (!tasks.length) throw new RunError(['experiment backlog contains no selected tasks']);
179	  const capNanos = usdToNanos(options.budgetUsd ?? config.budget.usd);
180	  if (!Number.isSafeInteger(capNanos) || capNanos <= 0) throw new RunError(['experiment budget must be positive and finite']);
181	  const now = options.now ?? (() => new Date());
182	  const started = now();
183	  const stamp = started.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}Z$/, 'Z').replace('T', '-');
184	  const experimentId = `exp-${stamp}`;
185	  const runsDir = resolve(options.runsDir ?? '.tally/runs');
186	  const summaryPath = join(runsDir, 'experiments', experimentId, 'summary.json');
187	  if (existsSync(summaryPath)) throw new RunError([`experiment already exists: ${experimentId}`]);
188	  const empty = (): ModeSummary => ({ runs: [], totalCostNanos: spread([]), costPerPassedTaskNanos: spread([]), passRate: spread([]) });
189	  const summary: ExperimentSummary = { schemaVersion: 1, experimentId, status: 'running', real: !options.dryRun,
190	    repo: config.repo.slug ?? config.repo.path, baseCommit, taskIds: tasks.map((task) => task.taskId), repeatsPlanned: repeats,
191	    startedAt: started.toISOString(), endedAt: null, budget: { capNanos, spentNanos: 0 }, modes: { baseline: empty(), tally: empty() },
192	    perTask: tasks.map((task) => ({ taskId: task.taskId, baseline: [], tally: [] })),
193	    comparison: { totalCostChangePct: null, costPerPassedTaskChangePct: null, passRateChangePoints: null, note: 'medians of the repeats; negative cost change means Tally was cheaper' } };
194	  writeExperimentSummary(summaryPath, summary);
195	  try {
196	    for (let repeat = 1; repeat <= repeats; repeat += 1) {
197	      for (const mode of ['baseline', 'tally'] as const) {
198	        if (summary.budget.spentNanos >= capNanos) { summary.status = 'stopped'; summary.reason = EXPERIMENT_CAP_REASON; break; }
199	        const defaults = options.dryRun ? { ...createDryRunPorts({ config, configPath }),
200	          worktrees: { commitFor: async () => baseCommit, checkoutPathFor: async () => null } } : (() => {
201	          const ao = new AoCliAdapter({ cwd: repoPath, project: config.repo.aoProject, requiredBaseCommit: baseCommit });
202	          return { worker: ao, usage: ao, sessions: ao };
203	        })();
204	        const ports = { ...defaults, ...options.ports };
205	        const guarded = new ExperimentWorker({ worker: ports.worker!, usage: ports.usage!, sessions: ports.sessions! }, capNanos, summary.budget.spentNanos, options.dryRun ? 1 : 1000);
206	        const runId = `run-${stamp}-${mode}-${repeat}`;
207	        const outputDir = join(runsDir, runId);
208	        if (existsSync(outputDir)) throw new RunError([`experiment run directory already exists: ${outputDir}`]);
209	        let result: RunResult;
210	        try {
211	          result = await runTally({ configPath, dryRun: options.dryRun, baseline: mode === 'baseline',
212	            budgetUsd: nanosToUsd(capNanos - summary.budget.spentNanos), outputDir, latestRunDir: join(runsDir, 'latest'), now, runId, repeat, requiredBaseCommit: baseCommit,
213	            stopRequested: () => guarded.stopReason(), ports: { ...ports, intake: { tasks: async () => structuredClone(tasks) }, worker: guarded, usage: guarded, sessions: guarded } });
214	        } catch (error) {
215	          await guarded.closeAll('experiment run failed');
216	          const runPath = join(outputDir, 'run.json');
217	          const ledgerPath = join(outputDir, 'ledger.json');
218	          if (existsSync(runPath) && existsSync(ledgerPath)) {
219	            const runState = JSON.parse(readFileSync(runPath, 'utf8')) as RunState;
220	            const ledger = JSON.parse(readFileSync(ledgerPath, 'utf8')) as Ledger;
221	            runState.status = 'interrupted';
222	            runState.endedAt = now().toISOString();
223	            const written = writeRunFiles(outputDir, runState, ledger, join(runsDir, 'latest'));
224	            updateExperimentSummary(summary, { ...written, runState, ledger }, repeat);
225	          }
226	          throw error;
227	        }
228	        updateExperimentSummary(summary, result, repeat);
229	        if (guarded.stopReason()) { summary.status = 'stopped'; summary.reason = guarded.stopReason()!; }
230	        writeExperimentSummary(summaryPath, summary);
231	        if (summary.status === 'stopped') break;
232	      }
233	      if (summary.status === 'stopped') break;
234	    }
235	    if (summary.status === 'running') summary.status = 'finished';
236	  } catch (error) {
237	    summary.status = 'stopped'; summary.reason = error instanceof Error ? error.message : String(error);
238	    throw error instanceof RunError ? error : new RunError([summary.reason]);
239	  } finally {
240	    summary.endedAt = now().toISOString();
241	    writeExperimentSummary(summaryPath, summary);
242	  }
243	  return { summary, summaryPath };
244	}
