 12	export async function recoverRunTraces(options: {
 13	  runId: string;
 14	  outputDir?: string;
 15	  drain?: WorkerTraceDrainPort;
 16	  reader?: WorkerTraceReaderPort;
 17	  now?: () => Date;
 18	}): Promise<{ before: RunState['integrations']['neatlogs']; after: RunState['integrations']['neatlogs']; traceIds: string[] }> {
 19	  if (!/^[a-zA-Z0-9_-]+$/.test(options.runId)) throw new Error('Invalid run id');
 20	  const outputDir = resolve(options.outputDir ?? join('.tally', 'runs', options.runId));
 21	  const runPath = join(outputDir, 'run.json');
 22	  const ledgerPath = join(outputDir, 'ledger.json');
 23	  const originalRun = readFileSync(runPath, 'utf8');
 24	  const originalLedger = readFileSync(ledgerPath, 'utf8');
 25	  const run = JSON.parse(originalRun) as RunState;
 26	  const ledger = JSON.parse(originalLedger) as Ledger;
 27	  if (!validateRunState(run).ok || !validateLedger(ledger).ok) throw new Error('Invalid saved run or ledger');
 28	  if (run.runId !== options.runId || ledger.some(r => r.runId !== run.runId)) throw new Error('Run id does not match saved evidence');
 29	  if (run.status !== 'finished' || run.dryRun || run.integrations.neatlogs.status === 'off') throw new Error('Only finished real runs with neatlogs enabled can be recovered');
 30	  const workers = ledger.filter(r => r.sessionId && r.costSource !== 'simulated' && r.harness !== 'entire');
 31	  if (!workers.length || workers.some(r => !r.entireSessionId)) throw new Error('Native session evidence is required for every worker attempt');
 32	  const drain = options.drain ?? new NeatlogsWorkerSpoolAdapter();
 33	  const reader = options.reader ?? new NeatlogsWorkerTraceReader();
 34	  const before = { ...run.integrations.neatlogs };
 35	  const traceIds: string[] = [];
 36	  for (const row of workers) {
 37	    await drain.drainWorker({ checkoutPath: null, entireSessionId: row.entireSessionId });
 38	    if (drain.status && drain.status().status !== 'ok') throw new Error('Worker batches remain pending; saved status was not changed');
 39	    const id = await reader.verifyFor({ runId: row.runId, taskId: row.taskId, attempt: row.attempt, nativeSessionId: row.entireSessionId!, traceId: row.workerTraceId });
 40	    if (!id) throw new Error(`Worker trace read-back failed for ${row.taskId} attempt ${row.attempt}; saved status was not changed`);
 41	    row.workerTraceId = id;
 42	    traceIds.push(id);
 43	  }
 44	  const completed = (options.now ?? (() => new Date()))().toISOString();
 45	  run.updatedAt = completed;
 46	  run.integrations.neatlogs = { status: 'ok', detail: `Worker trace delivery completed after the run at ${completed}; read-back verified: ${[...new Set(traceIds)].join(', ')}.` };
 47	  if (!validateRunState(run).ok || !validateLedger(ledger).ok) throw new Error('Recovered evidence failed schema validation');
 48	  if (readFileSync(runPath, 'utf8') !== originalRun || readFileSync(ledgerPath, 'utf8') !== originalLedger) throw new Error('Saved run changed during recovery; refusing to overwrite');
 49	  if (!existsSync(`${runPath}.before-trace-recovery`)) writeFileSync(`${runPath}.before-trace-recovery`, originalRun);
 50	  if (!existsSync(`${ledgerPath}.before-trace-recovery`)) writeFileSync(`${ledgerPath}.before-trace-recovery`, originalLedger);
 51	  // Write verified attempt evidence first, then the status that references it.
 52	  replaceJson(ledgerPath, ledger);
 53	  replaceJson(runPath, run);
 54	  const latestDir = join(dirname(outputDir), 'latest');
 55	  const latestPath = join(latestDir, 'run.json');
 56	  if (existsSync(latestPath) && (JSON.parse(readFileSync(latestPath, 'utf8')) as RunState).runId === run.runId) {
 57	    replaceJson(join(latestDir, 'ledger.json'), ledger);
 58	    replaceJson(latestPath, run);
 59	  }
 60	  return { before, after: run.integrations.neatlogs, traceIds };
 61	}

