 99	function jsonVerdict(text: string): { newlyFailing: string[]; newlyPassing: string[]; preExisting: string[] } | null {
100	  try {
101	    const parsed = JSON.parse(text) as Record<string, unknown>;
102	    return {
103	      newlyFailing: listFrom(parsed.newly_failing ?? parsed.newlyFailing ?? parsed.new_failures),
104	      newlyPassing: listFrom(parsed.newly_passing ?? parsed.newlyPassing ?? parsed.new_passes),
105	      preExisting: listFrom(parsed.pre_existing ?? parsed.preExisting ?? parsed.pre_existing_failures),
106	    };
107	  } catch {
108	    return null;
109	  }
110	}
111	
112	function lineList(text: string, label: RegExp): string[] {
113	  const line = text.split(/\r?\n/).find((candidate) => label.test(candidate));
114	  if (!line) return [];
115	  if (/\b0\b|none/i.test(line) && !/:\s*[^0\s]/.test(line)) return [];
116	  const after = line.includes(':') ? line.slice(line.indexOf(':') + 1) : line;
117	  return after
118	    .split(/,\s*|\s{2,}|;\s*/)
119	    .map((item) => item.replace(label, '').trim())
120	    .filter((item) => item !== '' && !/^0$|^none$/i.test(item))
121	    .slice(0, 20);
122	}
