124	export function parseEntireVerifyVerdict(output: string, code: number): VerifyResult {
125	  const structured = jsonVerdict(output);
126	  const newlyFailing = structured?.newlyFailing ?? lineList(output, /newly[-_\s]+fail(?:ing|ed)?/i);
127	  const newlyPassing = structured?.newlyPassing ?? lineList(output, /newly[-_\s]+pass(?:ing|ed)?/i);
128	  const preExisting = structured?.preExisting ?? lineList(output, /pre[-_\s]+existing/i);
129	  const notes = [
130	    newlyPassing.length > 0 ? `newly passing tests: ${newlyPassing.join(', ')}` : null,
131	    preExisting.length > 0 ? `pre-existing failing tests: ${preExisting.join(', ')}` : null,
132	  ].filter((note): note is string => note !== null);
133	  if (newlyFailing.length > 0) {
134	    return {
135	      passed: false,
136	      reason: `newly failing tests: ${newlyFailing.join(', ')}${notes.length > 0 ? `; ${notes.join('; ')}` : ''}`,
137	    };
138	  }
139	  if (code === 0 || notes.length > 0) return { passed: true, reason: notes.length > 0 ? notes.join('; ') : null };
140	  const detail = output.trim().split(/\r?\n/).slice(-3).join('\n');
141	  return { passed: false, reason: `tests failed${detail ? `: ${detail}` : ''}` };
142	}
