144	export class EntireGraphVerifier implements VerifierPort {
145	  constructor(
146	    private readonly fallback = new CommandVerifier(),
147	    private readonly runEntire: EntireVerifyRunner = defaultEntireRunner,
148	    private readonly resolveWorktree: WorktreeResolver = defaultWorktreeResolver,
149	  ) {}
150	
151	  async verify(input: VerifyInput): Promise<VerifyResult> {
152	    const checkoutPath =
153	      input.checkoutPath ?? (input.branch && input.repoPath ? await this.resolveWorktree(input.repoPath, input.branch) : null);
154	    if (!checkoutPath) return { passed: false, reason: 'worker checkout path was not reported and branch worktree was not found' };
155	    const baseline = join(mkdtempSync(join(tmpdir(), 'tally-entire-verify-')), 'baseline.json');
156	    const setup = input.config.test.setupCommand ? ['--setup', input.config.test.setupCommand] : [];
157	    const maxBytes = ['--max-bytes', '2048'];
158	    if (input.repoPath) {
159	      const recorded = await this.runEntire(
160	        ['graph', 'verify', '--repo', input.repoPath, '--test', input.config.test.command, ...setup, '--record-baseline', baseline, ...maxBytes],
161	        { cwd: input.repoPath },
162	      );
163	      if (recorded.code !== 0 && /unknown command|not found|No such file|not installed/i.test(`${recorded.stderr}\n${recorded.stdout}`)) {
164	        return this.fallback.verify(input);
165	      }
166	      const verified = await this.runEntire(
167	        ['graph', 'verify', '--repo', checkoutPath, '--test', input.config.test.command, ...setup, '--pre-edit-baseline', baseline, ...maxBytes],
168	        { cwd: checkoutPath },
169	      );
170	      return parseEntireVerifyVerdict(`${verified.stdout}\n${verified.stderr}`, verified.code);
171	    }
172	    const verified = await this.runEntire(['graph', 'verify', '--repo', checkoutPath, '--test', input.config.test.command, ...setup, ...maxBytes], {
173	      cwd: checkoutPath,
174	    });
175	    if (verified.code !== 0 && /unknown command|not found|No such file|not installed/i.test(`${verified.stderr}\n${verified.stdout}`)) {
176	      return this.fallback.verify(input);
177	    }
178	    return parseEntireVerifyVerdict(`${verified.stdout}\n${verified.stderr}`, verified.code);
179	  }
180	}
  1	/**
  2	 * Sizer: turns the sizing signals and the issue text into a size and a
  3	 * confidence score. The rules are deterministic; an LLM may refine the
  4	 * result but can only make the estimate more cautious about cost, never
  5	 * cheaper on its own word.
  6	 */
  7	import type { TaskSize } from '../schema/types.js';
  8	import type { CheckpointRecall, LlmPort, SizingSignals, SizingSignalsPort, TaskInput, TracePort } from './ports.js';
  9	import { traceDecision } from './trace.js';
 10	
 11	export interface SizeEstimate {
 12	  size: TaskSize;
 13	  /** How sure the sizer is that the task is what it looks like, in [0, 1]. */
 14	  confidence: number;
 15	  /** Null when nothing could be measured. */
 16	  signals: SizingSignals | null;
 17	  /** How specific the issue text is, in [0, 1]. */
 18	  specificity: number;
 19	  refinedBy: 'rules' | 'llm';
 20	  /** The signals in plain words, for the decision sentence. */
 21	  summary: string;
 22	  recall: CheckpointRecall | null;
 23	}
 24	
 25	export interface SizerOptions {
 26	  /** Model id for the optional refinement call. Use a cheap one. */
 27	  llmModel?: string;
 28	}
 29	
 30	const SIZES: TaskSize[] = ['small', 'medium', 'large'];
 31	
 32	/** Upper bounds for small and medium; anything above is large. */
 33	const FILE_LIMITS = [2, 7] as const;
 34	const DEPENDENT_LIMITS = [3, 11] as const;
 35	
 36	const BROAD = /\b(refactor\w*|rewrit\w*|rewrote|migrat\w*|redesign\w*|overhaul\w*|re-?architect\w*|everywhere|across the)\b/i;
 37	const CODE_REFERENCE = /`[^`]+`|\b[\w./-]+\.[a-z]{1,5}\b|\b\w+\(\)|\b[\w-]+\/[\w-]+\/[\w./-]+/;
 38	const EXPECTED_BEHAVIOUR = /\b(should|expected|must|instead of|returns?|raises?|throws?|fails?|error)\b/i;
 39	const STEPS_OR_OUTPUT = /^\s*(\d+[.)]|[-*])\s+\S|```|Traceback|\bat .+:\d+/m;
 40	
 41	function clamp01(value: number): number {
 42	  return Math.min(1, Math.max(0, value));
 43	}
 44	
 45	function round2(value: number): number {
 46	  return Math.round(value * 100) / 100;
 47	}
 48	
 49	function bucket(value: number, limits: readonly [number, number]): number {
 50	  if (value <= limits[0]) return 0;
 51	  return value <= limits[1] ? 1 : 2;
 52	}
 53	
 54	/** How precisely the issue says what to change, from 0 (a wish) to 1 (a pinned-down case). */
 55	export function specificity(task: TaskInput): number {
 56	  const text = `${task.title}\n${task.body}`;
 57	  let score = 0;
 58	  if (CODE_REFERENCE.test(text)) score += 0.35;
 59	  if (EXPECTED_BEHAVIOUR.test(text)) score += 0.25;
 60	  if (task.body.trim().length >= 80) score += 0.2;
 61	  if (STEPS_OR_OUTPUT.test(task.body)) score += 0.2;
 62	  return round2(clamp01(score));
 63	}
 64	
 65	function plural(count: number, noun: string): string {
 66	  return `${count} ${noun}${count === 1 ? '' : 's'}`;
 67	}
 68	
 69	function summarise(signals: SizingSignals | null): string {
 70	  if (!signals) return 'no sizing signals';
 71	  const files = `${plural(signals.filesTouched, 'file')} touched`;
 72	  const dependents = signals.dependents === 0 ? 'no dependents' : plural(signals.dependents, 'dependent');
 73	  return `${files}, ${dependents} and ${signals.testsPresent ? 'tests present' : 'no tests'}`;
 74	}
 75	
 76	/** The deterministic rules. */
 77	export function sizeFromSignals(task: TaskInput, signals: SizingSignals | null): SizeEstimate {
 78	  const specific = specificity(task);
 79	  const broad = BROAD.test(`${task.title}\n${task.body}`);
 80	  const base = { signals, specificity: specific, refinedBy: 'rules' as const, summary: summarise(signals), recall: null };
 81	
 82	  if (!signals || signals.source === 'none') {
 83	    // Nothing measured: assume the middle and admit it is a guess.
 84	    return { ...base, size: broad ? 'large' : 'medium', confidence: round2(Math.min(0.3, 0.15 + specific * 0.15)) };
 85	  }
 86	
 87	  const files = bucket(signals.filesTouched, FILE_LIMITS);
 88	  const dependents = bucket(signals.dependents, DEPENDENT_LIMITS);
 89	  const index = Math.min(2, files + (broad ? 1 : 0));
 90	
 91	  let confidence = 0.5;
 92	  confidence += signals.testsPresent ? 0.2 : -0.15;
 93	  confidence += specific * 0.25;
 94	  confidence -= dependents * 0.1;
 95	  if (signals.source === 'code-search') confidence -= 0.1;
 96	  if (broad) confidence -= 0.1;
 97	
 98	  return { ...base, size: SIZES[index]!, confidence: round2(clamp01(confidence)) };
 99	}
100	
101	export function applyCheckpointRecall(estimate: SizeEstimate, recall: CheckpointRecall | null): SizeEstimate {
102	  if (!recall?.failed) return estimate;
103	  const confidence = round2(clamp01(estimate.confidence - 0.15));
104	  const files = recall.files.length > 0 ? ` on ${recall.files.slice(0, 2).join(', ')}` : '';
105	  return {
106	    ...estimate,
107	    confidence,
108	    recall,
109	    summary: `${estimate.summary}; a prior checkpoint failed${files} before`,
110	  };
111	}
112	
113	function buildPrompt(task: TaskInput, rules: SizeEstimate): string {
114	  const signals = rules.signals;
115	  return [
116	    'Estimate how big this coding task is for an autonomous coding agent.',
117	    '',
118	    `Title: ${task.title}`,
119	    `Issue: ${task.body.slice(0, 4000) || '(empty)'}`,
120	    '',
121	    signals
122	      ? `Files touched: ${signals.filesTouched}\nDependents: ${signals.dependents}\nTests present: ${signals.testsPresent ? 'yes' : 'no'}`
123	      : 'No code measurements are available.',
124	    `Rule-based estimate: ${rules.size}`,
125	    '',
126	    'small = one or two target files. medium = several target files. large = many target files or a broad change. Dependents lower confidence, not size.',
127	    'Reply with JSON only: {"size":"small|medium|large","confidence":<0 to 1, how sure you are>}',
128	  ].join('\n');
129	}
130	
131	function parseReply(text: string): { size: TaskSize; confidence: number } | null {
132	  const match = /\{[^{}]*\}/.exec(text);
133	  if (!match) return null;
134	  try {
135	    const parsed: unknown = JSON.parse(match[0]);
136	    if (typeof parsed !== 'object' || parsed === null) return null;
137	    const { size, confidence } = parsed as Record<string, unknown>;
138	    if (!SIZES.includes(size as TaskSize)) return null;
139	    if (typeof confidence !== 'number' || !(confidence >= 0 && confidence <= 1)) return null;
140	    return { size: size as TaskSize, confidence };
141	  } catch {
142	    return null;
143	  }
144	}
145	
146	async function refine(task: TaskInput, rules: SizeEstimate, llm: LlmPort, model?: string): Promise<SizeEstimate> {
147	  let reply: { size: TaskSize; confidence: number } | null;
148	  try {
149	    const response = await llm.complete({
150	      ...(model ? { model } : {}),
151	      system: 'You size software tasks. Answer with JSON only.',
152	      prompt: buildPrompt(task, rules),
153	      maxTokens: 60,
154	    });
155	    reply = parseReply(response.text);
156	  } catch {
157	    reply = null;
158	  }
159	  if (!reply) return rules;
160	
161	  if (reply.size === rules.size) {
162	    const confidence = clamp01((rules.confidence + reply.confidence) / 2 + 0.1);
163	    return { ...rules, confidence: round2(Math.max(rules.confidence, confidence)), refinedBy: 'llm' };
164	  }
165	  // Disagreement is itself a sign of uncertainty: take the larger size and trust it less.
166	  const size = SIZES[Math.max(SIZES.indexOf(rules.size), SIZES.indexOf(reply.size))]!;
167	  const confidence = clamp01(Math.min(rules.confidence, reply.confidence) - 0.15);
168	  return { ...rules, size, confidence: round2(confidence), refinedBy: 'llm' };
169	}
