 66	  async verify(input: VerifyInput): Promise<VerifyResult> {
 67	    const checkoutPath =
 68	      input.checkoutPath ?? (input.branch && input.repoPath ? await this.resolveWorktree(input.repoPath, input.branch) : null);
 69	    if (!checkoutPath) return { passed: false, reason: 'worker checkout path was not reported and branch worktree was not found' };
 70	    try {
 71	      if (input.config.test.setupCommand) {
