 80	      const error = e as { code?: unknown; signal?: unknown; stderr?: unknown; message?: string };
 81	      const detail = typeof error.stderr === 'string' && error.stderr.trim() ? error.stderr.trim().split('\n').slice(-3).join('\n') : error.message;
