 87	function listFrom(value: unknown): string[] {
 88	  if (Array.isArray(value)) return value.map((item) => String(item)).filter(Boolean).slice(0, 20);
 89	  if (typeof value === 'number') return value > 0 ? [`${value} tests`] : [];
 90	  if (typeof value === 'string' && value.trim() !== '' && value.trim() !== '0') return [value.trim()];
 91	  if (typeof value === 'object' && value !== null) {
 92	    const record = value as Record<string, unknown>;
 93	    const ids = record.ids ?? record.tests ?? record.test_ids ?? record.count;
 94	    return listFrom(ids);
 95	  }
 96	  return [];
 97	}
