112	function lineList(text: string, label: RegExp): string[] {
113	  const line = text.split(/\r?\n/).find((candidate) => label.test(candidate));
114	  if (!line) return [];
115	  if (/\b0\b|none/i.test(line) && !/:\s*[^0\s]/.test(line)) return [];
116	  const after = line.includes(':') ? line.slice(line.indexOf(':') + 1) : line;
117	  return after
118	    .split(/,\s*|\s{2,}|;\s*/)
119	    .map((item) => item.replace(label, '').trim())
120	    .filter((item) => item !== '' && !/^0$|^none$/i.test(item))
121	    .slice(0, 20);
122	}
