 58	export interface SkipDecision {
 59	  action: 'skip';
 60	  taskId: string;
 61	  size: TaskSize;
 62	  confidence: number;
 63	  /** Goes into TaskState.statusReason. */
 64	  statusReason: 'not started: no budget';
 65	  reason: string;
