 68	export type RouteDecision = StartDecision | SkipDecision;
 69	
 70	export interface RouteInput {
 71	  task: TaskInput;
 72	  estimate: SizeEstimate;
 73	  config: TallyConfig;
 74	  ports: { history?: PriceHistoryPort; budget: BudgetPort; trace?: TracePort };
 75	  options?: Partial<RoutingOptions>;
 76	  traceAttributes?: TraceAttributes;
 77	}
 78	
 79	export function usd(nanos: number): string {
 80	  return formatUsd(nanos);
 81	}
 82	
 83	function percent(share: number): string {
 84	  return `${Math.round(share * 100)}%`;
 85	}
 86	
 87	function capitalise(text: string): string {
 88	  return text.charAt(0).toUpperCase() + text.slice(1);
 89	}
