 91	interface Candidate {
 92	  tier: Tier;
 93	  ceiling: number;
 94	  passRate: number;
 95	  avgCostNanos: number;
 96	  attempts: number;
 97	  source: 'history' | 'prior' | 'thin-history';
 98	  expected: number;
 99	  expectedOnPrior: number;
100	  neededConfidence: number;
101	  worthIt: boolean;
102	  worthItOnPrior: boolean;
103	  confident: boolean;
104	  fits: boolean;
105	}
106	
107	interface PlanningEstimate {
108	  passRate: number;
109	  avgCostNanos: number;
110	  attempts: number;
111	  source: 'history' | 'prior' | 'thin-history';
112	}
113	
114	async function observedFor(history: PriceHistoryPort | undefined, size: TaskSize, tier: string): Promise<PriceStats | null> {
115	  try {
116	    const observed = (await history?.lookup(size, tier)) ?? null;
117	    return observed && observed.attempts > 0 ? observed : null;
118	  } catch {
119	    return null;
120	  }
121	}
122	
123	async function planningEstimate(input: {
124	  config: TallyConfig;
125	  history: PriceHistoryPort | undefined;
126	  size: TaskSize;
127	  tierName: string;
128	  minHistoryAttempts: number;
129	}): Promise<PlanningEstimate> {
130	  const prior = priorFor(input.config, input.size, input.tierName);
131	  const observed = await observedFor(input.history, input.size, input.tierName);
132	  if (!observed) return { ...prior, attempts: 0, source: 'prior' };
133	  if (observed.attempts < input.minHistoryAttempts) {
134	    return { ...prior, attempts: observed.attempts, source: 'thin-history' };
135	  }
136	  return { passRate: observed.passRate, avgCostNanos: observed.avgCostNanos, attempts: observed.attempts, source: 'history' };
137	}
138	
139	function neededConfidenceForRule(ceiling: number, passRate: number, topCost: number): number {
140	  if (ceiling <= 0) return 0;
141	  if (passRate <= 0 || topCost <= 0) return 1;
142	  return Math.min(1, ceiling / (passRate * topCost));
143	}
144	
145	async function routeTaskCore(input: RouteInput): Promise<RouteDecision> {
146	  const { task, estimate, config } = input;
147	  const options = { ...DEFAULT_ROUTING, ...input.options };
148	  const { size, confidence } = estimate;
149	  const top = config.tiers[config.tiers.length - 1];
150	  if (!top) throw new Error('tally.yaml has no tiers');
151	
152	  const remaining = Math.max(0, await input.ports.budget.remainingNanos());
153	  const topPlan = await planningEstimate({
154	    config,
155	    history: input.ports.history,
156	    size,
157	    tierName: top.name,
158	    minHistoryAttempts: options.minHistoryAttempts,
159	  });
160	  const topPriorCost = (await estimateFor(config, undefined, size, top.name, options.priorWeight)).avgCostNanos;
161	  const topCost = topPlan.avgCostNanos;
162	  const topCeiling = ceilingNanos(config, size, top);
163	  const subject = `${size} task with ${estimate.summary}`;
164	  const common = { taskId: task.taskId, size, confidence };
165	
166	  const cheaper: Candidate[] = [];
167	  for (const tier of config.tiers.slice(0, -1)) {
168	    const plan = await planningEstimate({
169	      config,
170	      history: input.ports.history,
171	      size,
172	      tierName: tier.name,
173	      minHistoryAttempts: options.minHistoryAttempts,
174	    });
175	    const prior = priorFor(config, size, tier.name);
176	    const ceiling = ceilingNanos(config, size, tier);
177	    const expected = Math.round(ceiling + (1 - plan.passRate) * topCost);
178	    const expectedOnPrior = Math.round(ceiling + (1 - prior.passRate) * topPriorCost);
179	    const neededConfidence = neededConfidenceForRule(ceiling, plan.passRate, topCost);
180	    cheaper.push({
181	      tier,
182	      ceiling,
183	      passRate: plan.passRate,
184	      avgCostNanos: plan.avgCostNanos,
185	      attempts: plan.attempts,
186	      source: plan.source,
187	      expected,
188	      expectedOnPrior,
189	      neededConfidence,
190	      worthIt: expected < topCost,
191	      worthItOnPrior: expectedOnPrior < topPriorCost,
192	      confident: confidence >= neededConfidence,
193	      fits: ceiling <= remaining,
194	    });
195	  }
196	
197	  const historyNote = (candidate: Candidate): string | null => {
198	    if (candidate.source === 'thin-history') {
199	      return `History has only ${candidate.attempts} ${candidate.tier.name} attempt${candidate.attempts === 1 ? '' : 's'} for ${size}, so it uses the prior`;
200	    }
201	    if (candidate.source === 'prior') return `No usable history exists for ${candidate.tier.name} on ${size}, so it uses the prior`;
202	    if (candidate.worthIt !== candidate.worthItOnPrior) {
203	      return `History changed the choice for ${candidate.tier.name}: ${candidate.attempts} attempts show a ${percent(candidate.passRate)} pass rate and ${usd(candidate.avgCostNanos)} average cost`;
204	    }
205	    return null;
206	  };
207	
208	  // Why the tiers below the chosen one were passed over, most telling first.
209	  const passedOver = (below: Candidate[]): string | null => {
210	    const unsure = below.find((c) => c.worthIt && !c.confident);
211	    if (unsure) {
212	      const note = historyNote(unsure);
213	      const reason = `${subject} is too uncertain for ${unsure.tier.name} (confidence ${confidence.toFixed(2)} of ${unsure.neededConfidence.toFixed(2)} needed)`;
214	      return note ? `${note}; ${reason}` : capitalise(reason);
215	    }
216	    const failing = below.find((c) => !c.worthIt);
217	    if (failing) {
218	      const note = historyNote(failing);
219	      const reason = `${failing.tier.name} is expected to fail ${percent(1 - failing.passRate)} of ${size} tasks, too often for an attempt capped at ${usd(failing.ceiling)} to beat ${usd(topCost)} on ${top.name}`;
220	      return note ? `${note}; ${reason}` : capitalise(reason);
221	    }
222	    return null;
223	  };
224	
225	  const chosenIndex = cheaper.findIndex((c) => c.worthIt && c.confident && c.fits);
226	  const chosen = cheaper[chosenIndex];
227	  if (chosen) {
228	    const why = passedOver(cheaper.slice(0, chosenIndex));
229	    const odds = `expected to cost ${usd(chosen.expected)} against ${usd(topCost)} for going straight to ${top.name}`;
230	    const note = historyNote(chosen);
231	    const reason = why
232	      ? `${why}, so it starts on ${chosen.tier.name} capped at ${usd(chosen.ceiling)}, ${odds}.`
233	      : note
234	        ? `${note}; ${subject} starts on ${chosen.tier.name} capped at ${usd(chosen.ceiling)}, ${odds}.`
235	        : `${capitalise(subject)}, so a ${chosen.tier.name} attempt capped at ${usd(chosen.ceiling)} is ${odds}.`;
236	    return {
237	      ...common,
238	      action: 'start',
239	      tier: chosen.tier,
240	      ceilingNanos: chosen.ceiling,
241	      expectedCostNanos: chosen.expected,
242	      topCostNanos: topCost,
243	      reason,
244	    };
245	  }
246	
247	  if (topCeiling <= remaining) {
248	    const why = passedOver(cheaper);
249	    const ending = `${top.name} with a ${usd(topCeiling)} ceiling`;
250	    return {
251	      ...common,
252	      action: 'start',
253	      tier: top,
254	      ceilingNanos: topCeiling,
255	      expectedCostNanos: topCost,
256	      topCostNanos: topCost,
257	      reason: why
258	        ? `${why}, so it goes straight to ${ending}.`
259	        : `${capitalise(subject)} goes to ${ending}, the only tier configured.`,
260	    };
261	  }
262	
263	  // The preferred tier does not fit. Take the strongest one that does, if it has a fair chance.
264	  const fallback = [...cheaper]
265	    .reverse()
266	    .find((c) => c.fits && c.passRate >= options.minPassRateOnTightBudget);
267	  if (fallback) {
268	    return {
269	      ...common,
270	      action: 'start',
271	      tier: fallback.tier,
272	      ceilingNanos: fallback.ceiling,
273	      expectedCostNanos: fallback.expected,
274	      topCostNanos: topCost,
275	      reason: `Only ${usd(remaining)} of budget is left, which does not cover the ${usd(topCeiling)} ceiling on ${top.name}, so this ${size} task gets a ${fallback.tier.name} attempt capped at ${usd(fallback.ceiling)}.`,
276	    };
277	  }
278	
279	  const smallest = Math.min(topCeiling, ...cheaper.map((c) => c.ceiling));
280	  return {
281	    ...common,
282	    action: 'skip',
283	    statusReason: 'not started: no budget',
284	    reason:
285	      smallest > remaining
286	        ? `Not started because only ${usd(remaining)} of budget is left and the smallest ceiling for this ${size} task is ${usd(smallest)}.`
287	        : `Not started because only ${usd(remaining)} of budget is left, and no tier that fits it is likely to finish this ${size} task.`,
288	  };
289	}
290	
291	export async function routeTask(input: RouteInput): Promise<RouteDecision> {
292	  return traceDecision(
293	    input.ports.trace,
294	    'tally.route',
295	    { ...input.traceAttributes, taskId: input.task.taskId, size: input.estimate.size, confidence: input.estimate.confidence },
296	    async (span) => {
297	      const decision = await routeTaskCore(input);
298	      span.set({
299	        action: decision.action,
300	        tier: decision.action === 'start' ? decision.tier.name : null,
301	        ceilingNanos: decision.action === 'start' ? decision.ceilingNanos : null,
302	        reason: decision.reason,
303	      });
304	      return decision;
305	    },
306	  );
307	}
