 10	import { copyableIdEvidence, installSessionCopy, sessionEvidence } from './session-evidence.js';
 11	import { reasonText } from './reason-text.js';
 12	import { ledgerEmptyState } from './empty-state.js';
 13	
 14	const NANOS_PER_USD = 1_000_000_000;
 15	
 16	const query = new URLSearchParams(location.search);
 17	const defaults = window.TALLY_DASHBOARD ?? {};
 18	const asFolder = (path) => (path.endsWith('/') ? path : `${path}/`);
 19	const hasExplicitData = query.has('data');
 20	const wantsDemo = query.has('demo');
 21	const wantsReplay = query.has('replay');
 22	const config = {
 23	  data: asFolder(query.get('data') ?? defaults.data ?? './'),
 24	  runsIndex: query.get('runsIndex') ?? defaults.runsIndex ?? '/runs/index.json',
 25	  baseline: query.get('baseline') ?? defaults.baseline ?? null,
 26	  intervalMs: Math.max(250, Number(query.get('interval') ?? defaults.intervalMs ?? 2000) || 2000),
 27	  aoProject: query.get('aoProject') ?? defaults.aoProject ?? null,
 28	  liveCeilingSec: Math.max(30, Number(query.get('liveCeilingSec') ?? defaults.liveCeilingSec ?? 180) || 180),
 29	  sample: defaults.sample ?? null,
 30	  // ?demo shows the checked-in sample. ?replay=60 plays the chosen run over that many seconds.
 31	  useSample: wantsDemo || (wantsReplay && !hasExplicitData),
 32	  replaySec: wantsReplay ? Math.max(5, Number(query.get('replay')) || 60) : null,
 33	};
 34	if (config.baseline) config.baseline = asFolder(config.baseline);
 35	const runsRoot = asFolder(defaults.runsRoot ?? '/runs/');
 36	let activeData = asFolder(query.get('run') ? `${runsRoot}${encodeURIComponent(query.get('run'))}/` : config.data);
 37	
 38	// ---------- formatting ----------
 39	
 40	const esc = (value) =>
 41	  String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
 42	
 43	/** Only http(s) data links are rendered; anything else in the data is shown as plain text. */
 44	const safeUrl = (url) => (typeof url === 'string' && /^https?:\/\//i.test(url) ? url : null);
 45	
 46	function usd(nanos) {
 47	  const value = (nanos ?? 0) / NANOS_PER_USD;
 48	  const digits = value !== 0 && Math.abs(value) < 0.01 ? 4 : 2;
 49	  return `$${value.toLocaleString('en-US', { minimumFractionDigits: digits, maximumFractionDigits: digits })}`;
 50	}
 51	
 52	const count = (n) => (n ?? 0).toLocaleString('en-US');
 53	
 54	function minutes(fromIso, toIso) {
 55	  const span = Math.max(0, new Date(toIso) - new Date(fromIso));
 56	  const mins = Math.round(span / 60000);
 57	  if (mins < 1) return `${Math.round(span / 1000)} s`;
 58	  return mins < 60 ? `${mins} min` : `${Math.floor(mins / 60)} h ${mins % 60} min`;
 59	}
 60	
 61	const clock = (iso) => new Date(iso).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
 62	
 63	const link = (url, text) => {
 64	  const href = safeUrl(url);
 65	  return href ? `<a href="${esc(href)}" target="_blank" rel="noopener">${esc(text)}</a>` : '';
 66	};
 67	
 68	const idEvidence = copyableIdEvidence;
 69	
 70	function aoSessionEvidence(sessionId) {
 71	  // A browser URL or query parameter cannot establish that the host handles AO links.
 72	  return sessionEvidence(sessionId, { project: config.aoProject, insideAO: window.TALLY_AO_BROWSER === true });
