127	  const rawRuns = Array.isArray(index) ? index : Array.isArray(index?.runs) ? index.runs : [];
128	  return { runs: rawRuns.map(runOptionFrom).filter(Boolean), experiments: (Array.isArray(index?.experiments) ? index.experiments : []).map(runOptionFrom).filter(Boolean) };
129	}
130	
131	// ---------- drawing ----------
132	
133	/** Replaces a section's markup only when it changed, so links and selections survive a poll. */
134	function draw(id, html) {
135	  const node = document.getElementById(id);
136	  if (node.__html === html) return;
137	  node.__html = html;
138	  node.innerHTML = html;
139	}
140	
141	const passedCount = (run) => run.tasks.filter((task) => task.status === 'passed').length;
142	const perPassedTask = (run) => (passedCount(run) > 0 ? run.budget.spentNanos / passedCount(run) : null);
143	const passRate = (run) => (run.tasks.length > 0 ? passedCount(run) / run.tasks.length : 0);
144	
145	const sampleRepos = new Set(['acme/payments-service', 'demo/invoice-ledger']);
146	const nonRealCostSources = new Set(['simulated', 'ao-estimate']);
147	
148	function explicitRunKind(run) {
149	  const raw = run.dataKind ?? run.runKind ?? run.kind ?? run.costKind ?? run.sourceKind;
150	  if (typeof raw !== 'string') return null;
151	  const kind = raw.toLowerCase();
152	  if (['real', 'real-run', 'live'].includes(kind)) return 'real';
153	  if (['simulated', 'simulation', 'dry-run', 'dryrun'].includes(kind)) return 'simulated';
154	  if (['sample', 'fixture', 'demo', 'replay'].includes(kind)) return kind;
155	  return null;
156	}
157	
158	function taskIdsKey(run) {
159	  return run.tasks.map((task) => task.taskId).sort().join('|');
160	}
161	
162	function costKind(run, ledger, source = {}) {
163	  const explicit = explicitRunKind(run);
164	  if (source.sample || explicit === 'sample' || explicit === 'fixture' || sampleRepos.has(run.repo)) return 'sample';
165	  if (source.replaying || explicit === 'replay') return 'replay';
166	  if (run.dryRun || explicit === 'simulated') return 'simulated';
167	  if (explicit === 'real') return 'real';
168	  // A run that is not a dry run and has no attempts yet is a real run that has spent nothing, not a simulation.
169	  return ledger.every((row) => row.costSource && !nonRealCostSources.has(row.costSource)) ? 'real' : 'simulated';
170	}
171	
172	function comparableKey(run, ledger, source = {}) {
173	  return `${run.repo ?? ''}::${taskIdsKey(run)}::${costKind(run, ledger, source)}`;
174	}
175	
176	function runSummary(state, source = {}) {
177	  const run = state.run ?? state;
178	  const ledger = state.ledger ?? [];
179	  return {
180	    runId: run.runId,
181	    mode: run.mode,
182	    repeat: Number.isInteger(run.repeat) ? run.repeat : null,
183	    status: run.status,
184	    repo: run.repo,
185	    taskIds: taskIdsKey(run),
186	    kind: costKind(run, ledger, source),
187	    key: comparableKey(run, ledger, source),
188	    passed: passedCount(run),
189	    total: run.tasks.length,
190	    passRate: passRate(run),
191	    totalCost: run.budget.spentNanos,
192	    perPassed: perPassedTask(run),
193	  };
194	}
195	
196	function pct(value) {
197	  return `${Math.round(value * 100)}%`;
198	}
199	
200	function median(values) {
201	  if (values.length === 0) return null;
202	  const sorted = [...values].sort((a, b) => a - b);
203	  const middle = Math.floor(sorted.length / 2);
204	  return sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
205	}
206	
207	function spread(values, format) {
208	  const clean = values.filter((value) => value !== null && Number.isFinite(value));
209	  if (clean.length === 0) return '<span class="blank">none</span>';
210	  const min = Math.min(...clean);
211	  const max = Math.max(...clean);
212	  const mid = median(clean);
213	  return min === max ? format(min) : `${format(min)}-${format(max)} <span class="spread-mid">median ${format(mid)}</span>`;
214	}
215	
216	/** Tally marks: groups of four strokes crossed by a fifth. */
217	function tallyMarks(n) {
218	  const groups = [];
219	  for (let left = n; left > 0; left -= 5) {
220	    const strokes = Math.min(left, 4);
221	    const crossed = left >= 5;
222	    const lines = Array.from({ length: strokes }, (_, i) => `<path d="M${5 + i * 7} 3v22"/>`).join('');
223	    const slash = crossed ? '<path d="M1 22 30 7"/>' : '';
224	    groups.push(`<svg viewBox="0 0 ${crossed ? 32 : strokes * 7 + 3} 28" aria-hidden="true">${lines}${slash}</svg>`);
225	  }
226	  return groups.join('');
227	}
