141	const passedCount = (run) => run.tasks.filter((task) => task.status === 'passed').length;
142	const perPassedTask = (run) => (passedCount(run) > 0 ? run.budget.spentNanos / passedCount(run) : null);
143	const passRate = (run) => (run.tasks.length > 0 ? passedCount(run) / run.tasks.length : 0);
144	
145	const sampleRepos = new Set(['acme/payments-service', 'demo/invoice-ledger']);
146	const nonRealCostSources = new Set(['simulated', 'ao-estimate']);
147	
148	function explicitRunKind(run) {
149	  const raw = run.dataKind ?? run.runKind ?? run.kind ?? run.costKind ?? run.sourceKind;
150	  if (typeof raw !== 'string') return null;
151	  const kind = raw.toLowerCase();
152	  if (['real', 'real-run', 'live'].includes(kind)) return 'real';
153	  if (['simulated', 'simulation', 'dry-run', 'dryrun'].includes(kind)) return 'simulated';
154	  if (['sample', 'fixture', 'demo', 'replay'].includes(kind)) return kind;
155	  return null;
156	}
