162	function costKind(run, ledger, source = {}) {
163	  const explicit = explicitRunKind(run);
164	  if (source.sample || explicit === 'sample' || explicit === 'fixture' || sampleRepos.has(run.repo)) return 'sample';
165	  if (source.replaying || explicit === 'replay') return 'replay';
166	  if (run.dryRun || explicit === 'simulated') return 'simulated';
167	  if (explicit === 'real') return 'real';
168	  // A run that is not a dry run and has no attempts yet is a real run that has spent nothing, not a simulation.
169	  return ledger.every((row) => row.costSource && !nonRealCostSources.has(row.costSource)) ? 'real' : 'simulated';
170	}
