179	  return {
180	    runId: run.runId,
181	    mode: run.mode,
182	    repeat: Number.isInteger(run.repeat) ? run.repeat : null,
183	    status: run.status,
184	    repo: run.repo,
185	    taskIds: taskIdsKey(run),
186	    kind: costKind(run, ledger, source),
187	    key: comparableKey(run, ledger, source),
188	    passed: passedCount(run),
189	    total: run.tasks.length,
190	    passRate: passRate(run),
191	    totalCost: run.budget.spentNanos,
