216	/** Tally marks: groups of four strokes crossed by a fifth. */
217	function tallyMarks(n) {
218	  const groups = [];
219	  for (let left = n; left > 0; left -= 5) {
220	    const strokes = Math.min(left, 4);
221	    const crossed = left >= 5;
222	    const lines = Array.from({ length: strokes }, (_, i) => `<path d="M${5 + i * 7} 3v22"/>`).join('');
223	    const slash = crossed ? '<path d="M1 22 30 7"/>' : '';
224	    groups.push(`<svg viewBox="0 0 ${crossed ? 32 : strokes * 7 + 3} 28" aria-hidden="true">${lines}${slash}</svg>`);
225	  }
226	  return groups.join('');
