  5	const ms = (iso) => new Date(iso).getTime();
  6	
  7	/** Start and end of the run in epoch milliseconds, taken from the ledger when the run has no end. */
  8	export function runWindow(run, ledger) {
  9	  const start = ms(run.startedAt);
 10	  const ends = ledger.map((row) => (row.endedAt ? ms(row.endedAt) : 0));
 11	  const end = Math.max(run.endedAt ? ms(run.endedAt) : 0, ...ends, start + Math.max(ledger.length, 1) * 1000);
 12	  return { start, end };
 13	}
 14	
 15	function rowWindow(row, index, runStart, runEnd, count) {
 16	  const began = ms(row.startedAt);
 17	  const ended = row.endedAt ? ms(row.endedAt) : runEnd;
 18	  if (ended > began) return { began, ended };
 19	
 20	  // Dry-run attempts can be written with identical start/end timestamps because
 21	  // the engine simulates work instantly. Spread those zero-duration rows across
 22	  // the replay window so the dashboard still tells the story over ~60 seconds.
 23	  const slice = Math.max(1, (runEnd - runStart) / Math.max(count, 1));
 24	  return {
 25	    began: runStart + index * slice,
 26	    ended: runStart + (index + 1) * slice,
 27	  };
 28	}
 29	
 30	function inFlight(row, share) {
 31	  const scale = (n) => Math.round(n * share);
 32	  const tokens = {
 33	    uncachedInput: scale(row.tokens.uncachedInput),
 34	    cachedInput: scale(row.tokens.cachedInput),
 35	    output: scale(row.tokens.output),
 36	  };
 37	  tokens.total = tokens.uncachedInput + tokens.cachedInput + tokens.output;
 38	  return {
 39	    ...row,
 40	    tokens,
 41	    estimatedCostNanos: scale(row.estimatedCostNanos),
 42	    result: 'running',
 43	    resultReason: null,
 44	    prUrl: null,
 45	    checkpointId: null,
 46	    checkpointUrl: null,
 47	    endedAt: null,
 48	  };
 49	}
 50	
 51	/**
 52	 * The run and ledger as they stood `fraction` of the way through (0 to 1).
 53	 * At 1 the inputs are returned untouched.
 54	 */
 55	export function frameAt(run, ledger, fraction) {
 56	  if (fraction >= 1) return { run, ledger };
 57	  const { start, end } = runWindow(run, ledger);
 58	  const now = start + Math.max(0, fraction) * (end - start);
 59	
 60	  const rows = [];
 61	  for (const [index, row] of ledger.entries()) {
 62	    const { began, ended } = rowWindow(row, index, start, end, ledger.length);
 63	    if (began > now) continue;
 64	    rows.push(ended <= now ? row : inFlight(row, (now - began) / Math.max(1, ended - began)));
 65	  }
 66	
 67	  const tasks = run.tasks.map((task) => {
 68	    const all = ledger.filter((row) => row.taskId === task.taskId);
 69	    const seen = rows.filter((row) => row.taskId === task.taskId);
 70	    const last = seen[seen.length - 1];
 71	    if (!last) {
 72	      return {
 73	        ...task,
 74	        status: 'pending',
 75	        statusReason: null,
 76	        attempts: 0,
 77	        tier: null,
 78	        model: null,
 79	        spentNanos: 0,
 80	        escalated: false,
 81	        prUrl: null,
 82	        changedFiles: undefined,
 83	      };
 84	    }
 85	    const settled = last.result !== 'running' && seen.length === all.length;
 86	    return {
 87	      ...task,
 88	      status: settled ? task.status : 'running',
 89	      statusReason: settled ? task.statusReason : null,
 90	      attempts: seen.length,
 91	      tier: last.tier,
 92	      model: last.model,
 93	      spentNanos: seen.reduce((sum, row) => sum + row.estimatedCostNanos, 0),
 94	      escalated: seen.length > 1,
 95	      prUrl: settled ? task.prUrl : null,
 96	      changedFiles: settled ? task.changedFiles : undefined,
 97	    };
 98	  });
 99	
100	  return {
101	    run: {
102	      ...run,
103	      status: 'running',
104	      updatedAt: new Date(now).toISOString(),
105	      endedAt: null,
106	      budget: { ...run.budget, spentNanos: rows.reduce((sum, row) => sum + row.estimatedCostNanos, 0) },
107	      tasks,
108	    },
109	    ledger: rows,
110	  };
111	}
