   822	  }
   823	  const experimentState = usingSample || config.replaySec ? { experiment: null, experimentChoices: [] } : await readExperiments(lastGood);
   824	  document.body.classList.remove('unread');
   825	
   826	  let state = lastGood;
   827	  let replaying = false;
   828	  if (config.replaySec) {
   829	    replayStart ??= performance.now();
   830	    const fraction = (performance.now() - replayStart) / (config.replaySec * 1000);
   831	    replaying = true;
   832	    state = frameAt(lastGood.run, lastGood.ledger, fraction);
   833	  }
   834	  drawAll(state, { sample: usingSample, stale, baseline, replaying, runs, runsIndexError, comparisonRuns, ...experimentState });
   835	}
   836	
   837	async function loop() {
   838	  await tick();
   839	  setTimeout(loop, config.replaySec ? Math.min(config.intervalMs, 1000) : config.intervalMs);
   840	}
