 32	export function prepareReinit(configPath: string, afterConfig: string): ReinitPlan {
 33	  const path = installRecordPath(configPath);
 34	  const beforeRecord = existsSync(path) ? readFileSync(path, 'utf8') : null;
 35	  let afterRecord: string | null = null;
 36	  if (beforeRecord !== null) {
 37	    const record = JSON.parse(beforeRecord) as InstallRecord;
 38	    if (!record || record.version !== 1 || record.configPath !== configPath || typeof record.projectId !== 'string') {
 39	      throw new CommandError(`Invalid installation ownership record at ${path}; no changes made.`);
 40	    }
 41	    afterRecord = JSON.stringify({ ...record, configHash: contentHash(afterConfig) }, null, 2);
 42	  }
 43	  return { version: 1, configPath, beforeConfig: readFileSync(configPath, 'utf8'), afterConfig, beforeRecord, afterRecord };
 44	}
 45	
 46	function checkFile(path: string, before: string | null, after: string | null): void {
 47	  const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
 48	  if (current !== before && current !== after) throw new CommandError(`Re-init refused: ${path} changed since the proposal; preserve your edits before retrying.`);
 49	}
