 51	function replaceFile(path: string, contents: string): void {
 52	  const temporary = `${path}.${randomUUID()}.tmp`;
 53	  try {
 54	    writeFileSync(temporary, contents, { flag: 'wx', mode: existsSync(path) ? statSync(path).mode & 0o777 : 0o600 });
 55	    renameSync(temporary, path);
 56	  } finally { if (existsSync(temporary)) unlinkSync(temporary); }
 57	}
