 20	export function readReinit(configPath: string): ReinitPlan | null {
 21	  const path = reinitPath(configPath);
 22	  if (!existsSync(path)) return null;
 23	  try {
 24	    const value = JSON.parse(readFileSync(path, 'utf8')) as ReinitPlan;
 25	    if (!value || value.version !== 1 || value.configPath !== configPath || typeof value.beforeConfig !== 'string' ||
 26	        typeof value.afterConfig !== 'string' || (value.beforeRecord !== null && typeof value.beforeRecord !== 'string') ||
 27	        (value.afterRecord !== null && typeof value.afterRecord !== 'string')) throw new Error('invalid');
 28	    return value;
 29	  } catch { throw new CommandError(`Invalid re-init recovery record at ${path}; preserve it and inspect it before retrying.`); }
 30	}
