 59	export function applyReinit(plan: ReinitPlan): void {
 60	  const recordPath = installRecordPath(plan.configPath);
 61	  const pendingPath = reinitPath(plan.configPath);
 62	  checkFile(plan.configPath, plan.beforeConfig, plan.afterConfig);
 63	  checkFile(recordPath, plan.beforeRecord, plan.afterRecord);
 64	  try {
 65	    mkdirSync(dirname(pendingPath), { recursive: true });
 66	    if (!existsSync(pendingPath)) writeFileSync(pendingPath, JSON.stringify(plan, null, 2), { flag: 'wx', mode: 0o600 });
 67	    checkFile(plan.configPath, plan.beforeConfig, plan.afterConfig);
 68	    replaceFile(plan.configPath, plan.afterConfig);
 69	    if (plan.afterRecord !== null) {
