 22	export function readPendingInit(configPath: string): InitTransaction | null {
 23	  const path = pendingInitPath(configPath);
 24	  if (!existsSync(path)) return null;
 25	  let value: InitTransaction;
 26	  try { value = JSON.parse(readFileSync(path, 'utf8')) as InitTransaction; }
 27	  catch { throw new CommandError(`Invalid init recovery record at ${path}; preserve it and inspect it before retrying.`); }
 28	  if (!value || typeof value !== 'object' || value.version !== 1 || value.configPath !== configPath || value.record?.configPath !== configPath ||
 29	      typeof value.configText !== 'string' || contentHash(value.configText) !== value.record.configHash ||
 30	      typeof value.beforeProjectConfigHash !== 'string' || typeof value.repoRoot !== 'string' ||
 31	      value.record.version !== 1 || typeof value.record.projectId !== 'string' || typeof value.record.projectCreated !== 'boolean' || typeof value.record.projectConfigHash !== 'string') {
 32	    throw new CommandError(`Invalid init recovery record at ${path}; preserve it and inspect it before retrying.`);
 33	  }
 34	  return value;
 35	}
