 37	export async function applyInitTransaction(transaction: InitTransaction, command: InitCommandRunner, recordPath: string): Promise<void> {
 38	  const { configPath, configText, record, repoRoot } = transaction;
 39	  const pendingPath = pendingInitPath(configPath);
 40	  // Never overwrite files changed by the user while recovering an interrupted init.
 41	  if (existsSync(configPath) && contentHash(readFileSync(configPath, 'utf8')) !== record.configHash) {
 42	    throw new CommandError(`Init recovery refused: ${configPath} differs from the pending configuration; preserve your edits before retrying.`);
 43	  }
 44	  if (existsSync(recordPath) && configHash(JSON.parse(readFileSync(recordPath, 'utf8'))) !== configHash(record)) {
 45	    throw new CommandError(`Init recovery refused: ${recordPath} differs from the pending ownership record.`);
 46	  }
 47	  let stage = 'creating recovery record';
 48	  const completed = transaction.completed ?? [];
 49	  const save = () => writeFileSync(pendingPath, JSON.stringify({ ...transaction, completed }, null, 2), { mode: 0o600 });
 50	  try {
 51	    mkdirSync(dirname(pendingPath), { recursive: true });
 52	    if (!existsSync(pendingPath)) writeFileSync(pendingPath, JSON.stringify(transaction, null, 2), { mode: 0o600, flag: 'wx' });
 53	    stage = 'reading AO project';
 54	    let current: Record<string, unknown> | null;
 55	    try {
 56	      const payload = JSON.parse((await command('ao', ['project', 'get', record.projectId, '--json'], { cwd: repoRoot })).stdout);
 57	      const path = payload.project?.path;
 58	      if (typeof path === 'string' && resolve(path) !== resolve(repoRoot)) throw new CommandError(`AO project ${record.projectId} belongs to another repository (${path}); choose another project id.`);
 59	      current = payload.project?.config ?? {};
 60	    } catch (error) {
 61	      if (!(error instanceof Error) || !/missing project|not found|HTTP 404/i.test(error.message)) throw error;
 62	      if (!record.projectCreated) throw new CommandError(`Existing AO project ${record.projectId} disappeared; refusing to recreate a project Tally did not own.`);
 63	      stage = 'registering AO project';
 64	      await command('ao', ['project', 'add', '--path', repoRoot, '--id', record.projectId], { cwd: repoRoot });
 65	      completed.push(`registered AO project ${record.projectId}`);
 66	      save();
 67	      current = JSON.parse((await command('ao', ['project', 'get', record.projectId, '--json'], { cwd: repoRoot })).stdout).project?.config ?? {};
 68	    }
 69	    const hash = configHash(current);
 70	    if (!record.projectCreated && hash !== transaction.beforeProjectConfigHash && hash !== record.projectConfigHash) {
 71	      throw new CommandError('AO project settings changed since init was proposed; refusing to overwrite them.');
 72	    }
 73	    const next = { ...current };
 74	    if (record.addedSetupCommand) {
 75	      const commands = Array.isArray(next.postCreate) ? next.postCreate as string[] : [];
 76	      next.postCreate = commands.includes(record.addedSetupCommand) ? commands : [...commands, record.addedSetupCommand];
 77	    }
 78	    if (record.projectCreated && !transaction.newProjectInitialized) {
