 82	      record.postCreateAfterHash = configHash(next.postCreate ?? []);
 83	      if (record.addedSetupCommand && Array.isArray(current?.postCreate) && current.postCreate.includes(record.addedSetupCommand)) record.addedSetupCommand = null;
 84	      transaction.newProjectInitialized = true;
 85	      save();
 86	    }
 87	    if (configHash(next) !== record.projectConfigHash) {
 88	      throw new CommandError('AO project configuration differs from the pending init; no settings were overwritten.');
 89	    }
 90	    stage = 'updating AO project configuration';
 91	    await command('ao', ['project', 'set-config', record.projectId, '--config-json', JSON.stringify(next), '--json'], { cwd: repoRoot });
 92	    completed.push(`configured AO project ${record.projectId}`);
