 43	class PlanBudget implements BudgetPort {
 44	  private reservedNanos = 0;
 45	  constructor(private readonly limitNanos: number) {}
 46	  async remainingNanos(): Promise<number> {
 47	    return this.limitNanos - this.reservedNanos;
 48	  }
 49	  reserve(ceilingNanos: number | null): void {
 50	    this.reservedNanos += ceilingNanos ?? 0;
 51	  }
 52	}
