 60	export async function readPlanBudget(config: TallyConfig, options: Pick<PlanOptions, 'budgetUsd'>): Promise<PlanBudgetInfo> {
 61	  if (options.budgetUsd !== undefined) return { source: 'config', limitNanos: usdToNanos(options.budgetUsd) };
 62	  if (config.budget.source === 'cfoai') {
 63	    try {
 64	      return { source: 'cfoai', limitNanos: await new CfoaiBudgetAdapter({ config: config.budget.cfoai }).budgetLimitNanos() };
 65	    } catch {
 66	      return { source: 'config', limitNanos: usdToNanos(config.budget.usd) };
 67	    }
 68	  }
 69	  return { source: 'config', limitNanos: usdToNanos(config.budget.usd) };
 70	}
 71	
 72	export async function planTally(options: PlanOptions): Promise<PlannedTask[]> {
 73	  const config = loadConfig(options.configPath);
 74	  if (!options.dryRun) await validateRealRunConfig(config, options.configPath, options.preflightRunner);
 75	  const configDir = dirname(options.configPath);
 76	  const dryRunPorts = options.dryRun ? createDryRunPorts({ config, configPath: options.configPath }) : {};
 77	  const signals =
 78	    options.signals ??
 79	    dryRunPorts.signals ??
 80	    (config.integrations.entire ? new EntireSizingAdapter({ repoPath: resolve(configDir, config.repo.path) }) : nullSignals);
 81	  const intake = dryRunPorts.intake ?? new ConfigBacklogIntake();
 82	  const tasks = (await intake.tasks(config, options.configPath)).filter((task) => {
 83	    if (options.only === undefined) return true;
 84	    return task.taskId === options.only || String(task.issueNumber) === options.only;
 85	  });
 86	  const budgetInfo = await readPlanBudget(config, options);
 87	  const budget = new PlanBudget(budgetInfo.limitNanos);
 88	  const history = new PriceHistory();
 89	  const planned: PlannedTask[] = [];
 90	  for (const task of tasks) {
 91	    const taskInput = { taskId: task.taskId, title: task.title, body: task.body };
 92	    const estimate = await sizeTask(taskInput, { signals });
 93	    const route = options.baseline
 94	      ? await routeBaseline({ task: taskInput, estimate, config, ports: { budget, history } })
 95	      : await routeTask({ task: taskInput, estimate, config, ports: { budget, history } });
 96	    if (route.action === 'start') {
 97	      const ceiling = task.firstAttemptCeilingUsd === undefined || options.baseline ? route.ceilingNanos : Math.min(route.ceilingNanos ?? Infinity, usdToNanos(task.firstAttemptCeilingUsd));
 98	      budget.reserve(ceiling);
 99	      planned.push({
100	        taskId: task.taskId,
101	        title: task.title,
102	        size: estimate.size,
103	        tier: route.tier.name,
104	        model: route.tier.model,
105	        harness: route.tier.harness,
106	        ceilingNanos: ceiling,
107	        decision: task.firstAttemptCeilingUsd === undefined || options.baseline ? route.reason : `${route.reason} Deliberate first-attempt ceiling override: $${task.firstAttemptCeilingUsd.toFixed(3)} (normal ceiling remains an upper bound).`,
108	        skipped: false,
109	      });
110	    } else {
111	      planned.push({
112	        taskId: task.taskId,
113	        title: task.title,
114	        size: estimate.size,
115	        tier: null,
116	        model: null,
117	        harness: null,
118	        ceilingNanos: null,
119	        decision: route.reason,
120	        skipped: true,
121	      });
122	    }
123	  }
124	  return planned;
125	}
