 22	export function resolveAoBinary(options: AoBinaryOptions = {}): string {
 23	  const env = options.env ?? process.env;
 24	  const cwd = options.cwd ?? process.cwd();
 25	  const candidates = (env.PATH ?? '').split(delimiter).filter(Boolean).map((dir) => resolve(cwd, dir, 'ao'));
 26	  for (const override of [env.TALLY_AO_BIN, options.aoBin]) if (override) candidates.push(resolve(cwd, override));
 27	  if ((options.platform ?? process.platform) === 'darwin') {
 28	    const suffix = 'Agent Orchestrator.app/Contents/Resources/daemon/ao';
 29	    candidates.push(...(options.bundleRoots ?? ['/Applications', join(options.home ?? homedir(), 'Applications')]).map((root) => join(root, suffix)));
 30	  }
 31	  for (const candidate of candidates) {
 32	    try {
 33	      accessSync(candidate, constants.X_OK);
 34	      if (statSync(candidate).isFile()) return candidate;
 35	    } catch { /* Try the next explicit location. */ }
 36	  }
 37	  throw new CommandError(`Agent Orchestrator (AO) is required; looked in PATH (${env.PATH || 'empty'}), TALLY_AO_BIN (${env.TALLY_AO_BIN || 'unset'}), repo.aoBin (${options.aoBin || 'unset'}) and ${candidates.filter((path) => path.includes('.app/')).join(', ') || 'no app-bundle locations on this platform'}; install AO or set TALLY_AO_BIN to its executable path.`, 'ENOENT');
 38	}
 39	
 40	export async function runCommand(file: string, args: string[], options: AoBinaryOptions & { timeout?: number; maxBuffer?: number } = {}): Promise<{ stdout: string; stderr: string }> {
 41	  const executable = file === 'ao' ? resolveAoBinary(options) : file;
 42	  try {
 43	    return await execFileAsync(executable, args, { cwd: options.cwd, env: options.env, timeout: options.timeout, maxBuffer: options.maxBuffer, encoding: 'utf8' });
 44	  } catch (error) {
 45	    const failure = error as { code?: string | number; stdout?: unknown; stderr?: unknown };
 46	    const code = failure.code;
 47	    throw new CommandError(code === 'ENOENT'
 48	      ? `${file} is required but could not be started; install it or add its executable to PATH${options.cwd ? `, and check that ${options.cwd} exists` : ''}.`
 49	      : `${file} command failed (${code ?? 'unknown error'}); check the command in your terminal before retrying.`, code,
 50	      typeof failure.stdout === 'string' ? failure.stdout : '', typeof failure.stderr === 'string' ? failure.stderr : '');
 51	  }
 52	}

