164	      const remote = aggregate(await this.remoteObservations(), size, tier);
165	      return remote ?? this.fallback.lookup(size, tier);
166	    } catch {
167	      return this.fallback.lookup(size, tier);
168	    }
169	  }
170	
171	  async record(outcome: AttemptOutcome): Promise<void> {
172	    await this.fallback.record(outcome);
173	  }
174	
175	  private headers(): HeadersInit {
176	    return { Authorization: `Bearer ${this.token}`, 'x-project-id': this.projectId! };
177	  }
178	
179	  private async remoteObservations(): Promise<Observation[]> {
180	    const tracesUrl = new URL(`${this.endpoint}/traces`);
181	    tracesUrl.searchParams.set('workflowName', this.workflowName);
182	    tracesUrl.searchParams.set('limit', String(this.limit));
183	    const tracesResponse = await this.fetchImpl(tracesUrl, { headers: this.headers() });
184	    if (!tracesResponse.ok) throw new Error(`neatlogs traces read failed: ${tracesResponse.status}`);
185	    const traces = tracesOf(await tracesResponse.json());
186	    const observations: Observation[] = [];
187	    for (const trace of traces) {
188	      const traceName = traceNameOf(trace);
189	      const traceObservation = observationFromName(traceName);
190	      if (traceObservation) observations.push(traceObservation);
191	      if (traceName && traceName !== 'tally.history.record') continue;
192	      const traceId = traceIdOf(trace);
193	      if (!traceId) continue;
194	      const spansResponse = await this.fetchImpl(`${this.endpoint}/traces/${encodeURIComponent(traceId)}/spans`, { headers: this.headers() });
195	      if (!spansResponse.ok) continue;
196	      for (const span of spansOf(await spansResponse.json())) {
197	        const observation = observationFromSpan(span);
198	        if (observation) observations.push(observation);
199	      }
200	    }
201	    return observations;
202	  }
203	}
