205	export function historyAttributes(outcome: AttemptOutcome): Record<string, string | number> {
206	  return {
207	    'tally.history.kind': 'attempt',
208	    'tally.history.size': outcome.size,
209	    'tally.history.tier': outcome.tier,
210	    'tally.history.result': outcome.result,
211	    'tally.history.cost_nanos': outcome.costNanos,
212	    'tally.history.cost_usd': outcome.costNanos / NANOS_PER_USD,
213	  };
214	}
