100	export class EntireCheckpointAdapter implements HandoffPort, CheckpointPort {
101	  private readonly command: CommandRunner;
102	  private readonly repoPath: string;
103	  private readonly summaryTimeoutSec: number;
104	  private readonly generatedSummaries: boolean;
105	
106	  constructor(options: EntireCheckpointOptions) {
107	    this.command = options.command ?? defaultCommand;
108	    this.repoPath = options.repoPath;
109	    this.summaryTimeoutSec = options.summaryTimeoutSec ?? 45;
110	    this.generatedSummaries = options.generatedSummaries === true;
111	  }
112	
113	  async checkpointFor(context: HandoffContext & { sessionId: string }): Promise<CheckpointInfo | null> {
114	    const found = await this.findCheckpoint(context);
115	    return found ? { checkpointId: found.checkpointId, checkpointUrl: found.checkpointUrl, entireSessionId: found.entireSessionId ?? null } : null;
116	  }
117	
118	  async sessionIdFor(context: HandoffContext & { sessionId: string }): Promise<string | null> {
119	    // Killed workers may have no commit, but prompt-submit has already registered a session.
120	    // Read the shared repository after AO removes the worker worktree.
121	    const result = await this.command('entire', ['session', 'list', '--json'], { cwd: this.repoPath }).catch(() => null);
122	    const sessions = parseJson<SessionInfo[]>(result?.stdout ?? '');
123	    if (!Array.isArray(sessions)) return null;
124	    const exact = sessions.filter(s => text(s.session_id) === context.sessionId || text(s.worktree_id) === context.sessionId);
125	    const candidates = exact.length ? exact : sessions.filter(s => {
126	      if (text(s.worktree_id)) return false;
127	      const path = text(s.worktree_path);
128	      if (path) return !!context.checkoutPath && resolve(path) === resolve(context.checkoutPath);
129	      return !!context.branch && text(s.branch) === context.branch;
130	    });
131	    // Same-branch continuation must not inherit an earlier worker's capture session.
132	    return candidates.length === 1 ? text(candidates[0]?.session_id) : null;
133	  }
134	
135	  async summaryFor(sessionId: string, context: HandoffContext = {}): Promise<HandoffSummary | null> {
136	    const found = await this.findCheckpoint({ ...context, sessionId });
137	    if (!found) return null;
138	    const generated = this.generatedSummaries ? await this.command(
139	      'entire',
140	      ['checkpoint', 'explain', found.checkpointId, '--generate', '--summary-timeout-seconds', String(this.summaryTimeoutSec), '--no-pager'],
141	      { cwd: context.checkoutPath ?? this.repoPath },
142	    ).catch(() => null) : null;
143	    let summary = trimSummary(generated?.stdout ?? '');
144	    if (!summary || /not generated yet|run .*checkpoint explain.*--generate/i.test(summary)) {
145	      const branch = context.branch ?? found.branch;
146	      const diff = context.changedFiles ? null : await this.command('git', ['show', '--format=', '--name-only', '-z', '--end-of-options', branch ?? 'HEAD', '--'], {
147	        cwd: context.checkoutPath ?? this.repoPath,
148	      }).catch(() => null);
149	      const changedFiles = context.changedFiles ?? (diff ? diff.stdout.split('\0').filter(Boolean) : null);
150	      summary = [
151	        'Metadata-only handoff; no generated summary or transcript export was requested.',
152	        `Checkpoint: ${found.checkpointId}; native session: ${found.entireSessionId ?? '(unknown)'}.`,
153	        `Branch: ${branch ?? '(unknown)'}.`,
154	        `Checkpoint files: ${found.filesTouched.length ? found.filesTouched.join(', ') : '(unavailable)'}.`,
155	        `Changed files: ${changedFiles === null ? '(unavailable)' : changedFiles.length ? changedFiles.join(', ') : '(none)'}.`,
156	        `Attempt verdict: ${context.result ?? '(unknown)'}${context.resultReason ? ` - ${context.resultReason}` : ''}.`,
157	        ...(context.task ? [`Task ${context.task.taskId}: ${context.task.title}`, context.task.body] : []),
158	        'Inspect the branch changes and rerun the failed tests before continuing.',
159	      ].join('\n');
160	    }
161	    if (!summary) return null;
162	    return {
163	      type: 'entire-handoff',
164	      summary,
165	      branch: context.branch ?? found.branch ?? null,
166	      checkpointId: found.checkpointId,
167	      checkpointUrl: found.checkpointUrl,
168	      summaryCostNanos: 0,
169	      summaryCostSource: 'ao-estimate',
170	    };
171	  }
172	
173	  private async findCheckpoint(context: HandoffContext & { sessionId: string }): Promise<ResolvedCheckpoint | null> {
174	    if (context.checkpointId) return this.explain(context.checkpointId, context);
175	    // AO session ids differ from Codex session ids; the task commit is authoritative.
176	    if (context.branch || context.checkoutPath) {
177	      const log = await this.command('git', ['log', '-1', '--format=%B', '--end-of-options', context.branch ?? 'HEAD', '--'], {
178	        cwd: context.checkoutPath ?? this.repoPath,
179	      }).catch(() => null);
180	      const trailer = log ? trailerFrom(log.stdout) : null;
181	      if (trailer) return this.explain(trailer, context);
182	    }
183	    const session = await this.sessionInfo(context.sessionId, context.checkoutPath);
184	    const sessionCheckpoint = text(session?.last_checkpoint_id) ?? checkpointId(session ?? {});
185	    if (sessionCheckpoint) return this.explain(sessionCheckpoint, { ...context, branch: text(session?.branch) ?? context.branch ?? null });
186	
187	    const pending = await this.checkpointList(['checkpoint', 'list', '--pending', '--json'], context.checkoutPath);
188	    const pendingMatch = latestForSession(pending, context.sessionId);
189	    if (pendingMatch) return this.explain(checkpointId(pendingMatch)!, { ...context, branch: text(pendingMatch.branch) ?? context.branch ?? null });
190	
191	    const condensed = await this.checkpointList(['checkpoint', 'list', '--json', '--session', context.sessionId], context.checkoutPath);
192	    const condensedMatch = latestForSession(condensed, context.sessionId);
193	    if (condensedMatch) return this.explain(checkpointId(condensedMatch)!, { ...context, branch: text(condensedMatch.branch) ?? context.branch ?? null });
194	
195	    return null;
196	  }
197	
198	  private async sessionInfo(sessionId: string, cwd?: string | null): Promise<SessionInfo | null> {
199	    const result = await this.command('entire', ['session', 'info', sessionId, '--json'], { cwd: cwd ?? this.repoPath }).catch(() => null);
200	    return result ? parseJson<SessionInfo>(result.stdout) : null;
201	  }
202	
203	  private async checkpointList(args: string[], cwd?: string | null): Promise<PendingCheckpoint[]> {
204	    const result = await this.command('entire', args, { cwd: cwd ?? this.repoPath }).catch(() => null);
205	    return parseJson<PendingCheckpoint[]>(result?.stdout ?? '') ?? [];
206	  }
207	
208	  private async explain(id: string, context: HandoffContext): Promise<ResolvedCheckpoint | null> {
209	    const result = await this.command('entire', ['checkpoint', 'explain', id, '--json', '--no-pager'], { cwd: context.checkoutPath ?? this.repoPath }).catch(
210	      () => null,
211	    );
212	    const parsed = result ? parseJson<ExplainEnvelope>(result.stdout) : null;
213	    const checkpoint = checkpointId(parsed ?? {}) ?? id;
214	    return {
215	      checkpointId: checkpoint,
216	      checkpointUrl: parsed ? checkpointUrl(parsed) : null,
217	      branch: text(parsed?.branch) ?? context.branch ?? null,
218	      entireSessionId: text(parsed?.sessions?.[parsed.sessions.length - 1]?.session_id),
219	      filesTouched: Array.isArray(parsed?.files_touched) ? parsed.files_touched.filter((file): file is string => typeof file === 'string') : [],
220	    };
221	  }
222	}
