 18	type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
 19	
 20	function defaultCommand(file: string, args: string[], options?: { cwd?: string }): Promise<CommandResult> {
 21	  return execFileAsync(file, args, { cwd: options?.cwd, maxBuffer: 10 * 1024 * 1024 });
 22	}
 23	
 24	function parseJson(stdout: string): Json {
 25	  try {
 26	    return JSON.parse(stdout) as Json;
 27	  } catch {
 28	    return null;
 29	  }
 30	}
 31	
 32	function objects(value: Json): Array<Record<string, Json>> {
 33	  if (Array.isArray(value)) return value.filter((item): item is Record<string, Json> => typeof item === 'object' && item !== null && !Array.isArray(item));
 34	  if (typeof value !== 'object' || value === null || Array.isArray(value)) return [];
 35	  for (const key of ['results', 'matches', 'checkpoints']) {
 36	    const list = value[key];
 37	    if (Array.isArray(list)) return objects(list);
 38	  }
 39	  return [value];
 40	}
 41	
 42	function stringField(value: Record<string, Json>, names: string[]): string | null {
 43	  for (const name of names) {
 44	    const found = value[name];
 45	    if (typeof found === 'string' && found.trim() !== '') return found.trim();
 46	  }
 47	  return null;
 48	}
 49	
 50	function collectFiles(value: Json, out = new Set<string>()): string[] {
 51	  if (Array.isArray(value)) {
 52	    for (const item of value) collectFiles(item, out);
 53	    return [...out];
 54	  }
 55	  if (typeof value !== 'object' || value === null) return [...out];
 56	  for (const [key, nested] of Object.entries(value)) {
 57	    if (/^(file|file_path|path)$/.test(key) && typeof nested === 'string' && nested.trim() !== '') out.add(nested.trim());
 58	    else if (/files/i.test(key) && Array.isArray(nested)) {
 59	      for (const item of nested) if (typeof item === 'string' && item.trim() !== '') out.add(item.trim());
 60	      collectFiles(nested, out);
 61	    } else if (/files/i.test(key)) collectFiles(nested, out);
 62	  }
 63	  return [...out];
 64	}
 65	
 66	function issueFiles(task: TaskInput): string[] {
 67	  const text = `${task.title}\n${task.body}`;
 68	  const explicit = [...text.matchAll(/`([^`]+\.[A-Za-z0-9]+)`/g)].map((match) => match[1]!);
 69	  const bare = text.match(/\b[\w./-]+\.[A-Za-z0-9]{1,8}\b/g) ?? [];
 70	  return [...new Set([...explicit, ...bare].map((file) => file.replace(/^[./]+/, '')).filter((file) => file.includes('.')))].slice(0, 6);
 71	}
 72	
 73	function sameFile(files: string[], wanted: string[]): boolean {
 74	  if (wanted.length === 0) return false;
 75	  return files.some((file) => wanted.some((target) => file === target || file.endsWith(`/${target}`) || target.endsWith(`/${file}`)));
 76	}
 77	
 78	function failed(text: string): boolean {
 79	  return /\b(failed|failing|failure|red|stopped|errored|error|regression|did not pass)\b/i.test(text);
 80	}
