 82	export class EntireCheckpointRecallAdapter implements CheckpointRecallPort {
 83	  private readonly command: CommandRunner;
 84	  private readonly repoPath: string;
 85	  private readonly limit: number;
 86	
 87	  constructor(options: EntireRecallOptions) {
 88	    this.command = options.command ?? defaultCommand;
 89	    this.repoPath = options.repoPath;
 90	    this.limit = options.limit ?? 5;
 91	  }
 92	
 93	  async recallFor(task: TaskInput): Promise<CheckpointRecall | null> {
 94	    const files = issueFiles(task);
 95	    if (files.length === 0) return null;
 96	    const query = files.join(' ');
 97	    const result = await this.command('entire', ['checkpoint', 'search', query, '--json', '--compact', '--limit', String(this.limit)], {
 98	      cwd: this.repoPath,
 99	    }).catch(() => null);
100	    const matches = objects(parseJson(result?.stdout ?? ''));
101	    for (const match of matches) {
102	      const touched = collectFiles(match);
103	      if (!sameFile(touched, files)) continue;
104	      const summary = stringField(match, ['match', 'snippet', 'title', 'summary']) ?? `checkpoint matched ${files[0]}`;
105	      const haystack = `${summary}\n${JSON.stringify(match)}`;
106	      if (!failed(haystack)) continue;
107	      return {
108	        checkpointId: stringField(match, ['checkpoint_id', 'checkpointId', 'id']) ?? 'unknown',
109	        checkpointUrl: stringField(match, ['url', 'web_url', 'html_url']),
110	        summary,
111	        files: touched.length > 0 ? touched : files,
112	        failed: true,
113	      };
114	    }
115	    return null;
116	  }
117	}
