 93	function spansOf(body: unknown): unknown[] {
 94	  if (Array.isArray(body)) return body;
 95	  if (typeof body !== 'object' || body === null) return [];
 96	  const record = body as Record<string, unknown>;
 97	  if (Array.isArray(record.spans)) return record.spans;
 98	  if (Array.isArray(record.data)) return record.data;
 99	  if (typeof record.data === 'object' && record.data !== null && Array.isArray((record.data as Record<string, unknown>).spans)) {
100	    return (record.data as Record<string, unknown>).spans as unknown[];
101	  }
102	  return [];
103	}
104	
105	function tracesOf(body: unknown): unknown[] {
106	  if (Array.isArray(body)) return body;
107	  if (typeof body !== 'object' || body === null) return [];
108	  const record = body as Record<string, unknown>;
109	  if (Array.isArray(record.traces)) return record.traces;
110	  if (Array.isArray(record.data)) return record.data;
111	  if (typeof record.data === 'object' && record.data !== null && Array.isArray((record.data as Record<string, unknown>).traces)) {
112	    return (record.data as Record<string, unknown>).traces as unknown[];
113	  }
114	  return [];
115	}
116	
117	function observationFromSpan(span: unknown): Observation | null {
118	  if (typeof span !== 'object' || span === null) return null;
119	  const name = stringValue((span as Record<string, unknown>).name);
120	  const attrs = attributesOf(span);
121	  if (name !== 'tally.history.record' && stringValue(attrs['tally.history.kind']) !== 'attempt') return null;
122	  const size = stringValue(attrs['tally.history.size']) ?? stringValue(attrs.size);
123	  const tier = stringValue(attrs['tally.history.tier']) ?? stringValue(attrs.tier);
124	  const result = stringValue(attrs['tally.history.result']) ?? stringValue(attrs.result);
125	  const costNanos = numberValue(attrs['tally.history.cost_nanos']) ?? numberValue(attrs.costNanos);
126	  if (size !== 'small' && size !== 'medium' && size !== 'large') return null;
127	  if (!tier || !result || costNanos === null || costNanos < 0) return null;
128	  return { size, tier, result, costNanos: Math.round(costNanos) };
129	}
130	
131	function aggregate(observations: Observation[], size: TaskSize, tier: string): PriceStats | null {
132	  const matches = observations.filter((row) => row.size === size && row.tier === tier && row.result !== 'error');
133	  if (matches.length === 0) return null;
134	  return {
135	    attempts: matches.length,
136	    passRate: matches.filter((row) => row.result === 'passed').length / matches.length,
137	    avgCostNanos: Math.round(matches.reduce((sum, row) => sum + row.costNanos, 0) / matches.length),
138	  };
139	}
140	
141	export class NeatlogsPriceHistory implements PriceHistoryPort, PriceHistoryWriterPort {
142	  private readonly fallback: PriceHistoryPort & PriceHistoryWriterPort;
143	  private readonly token: string | null;
144	  private readonly projectId: string | null;
145	  private readonly fetchImpl: typeof fetch;
146	  private readonly endpoint: string;
147	  private readonly workflowName: string;
148	  private readonly limit: number;
149	
150	  constructor(options: NeatlogsHistoryOptions) {
151	    const env = options.env ?? loadEnv();
152	    this.fallback = options.fallback;
153	    this.token = env.NEATLOGS_TOKEN || null;
154	    this.projectId = env.NEATLOGS_PROJECT_ID || null;
155	    this.fetchImpl = options.fetch ?? fetch;
156	    this.endpoint = options.endpoint ?? DEFAULT_ENDPOINT;
157	    this.workflowName = options.workflowName ?? DEFAULT_WORKFLOW;
158	    this.limit = options.limit ?? 100;
159	  }
160	
161	  async lookup(size: TaskSize, tier: string): Promise<PriceStats | null> {
162	    if (!this.token || !this.projectId) return this.fallback.lookup(size, tier);
163	    try {
164	      const remote = aggregate(await this.remoteObservations(), size, tier);
165	      return remote ?? this.fallback.lookup(size, tier);
166	    } catch {
167	      return this.fallback.lookup(size, tier);
168	    }
169	  }
170	
171	  async record(outcome: AttemptOutcome): Promise<void> {
172	    await this.fallback.record(outcome);
173	  }
174	
175	  private headers(): HeadersInit {
176	    return { Authorization: `Bearer ${this.token}`, 'x-project-id': this.projectId! };
177	  }
178	
179	  private async remoteObservations(): Promise<Observation[]> {
180	    const tracesUrl = new URL(`${this.endpoint}/traces`);
181	    tracesUrl.searchParams.set('workflowName', this.workflowName);
182	    tracesUrl.searchParams.set('limit', String(this.limit));
183	    const tracesResponse = await this.fetchImpl(tracesUrl, { headers: this.headers() });
184	    if (!tracesResponse.ok) throw new Error(`neatlogs traces read failed: ${tracesResponse.status}`);
185	    const traces = tracesOf(await tracesResponse.json());
186	    const observations: Observation[] = [];
187	    for (const trace of traces) {
188	      const traceName = traceNameOf(trace);
189	      const traceObservation = observationFromName(traceName);
190	      if (traceObservation) observations.push(traceObservation);
191	      if (traceName && traceName !== 'tally.history.record') continue;
192	      const traceId = traceIdOf(trace);
193	      if (!traceId) continue;
194	      const spansResponse = await this.fetchImpl(`${this.endpoint}/traces/${encodeURIComponent(traceId)}/spans`, { headers: this.headers() });
195	      if (!spansResponse.ok) continue;
196	      for (const span of spansOf(await spansResponse.json())) {
197	        const observation = observationFromSpan(span);
198	        if (observation) observations.push(observation);
199	      }
200	    }
201	    return observations;
202	  }
203	}
