 76	  record(outcome: AttemptOutcome): Promise<void>;
 77	}
 78	
 79	export interface BudgetPort {
 80	  /**
 81	   * Budget that is free to commit right now: the limit, minus what has been
 82	   * spent, minus the ceilings of attempts that are still running.
 83	   */
 84	  remainingNanos(): Promise<number>;
 85	}
 86	
 87	export interface LiveUsage {
 88	  tokens: TokenUsage;
 89	  /** The Agent Orchestrator's own estimate; used only when no list price applies. */
 90	  estimatedCostNanos: number;
 91	}
 92	
 93	export interface LiveUsagePort {
 94	  /** Null when the session has reported no usage yet. */
 95	  usageFor(sessionId: string): Promise<LiveUsage | null>;
 96	}
