100	}
101	
102	export interface HandoffSummary {
103	  /** Which mechanism produced the summary. Recorded on the escalated ledger row. */
104	  type: Exclude<Handoff, 'none' | 'restart'>;
105	  summary: string;
106	  /** Entire checkpoint evidence for the failed attempt, when available. */
107	  checkpointId?: string | null;
108	  checkpointUrl?: string | null;
109	  /** Branch the stronger model should continue from. */
110	  branch?: string | null;
111	  /** Cost of generating this summary, if the provider reports it. */
