128	  /** Null when no summary exists; the escalation then restarts from the issue. */
129	  summaryFor(sessionId: string, context?: HandoffContext): Promise<HandoffSummary | null>;
130	}
131	
132	export interface CheckpointInfo {
133	  checkpointId: string;
134	  checkpointUrl: string | null;
135	  entireSessionId?: string | null;
136	}
137	
138	export interface CheckpointPort {
139	  checkpointFor(context: HandoffContext & { sessionId: string }): Promise<CheckpointInfo | null>;
140	  /** Native capture session may exist before any checkpoint or task commit. */
141	  sessionIdFor?(context: HandoffContext & { sessionId: string }): Promise<string | null>;
142	}
