  1	/**
  2	 * Escalation: what happens after an attempt fails or is stopped at its
  3	 * ceiling. The task moves one tier up, once, if the budget allows, and the
  4	 * stronger tier is given the earlier attempt's handoff summary when there is
  5	 * one.
  6	 */
  7	import { ceilingNanos } from '../schema/money.js';
  8	import type { AttemptResult, CostSource, Handoff, TallyConfig, TaskSize, Tier, TokenUsage } from '../schema/types.js';
  9	import type { BudgetPort, HandoffPort, TaskInput, TraceAttributes, TracePort } from './ports.js';
 10	import { usd } from './router.js';
 11	import { traceDecision } from './trace.js';
 12	
 13	/** The attempt that just ended, as written on its ledger row. */
 14	export interface FinishedAttempt {
 15	  attemptId: string;
 16	  taskId: string;
 17	  /** 1 for the first attempt, 2 for the escalation. */
 18	  attempt: number;
 19	  size: TaskSize;
 20	  /** Tier name from tally.yaml. */
 21	  tier: string;
 22	  result: AttemptResult;
 23	  /** Null for simulated attempts. */
 24	  sessionId: string | null;
 25	  branch?: string | null;
 26	  checkpointId?: string | null;
 27	  resultReason?: string | null;
 28	}
 29	
 30	export interface EscalateDecision {
 31	  action: 'escalate';
 32	  taskId: string;
 33	  size: TaskSize;
 34	  attempt: 2;
 35	  tier: Tier;
 36	  ceilingNanos: number;
 37	  /** attemptId of the attempt being taken over. */
 38	  escalatedFrom: string;
 39	  /** Goes on the escalated ledger row. */
 40	  handoff: Exclude<Handoff, 'none'>;
 41	  /** Text to give the stronger tier; null when it restarts from the issue. */
 42	  handoffSummary: string | null;
 43	  handoffBranch?: string | null;
 44	  handoffSummaryCostNanos: number;
 45	  handoffSummaryCostSource: CostSource;
 46	  handoffSummaryTokens: TokenUsage;
 47	  checkpointId: string | null;
 48	  checkpointUrl: string | null;
 49	  /** One plain-English sentence for the dashboard and the ledger row. */
 50	  reason: string;
 51	}
 52	
 53	export interface GiveUpDecision {
 54	  action: 'give-up';
 55	  taskId: string;
 56	  /** Goes into TaskState.statusReason. Null when the attempt passed and nothing is wrong. */
 57	  statusReason: string | null;
 58	  reason: string;
 59	}
 60	
 61	export type EscalationDecision = EscalateDecision | GiveUpDecision;
 62	
 63	export interface EscalationInput {
 64	  previous: FinishedAttempt;
 65	  task?: TaskInput;
 66	  config: TallyConfig;
 67	  ports: { budget: BudgetPort; handoff?: HandoffPort; trace?: TracePort };
 68	  traceAttributes?: TraceAttributes;
 69	}
 70	
 71	const HANDOFF_NAMES: Record<Exclude<Handoff, 'none' | 'restart'>, string> = {
 72	  'entire-handoff': 'the Entire handoff summary',
 73	};
 74	
 75	function capitalise(text: string): string {
 76	  return text.charAt(0).toUpperCase() + text.slice(1);
 77	}
 78	
 79	async function decideEscalationCore(input: EscalationInput): Promise<EscalationDecision> {
 80	  const { previous, config } = input;
 81	  const index = config.tiers.findIndex((tier) => tier.name === previous.tier);
 82	  if (index < 0) throw new Error(`Tier "${previous.tier}" is not in tally.yaml`);
 83	  const from = capitalise(previous.tier);
 84	  const giveUp = (statusReason: string | null, reason: string): GiveUpDecision => ({
 85	    action: 'give-up',
 86	    taskId: previous.taskId,
 87	    statusReason,
 88	    reason,
 89	  });
 90	
 91	  if (previous.result === 'passed') {
 92	    return giveUp(null, `${from} attempt passed, so there is nothing to escalate.`);
 93	  }
 94	  if (previous.result === 'error') {
 95	    return giveUp(
 96	      'failed: attempt errored',
 97	      `${from} attempt broke for a reason outside the model, so a stronger tier would not help and it is not escalated.`,
 98	    );
 99	  }
100	  const outcome = previous.result === 'stopped' ? 'was stopped at its ceiling' : 'failed its tests';
101	  if (previous.attempt >= 2) {
102	    return giveUp(
103	      'failed: already escalated once',
104	      `${from} attempt ${outcome} and the task has already been escalated once, so it is marked failed.`,
105	    );
106	  }
107	  const next = config.tiers[index + 1];
108	  if (!next) {
109	    return giveUp(
110	      'failed: no stronger tier',
111	      `${from} attempt ${outcome} and there is no stronger tier to hand it to, so it is marked failed.`,
112	    );
113	  }
114	  const ceiling = ceilingNanos(config, previous.size, next);
115	  const remaining = Math.max(0, await input.ports.budget.remainingNanos());
116	  if (ceiling > remaining) {
117	    return giveUp(
118	      `failed: no budget to escalate (next ceiling ${usd(ceiling)}, budget left ${usd(remaining)})`,
119	      `${from} attempt ${outcome}, but the ${usd(ceiling)} ceiling on ${next.name} does not fit the ${usd(remaining)} of budget left, so it is not escalated.`,
120	    );
121	  }
122	
123	  let handoff: EscalateDecision['handoff'] = 'restart';
124	  let handoffSummary: string | null = null;
125	  let handoffBranch: string | null = null;
126	  let handoffSummaryCostNanos = 0;
127	  let handoffSummaryCostSource: CostSource = 'ao-estimate';
128	  let handoffSummaryTokens: TokenUsage = { uncachedInput: 0, cachedInput: 0, output: 0, total: 0 };
129	  let checkpointId: string | null = previous.checkpointId ?? null;
130	  let checkpointUrl: string | null = null;
131	  if (previous.sessionId && input.ports.handoff) {
132	    try {
133	      const found = await input.ports.handoff.summaryFor(previous.sessionId, {
134	        branch: previous.branch,
135	        checkpointId: previous.checkpointId,
136	        result: previous.result,
137	        resultReason: previous.resultReason,
138	        task: input.task,
139	      });
140	      if (found && found.summary.trim() !== '') {
141	        handoff = found.type;
142	        handoffSummary = found.branch ? `Continue from failed branch ${found.branch}.\n\n${found.summary}` : found.summary;
143	        handoffBranch = found.branch ?? null;
144	        handoffSummaryCostNanos = Math.max(0, Math.round(found.summaryCostNanos ?? 0));
145	        handoffSummaryCostSource = found.summaryCostSource ?? 'ao-estimate';
146	        handoffSummaryTokens = found.summaryTokens ?? handoffSummaryTokens;
147	        checkpointId = found.checkpointId ?? checkpointId;
148	        checkpointUrl = found.checkpointUrl ?? null;
149	      }
150	    } catch {
151	      // No summary: the stronger tier starts from the issue.
152	    }
153	  }
154	  const how =
155	    handoff === 'restart'
156	      ? 'restarting from the issue because no handoff summary was available,'
157	      : `continuing from ${HANDOFF_NAMES[handoff]}`;
158	  return {
159	    action: 'escalate',
160	    taskId: previous.taskId,
161	    size: previous.size,
162	    attempt: 2,
163	    tier: next,
164	    ceilingNanos: ceiling,
165	    escalatedFrom: previous.attemptId,
166	    handoff,
167	    handoffSummary,
168	    handoffBranch,
169	    handoffSummaryCostNanos,
170	    handoffSummaryCostSource,
171	    handoffSummaryTokens,
172	    checkpointId,
173	    checkpointUrl,
174	    reason: `${from} attempt ${outcome}, so it escalates one tier to ${next.name} capped at ${usd(ceiling)}, ${how} with ${usd(remaining)} of budget left.`,
175	  };
176	}
177	
178	export async function decideEscalation(input: EscalationInput): Promise<EscalationDecision> {
179	  return traceDecision(
180	    input.ports.trace,
181	    'tally.escalate',
182	    {
183	      taskId: input.previous.taskId,
184	      size: input.previous.size,
185	      attempt: input.previous.attempt,
186	      fromTier: input.previous.tier,
187	      result: input.previous.result,
188	      ...input.traceAttributes,
189	    },
190	    async (span) => {
191	      const decision = await decideEscalationCore(input);
192	      span.set({
193	        action: decision.action,
194	        tier: decision.action === 'escalate' ? decision.tier.name : null,
195	        handoff: decision.action === 'escalate' ? decision.handoff : null,
196	        checkpointId: decision.action === 'escalate' ? decision.checkpointId : null,
197	        reason: decision.reason,
198	      });
199	      return decision;
200	    },
201	  );
202	}
  1	/**
