 64	}
 65	
 66	/** One finished attempt, as the history needs it. */
 67	export interface AttemptOutcome {
 68	  size: TaskSize;
 69	  /** Tier name from tally.yaml. */
 70	  tier: string;
 71	  result: AttemptResult;
 72	  costNanos: number;
 73	}
 74	
 75	export interface PriceHistoryWriterPort {
 76	  record(outcome: AttemptOutcome): Promise<void>;
 77	}
 78	
 79	export interface BudgetPort {
