export async function runRealTally(options: RealRunOptions): Promise<RunResult> {
  const config = loadConfig(options.configPath);
  const ports = resolvePorts(config, options.configPath, options.ports);
  const now = options.now ?? (() => new Date());
  const started = now();
  const runId = options.runId ?? runIdFrom(started);
  const mode: RunMode = options.baseline ? 'baseline' : 'tally';
  const outputDir = options.outputDir ? resolve(options.outputDir) : defaultOutputDir(runId);
  const ledgerPath = resolve(outputDir, 'ledger.json');
  const ledger = loadLedger(ledgerPath);
  const savedLedgerLength = ledger.length;
  let budgetLimitNanos = usdToNanos(options.budgetUsd ?? config.budget.usd);
  let budgetSource: BudgetSource = 'config';
  let cfoaiWriteFailure: string | null = null;
  let committedBeforeRunNanos = 0;
  const cfoaiEnabled = config.integrations.cfoai || config.budget.source === 'cfoai';
  if (cfoaiEnabled && ports.cfoai) {
    try {
      const [limit, currentSpend] = await Promise.all([ports.cfoai.budgetLimitNanos(), ports.cfoai.currentSpendNanos?.() ?? Promise.resolve(0)]);
      ports.cfoai.setRunBaseSpendNanos?.(Math.max(0, currentSpend - ledgerSpend(ledger)));
      if (options.budgetUsd === undefined && config.budget.source === 'cfoai') {
        budgetLimitNanos = limit;
        committedBeforeRunNanos = Math.max(0, currentSpend - ledgerSpend(ledger));
        budgetSource = 'cfoai';
      }
    } catch {
      budgetSource = 'config';
    }
  }
  const budget = new LedgerBudget(budgetLimitNanos, ledger, committedBeforeRunNanos);
  const recordSpend = async (row: LedgerRow) => {
    if (options.dryRun) return;
    const cumulative = ledgerSpend(ledger);
    appendCfoaiFallback(outputDir, row, cumulative);
    if (!cfoaiEnabled || !ports.cfoai) return;
    try {
      await ports.cfoai.writeCumulativeActualSpend(cumulative);
      await ports.cfoai.writeSpendDetail?.({
        // The adapter snapshots remote tier totals before the first write. On a
        // resumed run, saved rows are already represented there; only send the
        // attempts appended during this invocation to avoid double counting.
        attempts: ledger.slice(savedLedgerLength).map((attempt) => ({ tier: attempt.tier, costNanos: attempt.estimatedCostNanos })),
        cumulativeRunSpendNanos: cumulative,
      });
      cfoaiWriteFailure = null;
    } catch (error) {
      cfoaiWriteFailure = `write failed: ${error instanceof Error ? error.message : String(error)}; actual spend retained in cfoai-spend-fallback.csv`;
      // CSV fallback has already preserved the attempted spend for a later sync.
    }
  };
  const tasks = (await ports.intake.tasks(config, options.configPath)).filter((task) => {
    if (options.only === undefined) return true;
    return task.taskId === options.only || String(task.issueNumber) === options.only;
  });
  const savedRun = existsSync(resolve(outputDir, 'run.json')) ? JSON.parse(readFileSync(resolve(outputDir, 'run.json'), 'utf8')) as RunState : null;
  const resolvedBase = options.requiredBaseCommit !== undefined || (!savedRun?.baseCommit && !options.dryRun)
    ? await ports.worktrees.commitFor?.(resolve(dirname(options.configPath), config.repo.path), config.repo.baseBranch).catch(() => null) ?? null
    : null;
  if (options.requiredBaseCommit !== undefined) {
    if (resolvedBase !== options.requiredBaseCommit) {
      throw new Error(`Required base commit ${options.requiredBaseCommit} does not match resolved ${config.repo.baseBranch} base ${resolvedBase ?? '(unavailable)'}; no workers were started.`);
    }
    if (savedRun?.baseCommit && savedRun.baseCommit !== options.requiredBaseCommit) {
      throw new Error(`Saved run base ${savedRun.baseCommit} does not match required base commit ${options.requiredBaseCommit}; no workers were started.`);
    }
  }
  const baseCommit = options.requiredBaseCommit ?? savedRun?.baseCommit ?? resolvedBase;
  const taskStates = tasks.map((task) => {
    const saved = savedRun?.tasks.find((state) => state.taskId === task.taskId);
    return { ...initialTaskState(task), ...(saved?.impact ? { impact: saved.impact } : {}), ...(saved?.changedFiles ? { changedFiles: saved.changedFiles } : {}) };
  });
  const liveCosts = new Map<string, number>();
  const progressFor = (index: number, attempt: number, tier: Tier) => (cost: number) => {
    const state = taskStates[index]!;
    liveCosts.set(state.taskId, Math.max(liveCosts.get(state.taskId) ?? 0, cost));
    state.status = 'running';
    state.statusReason = null;
    state.attempts = attempt;
    state.tier = tier.name;
    state.model = tier.model;
    state.escalated = attempt > 1;
    state.spentNanos = ledger.filter((row) => row.taskId === state.taskId).reduce((sum, row) => sum + row.estimatedCostNanos, 0) + liveCosts.get(state.taskId)!;
    writeCurrent('running', null);
  };
  const changedFor = (index: number) => (files: string[]) => {
    const state = taskStates[index]!;
    state.changedFiles = [...new Set([...(state.changedFiles ?? []), ...files])].sort();
    writeCurrent('running', null);
  };
  const writeCurrent = (status: RunState['status'], endedAt: string | null): RunState => {
    const updatedAt = now().toISOString();
    const runState: RunState = {
      schemaVersion: SCHEMA_VERSION,
      runId,
      mode,
      ...(options.repeat === undefined ? {} : { repeat: options.repeat }),
      dryRun: options.dryRun,
      status,
      repo: repoName(config),
      backlog: { ...config.backlog },
      baseCommit,
      startedAt: started.toISOString(),
      updatedAt,
      endedAt,
      budget: {
        source: budgetSource,
        limitSource: options.budgetUsd === undefined ? budgetSource : 'cli',
        systemOfRecord: cfoaiEnabled && ports.cfoai ? 'cfoai' : 'ledger',
        ...((config.budget.source === 'cfoai' || config.integrations.cfoai) && config.budget.cfoai
          ? { cfoai: {
            ...(config.budget.cfoai.pageUrl ? { pageUrl: config.budget.cfoai.pageUrl } : {}),
            ...(config.budget.cfoai.tableUrl ? { tableUrl: config.budget.cfoai.tableUrl } : {}),
          } }
          : {}),
        limitNanos: budgetLimitNanos,
        spentNanos: ledgerSpend(ledger) + [...liveCosts.values()].reduce((sum, cost) => sum + cost, 0),
      },
      tasks: taskStates,
      integrations: integrationStates(config, ports, { dryRun: options.dryRun, budgetSource }),
    };
    if (cfoaiWriteFailure) runState.integrations.cfoai = { status: 'error', detail: cfoaiWriteFailure };
    assertValid(runState, ledger);
    writeRunFiles(outputDir, runState, ledger, options.latestRunDir);
    return runState;
  };
  writeCurrent('running', null);
  const finishAttempt = (row: LedgerRow) => {
    ledger.push(row);
    liveCosts.delete(row.taskId);
    const index = taskStates.findIndex((state) => state.taskId === row.taskId);
    if (index >= 0) taskStates[index] = stateFromRows(taskStates[index]!, ledger.filter((item) => item.taskId === row.taskId));
    writeCurrent('running', null);
  };
  const onStartupError = async (row: LedgerRow) => {
    finishAttempt(row);
    await recordSpend(row);
    writeCurrent('running', null);
    if (row.ceilingNanos !== null && row.ceilingNanos > await budget.remainingNanos()) throw new Error('worker never started; no budget for startup retry');
  };

  for (const [index, task] of tasks.entries()) {
    const stopReason = options.stopRequested?.();
    if (stopReason) {
      for (const state of taskStates.slice(index)) {
        state.status = 'skipped';
        state.statusReason = stopReason;
      }
      break;
    }
    const existingRows = ledger.filter((row) => row.taskId === task.taskId);
    if (isTaskDone(existingRows)) {
      taskStates[index] = stateFromRows(taskStates[index]!, existingRows);
      writeCurrent('running', null);
      continue;
    }
    const interrupted = existingRows[existingRows.length - 1];
    if (interrupted && interrupted.result !== 'passed' && interrupted.attempt === 1) {
      task.size = interrupted.size;
      let latest = interrupted;
      if (interrupted.result !== 'error') {
        const escalation = await decideEscalation({
          previous: {
            attemptId: interrupted.attemptId,
            taskId: interrupted.taskId,
            attempt: interrupted.attempt,
            size: interrupted.size,
            tier: interrupted.tier,
            result: interrupted.result,
            sessionId: interrupted.sessionId,
            branch: interrupted.branch,
            checkpointId: interrupted.checkpointId,
            resultReason: interrupted.resultReason,
          },
          task,
          config,
          ports: { budget, handoff: ports.handoff, trace: ports.trace },
          traceAttributes: { sessionId: runId, taskId: interrupted.taskId, attempt: interrupted.attempt + 1 },
        });
        const escalationTraceId = lastTraceId(ports.trace);
        if (escalation.action === 'escalate') {
          const summaryRow = handoffSummaryLedgerRow({ runId, task, previous: interrupted, decision: escalation, traceId: escalationTraceId, now });
          if (summaryRow) {
            ledger.push(summaryRow);
            await recordSpend(summaryRow);
          }
          latest = await runAttempt({
            runId,
            task,
            attempt: 2,
            tier: escalation.tier,
            ceilingNanos: escalation.ceilingNanos,
            decision: escalation.reason,
            escalatedFrom: escalation.escalatedFrom,
            handoff: escalation.handoff,
            handoffSummary: escalation.handoffSummary,
            traceId: escalationTraceId,
            config,
            configPath: options.configPath,
            ports,
            now,
            dryRun: options.dryRun,
            baseCommit,
            requiredBaseCommit: options.requiredBaseCommit,
            continueBranch: escalation.handoffBranch ?? interrupted.branch,
            continueSessionId: interrupted.sessionId,
            onChangedFiles: changedFor(index),
            onStartupError,
            onProgress: progressFor(index, 2, escalation.tier),
          });
          finishAttempt(latest);
          await recordHistory({ ports, row: latest, dryRun: options.dryRun });
          await recordSpend(latest);
        } else {
          interrupted.resultReason = escalation.statusReason;
        }
      }
      taskStates[index] = stateFromRows(taskStates[index]!, ledger.filter((row) => row.taskId === task.taskId));
      writeCurrent('running', null);
      continue;
    }
    const taskInput = { taskId: task.taskId, title: task.title, body: task.body };
    const sized = await sizeTask(taskInput, { signals: ports.signals, trace: ports.trace });
    let estimate = sized;
    if (ports.recall) {
      try {
        estimate = applyCheckpointRecall(sized, await ports.recall.recallFor(taskInput));
      } catch {
        estimate = sized;
      }
    }
    task.size = estimate.size;
    const state = taskStates[index]!;
    state.size = estimate.size;
    state.impact ??= structuredClone(estimate.signals?.impact ?? {
      source: estimate.signals?.source ?? 'none', query: `${task.title}\n${task.body}`.trim(), nodes: [], edges: [],
      totals: { filesTouched: estimate.signals?.filesTouched ?? 0, dependents: estimate.signals?.dependents ?? 0, testsPresent: estimate.signals?.testsPresent ?? false, nodes: 0, edges: 0 }, truncated: false,
    });
    writeCurrent('running', null);
    const route = options.baseline
      ? await routeBaseline({
          task: taskInput,
          estimate,
          config,
          ports: { history: ports.history, budget, trace: ports.trace },
          traceAttributes: { sessionId: runId, taskId: task.taskId, attempt: 1 },
        })
      : await routeTask({
          task: taskInput,
          estimate,
          config,
          ports: { history: ports.history, budget, trace: ports.trace },
          traceAttributes: { sessionId: runId, taskId: task.taskId, attempt: 1 },
        });
    const routeTraceId = lastTraceId(ports.trace);
    if (route.action === 'skip') {
      state.status = 'skipped';
      state.statusReason = route.statusReason;
      writeCurrent('running', null);
      continue;
    }
    const first = await runAttempt({
      runId,
      task,
      attempt: 1,
      tier: route.tier,
      ceilingNanos: task.firstAttemptCeilingUsd === undefined || options.baseline ? route.ceilingNanos : Math.min(route.ceilingNanos ?? Infinity, usdToNanos(task.firstAttemptCeilingUsd)),
      decision: task.firstAttemptCeilingUsd === undefined || options.baseline ? route.reason : `${route.reason} Deliberate first-attempt ceiling override: $${task.firstAttemptCeilingUsd.toFixed(3)} (normal ceiling remains an upper bound).`,
      escalatedFrom: null,
      handoff: 'none',
      handoffSummary: null,
      traceId: routeTraceId,
      config,
      configPath: options.configPath,
      ports,
      now,
      dryRun: options.dryRun,
      baseCommit,
      requiredBaseCommit: options.requiredBaseCommit,
      onChangedFiles: changedFor(index),
      onStartupError,
      onProgress: progressFor(index, 1, route.tier),
    });
    finishAttempt(first);
    if (first.result === 'stopped' && options.stopRequested?.()) first.resultReason = options.stopRequested()!;
    await recordHistory({ ports, row: first, dryRun: options.dryRun });
    await recordSpend(first);
    let latest = first;
    if (first.result !== 'passed' && first.result !== 'error' && !options.stopRequested?.()) {
      const escalation = await decideEscalation({
        previous: {
          attemptId: first.attemptId,
          taskId: first.taskId,
          attempt: first.attempt,
          size: first.size,
          tier: first.tier,
          result: first.result,
          sessionId: first.sessionId,
          branch: first.branch,
          checkpointId: first.checkpointId,
          resultReason: first.resultReason,
        },
        task,
        config,
        ports: { budget, handoff: ports.handoff, trace: ports.trace },
        traceAttributes: { sessionId: runId, taskId: first.taskId, attempt: 2 },
      });
      const escalationTraceId = lastTraceId(ports.trace);
      if (escalation.action === 'escalate') {
        const summaryRow = handoffSummaryLedgerRow({ runId, task, previous: first, decision: escalation, traceId: escalationTraceId, now });
        if (summaryRow) {
          ledger.push(summaryRow);
          await recordSpend(summaryRow);
        }
        latest = await runAttempt({
          runId,
          task,
          attempt: 2,
          tier: escalation.tier,
          ceilingNanos: escalation.ceilingNanos,
          decision: escalation.reason,
          escalatedFrom: escalation.escalatedFrom,
          handoff: escalation.handoff,
          handoffSummary: escalation.handoffSummary,
          traceId: escalationTraceId,
          config,
          configPath: options.configPath,
          ports,
          now,
          dryRun: options.dryRun,
          baseCommit,
          requiredBaseCommit: options.requiredBaseCommit,
          continueBranch: escalation.handoffBranch ?? first.branch,
          continueSessionId: first.sessionId,
          onChangedFiles: changedFor(index),
          onStartupError,
          onProgress: progressFor(index, 2, escalation.tier),
        });
        finishAttempt(latest);
        await recordHistory({ ports, row: latest, dryRun: options.dryRun });
        await recordSpend(latest);
      } else {
        latest.resultReason = latest.result === 'error' && latest.resultReason ? latest.resultReason : escalation.statusReason;
      }
    }
    const rows = ledger.filter((row) => row.taskId === task.taskId);
    state.status = statusFrom(latest.result);
    state.statusReason = latest.resultReason;
    state.attempts = latest.attempt;
    state.tier = latest.tier;
    state.model = latest.model;
    state.spentNanos = rows.reduce((sum, row) => sum + row.estimatedCostNanos, 0);
    state.escalated = latest.escalatedFrom !== null;
    state.prUrl = latest.prUrl;
    writeCurrent('running', null);
  }

  const endedAt = now().toISOString();
  let traceFlushFailure: string | null = null;
  try {
    await (ports.trace as (TracePort & { flush?: () => Promise<void> }) | undefined)?.flush?.();
  } catch {
    // Optional telemetry must not turn a completed run into a failed command.
    traceFlushFailure = 'neatlogs flush failed; the run completed and local evidence was retained.';
  }
  const runState = writeCurrent(options.stopRequested?.() ? 'interrupted' : 'finished', endedAt);
  if (traceFlushFailure) {
    runState.integrations.neatlogs = { status: 'error', detail: traceFlushFailure };
    assertValid(runState, ledger);
    writeRunFiles(outputDir, runState, ledger, options.latestRunDir);
  }
  const paths = writeRunFiles(outputDir, runState, ledger, options.latestRunDir);
  return { runState, ledger, ...paths };
}

import { loadEnv } from '../engine/env.js';
import type { IntegrationState } from '../schema/types.js';
import type { TraceAttributes, TracePort, TraceSpan, TraceValue } from '../agent/ports.js';

export interface NeatlogsSdk {
  init(options: { apiKey: string; workflowName: string; tags?: string[] }): Promise<unknown> | unknown;
  trace<T>(options: { name: string; kind: 'CHAIN'; sessionId?: string; input?: unknown; attributes?: Record<string, TraceValue> }, fn: () => Promise<T>): Promise<T>;
  injectTraceContext?(carrier: Record<string, string>): void;
  flush?(): Promise<void> | void;
  shutdown?(): Promise<void> | void;
}

export interface NeatlogsTraceOptions {
  workflowName?: string;
  tags?: string[];
  env?: Record<string, string>;
  sdk?: NeatlogsSdk | null;
  loadSdk?: () => Promise<NeatlogsSdk>;
}

type MutableSpan = TraceSpan & { attributes: TraceAttributes };

const DEFAULT_WORKFLOW = 'tally-cfo-agent';

function traceIdFromCarrier(carrier: Record<string, string>): string | null {
  const traceparent = carrier.traceparent;
  const match = typeof traceparent === 'string' ? /^[\da-f]{2}-([\da-f]{32})-[\da-f]{16}-[\da-f]{2}$/i.exec(traceparent) : null;
  return match?.[1] ?? null;
}

function serialisable(attributes: TraceAttributes): Record<string, TraceValue> {
  return Object.fromEntries(Object.entries(attributes).filter(([, value]) => ['string', 'number', 'boolean', 'object'].includes(typeof value)));
}

async function importNeatlogs(): Promise<NeatlogsSdk> {
  const dynamicImport = new Function('specifier', 'return import(specifier)') as (specifier: string) => Promise<NeatlogsSdk>;
  return dynamicImport('neatlogs');
}

export class NeatlogsTraceAdapter implements TracePort {
  private readonly apiKey: string | null;
  private readonly workflowName: string;
  private readonly tags: string[];
  private readonly sdkOverride: NeatlogsSdk | null | undefined;
  private readonly loadSdk: () => Promise<NeatlogsSdk>;
  private sdk: NeatlogsSdk | null = null;
  private initStarted: Promise<void> | null = null;
  private offReason: string | null = null;
  private lastTraceIdValue: string | null = null;
  private statusState: IntegrationState = { status: 'ok', detail: null };

  constructor(options: NeatlogsTraceOptions = {}) {
    const env = options.env ?? loadEnv();
    this.apiKey = env.NEATLOGS_API_KEY || null;
    this.workflowName = options.workflowName ?? DEFAULT_WORKFLOW;
    this.tags = options.tags ?? ['tally', 'cfo-agent'];
    this.sdkOverride = options.sdk;
    this.loadSdk = options.loadSdk ?? importNeatlogs;
    if (!this.apiKey) {
      this.offReason = 'NEATLOGS_API_KEY is missing';
      this.statusState = { status: 'missing', detail: this.offReason };
    }
  }

  status(): IntegrationState {
    return this.statusState.status === 'ok' ? { status: 'ok', detail: this.lastTraceIdValue } : this.statusState;
  }

  lastTraceId(): string | null {
    return this.lastTraceIdValue;
  }

  async span<T>(name: string, attributes: TraceAttributes, fn: (span: TraceSpan) => Promise<T>): Promise<T> {
    const sdk = await this.ready();
    if (!sdk) return fn({ set: () => {} });

    const span: MutableSpan = {
      attributes: { ...attributes },
      set: (next) => Object.assign(span.attributes, next),
    };
    const sessionId = typeof attributes.sessionId === 'string' ? attributes.sessionId : undefined;
    const safeAttributes = serialisable(attributes);
    let callbackStarted = false;
    let callbackCompleted = false;
    let callbackFailed = false;
    let callbackResult!: T;
    const callback = async (): Promise<T> => {
      callbackStarted = true;
      const carrier: Record<string, string> = {};
      sdk.injectTraceContext?.(carrier);
      this.lastTraceIdValue = traceIdFromCarrier(carrier);
      try {
        callbackResult = await fn(span);
        callbackCompleted = true;
        return callbackResult;
      } catch (error) {
        callbackFailed = true;
        throw error;
      }
    };
    try {
      const traced = await sdk.trace({ name, kind: 'CHAIN', ...(sessionId ? { sessionId } : {}), input: safeAttributes, attributes: safeAttributes }, callback);
      // Some exporters finish delivery after the callback resolves. Keep the
      // callback's result if delivery reports a late failure.
      return callbackCompleted ? callbackResult : traced;
    } catch (error) {
      // Never run application work twice. Callback failures belong to Tally and
      // must be rethrown; exporter failures before callback entry are optional.
      if (callbackFailed || (callbackStarted && !callbackCompleted)) throw error;
      if (callbackCompleted) return callbackResult;
      this.offReason = 'neatlogs trace export failed; the run continued without this span';
      this.statusState = { status: 'error', detail: this.offReason };
      return fn({ set: () => {} });
    }
  }

  async flush(): Promise<void> {
    const sdk = await this.ready();
    try {
      await sdk?.flush?.();
    } catch {
      this.offReason = 'neatlogs flush failed; queued trace data may be pending';
      this.statusState = { status: 'error', detail: this.offReason };
    }
  }

  async shutdown(): Promise<void> {
    const sdk = await this.ready();
    await this.flush();
    try {
      await sdk?.shutdown?.();
    } catch {
      this.offReason = 'neatlogs shutdown failed; the run data remains local';
      this.statusState = { status: 'error', detail: this.offReason };
    }
  }

  private async ready(): Promise<NeatlogsSdk | null> {
    if (this.sdk || this.offReason) return this.sdk;
    this.initStarted ??= this.initialise();
    await this.initStarted;
    return this.sdk;
  }

  private async initialise(): Promise<void> {
    if (!this.apiKey) return;
    try {
      const sdk = this.sdkOverride === undefined ? await this.loadSdk() : this.sdkOverride;
      if (!sdk) {
        this.offReason = 'neatlogs SDK is not installed';
        this.statusState = { status: 'missing', detail: this.offReason };
        return;
      }
      await sdk.init({ apiKey: this.apiKey, workflowName: this.workflowName, tags: this.tags });
      this.sdk = sdk;
      this.offReason = null;
      this.statusState = { status: 'ok', detail: null };
    } catch {
      this.offReason = 'neatlogs SDK is not available';
      this.statusState = { status: 'missing', detail: this.offReason };
      this.sdk = null;
    }
  }
}
import { describe, expect, it } from 'vitest';
import { NeatlogsTraceAdapter, type NeatlogsSdk } from './neatlogs.js';

class FakeNeatlogs implements NeatlogsSdk {
  initCalls: Array<{ apiKey: string; workflowName: string; tags?: string[] }> = [];
  traceCalls: Array<{ name: string; sessionId?: string; input?: unknown; attributes?: unknown }> = [];
  flushed = 0;
  shutDown = 0;

  async init(options: { apiKey: string; workflowName: string; tags?: string[] }): Promise<void> {
    this.initCalls.push(options);
  }

  async trace<T>(options: { name: string; kind: 'CHAIN'; sessionId?: string; input?: unknown; attributes?: unknown }, fn: () => Promise<T>): Promise<T> {
    this.traceCalls.push(options);
    return fn();
  }

  injectTraceContext(carrier: Record<string, string>): void {
    carrier.traceparent = '00-1234567890abcdef1234567890abcdef-abcdef1234567890-01';
  }

  async flush(): Promise<void> {
    this.flushed += 1;
  }

  async shutdown(): Promise<void> {
    this.shutDown += 1;
  }
}

class FailingTraceNeatlogs extends FakeNeatlogs {
  override async trace<T>(): Promise<T> {
    throw new Error('export unavailable');
  }
}

describe('NeatlogsTraceAdapter', () => {
  it('is off and acts as a no-op when the key is missing', async () => {
    const adapter = new NeatlogsTraceAdapter({ env: {}, sdk: new FakeNeatlogs() });
    let called = false;
    await adapter.span('tally.route', { taskId: 'T1' }, async (span) => {
      span.set({ action: 'start' });
      called = true;
    });
    expect(called).toBe(true);
    expect(adapter.status()).toEqual({ status: 'missing', detail: 'NEATLOGS_API_KEY is missing' });
    expect(adapter.lastTraceId()).toBeNull();
  });

  it('initialises the SDK, passes sessionId on trace(), and captures the trace id', async () => {
    const sdk = new FakeNeatlogs();
    const adapter = new NeatlogsTraceAdapter({ env: { NEATLOGS_API_KEY: 'secret-key' }, sdk, workflowName: 'wf', tags: ['one'] });
    await adapter.span('tally.ceiling.poll', { sessionId: 'sess-1', taskId: 'T1' }, async (span) => {
      span.set({ action: 'stop' });
    });
    expect(sdk.initCalls).toEqual([{ apiKey: 'secret-key', workflowName: 'wf', tags: ['one'] }]);
    expect(sdk.traceCalls).toMatchObject([{ name: 'tally.ceiling.poll', sessionId: 'sess-1' }]);
    expect(sdk.traceCalls[0]?.attributes).toMatchObject({ sessionId: 'sess-1', taskId: 'T1' });
    expect(JSON.stringify(sdk.initCalls)).not.toContain('NEATLOGS_API_KEY');
    expect(adapter.lastTraceId()).toBe('1234567890abcdef1234567890abcdef');
    expect(adapter.status()).toEqual({ status: 'ok', detail: '1234567890abcdef1234567890abcdef' });
  });

  it('flushes before shutdown', async () => {
    const sdk = new FakeNeatlogs();
    const adapter = new NeatlogsTraceAdapter({ env: { NEATLOGS_API_KEY: 'secret-key' }, sdk });
    await adapter.shutdown();
    expect(sdk.flushed).toBe(1);
    expect(sdk.shutDown).toBe(1);
  });

  it('turns off when the SDK cannot be loaded', async () => {
    const adapter = new NeatlogsTraceAdapter({
      env: { NEATLOGS_API_KEY: 'secret-key' },
      loadSdk: async () => {
        throw new Error('not installed');
      },
    });
    await adapter.span('tally.route', {}, async () => {});
    expect(adapter.status()).toEqual({ status: 'missing', detail: 'neatlogs SDK is not available' });
  });

  it('keeps application work running when a trace export fails before the callback', async () => {
    const adapter = new NeatlogsTraceAdapter({ env: { NEATLOGS_API_KEY: 'secret-key' }, sdk: new FailingTraceNeatlogs() });
    let calls = 0;
    await expect(adapter.span('tally.route', {}, async () => { calls += 1; return 'completed'; })).resolves.toBe('completed');
    expect(calls).toBe(1);
    expect(adapter.status()).toEqual({ status: 'error', detail: 'neatlogs trace export failed; the run continued without this span' });
  });

  it('keeps a flush failure out of the run result', async () => {
    const sdk = new FakeNeatlogs();
    sdk.flush = async () => { throw new Error('network unavailable'); };
    const adapter = new NeatlogsTraceAdapter({ env: { NEATLOGS_API_KEY: 'secret-key' }, sdk });
    await expect(adapter.flush()).resolves.toBeUndefined();
    expect(adapter.status()).toEqual({ status: 'error', detail: 'neatlogs flush failed; queued trace data may be pending' });
  });
});

    this.store.write(current);
  }
}

class SdkCfoaiMcpClient implements CfoaiMcpClient {
  private readonly client = new Client({ name: 'tally', version: '0.1.0' });
  private readonly transport: StreamableHTTPClientTransport;

  constructor(serverUrl: string, authProvider: OAuthClientProvider) {
    this.transport = new StreamableHTTPClientTransport(new URL(serverUrl), { authProvider });
  }

  async connect(): Promise<void> {
    await this.client.connect(this.transport);
  }

  async listTools(): ReturnType<CfoaiMcpClient['listTools']> {
    return this.client.listTools();
  }

  async callTool(name: string, args: Record<string, unknown>): Promise<unknown> {
    return this.client.callTool({ name, arguments: args });
  }

  async close(): Promise<void> {
    await this.client.close();
  }

  async finishAuth(code: string): Promise<void> {
    await this.transport.finishAuth(code);
  }
}

/** A separate MCP connection using only Tally's own OAuth cache. */
export function createCfoaiClient(tokenPath?: string): CfoaiMcpClient {
  return new SdkCfoaiMcpClient(
    CFOAI_SERVER_URL,
    new CfoaiOAuthProvider(new FileTokenStore(tokenPath), undefined, async () => undefined),
  );
}

export interface CfoaiBudgetAdapterOptions {
  config?: CfoaiBudgetConfig;
  client?: CfoaiMcpClient;
  now?: () => Date;
}

export class CfoaiBudgetAdapter implements BudgetPort {
  private readonly config: NormalizedCfoaiBudgetConfig;
  private readonly now: () => Date;
  private connected = false;
  private usable = false;
  private statusState: IntegrationState = { status: 'missing', detail: CFOAI_FIX_COMMAND };
  private toolsChecked = false;
  private runBaseSpendNanos: number | null = null;
  private baseDetailSpendNanos: Map<string, number> | null = null;
  private seededDetailGapNanos = 0;
  private readyPromise: Promise<void> | null = null;

  constructor(options: CfoaiBudgetAdapterOptions = {}) {
    this.config = normalizeCfoaiConfig(options.config);
    this.now = options.now ?? (() => new Date());
    this.client =
      options.client ??
      new SdkCfoaiMcpClient(this.config.serverUrl, new CfoaiOAuthProvider(new FileTokenStore(), undefined, async () => undefined));
  }

  private readonly client: CfoaiMcpClient;

  status(): IntegrationState {
    return this.statusState;
  }

  tableUrl(): string | undefined {
    return this.config.tableUrl;
  }

  setRunBaseSpendNanos(nanos: number): void {
    this.runBaseSpendNanos = Math.max(0, Math.round(nanos));
  }

  spendDetailTableUrl(): string | undefined {
    return this.config.spendDetailTableUrl;
  }

  async budgetLimitNanos(): Promise<number> {
    await this.ensureReady();
    return usdToNanos(await this.readUsd(this.config.budgetRow));
  }

  async currentSpendNanos(): Promise<number> {
    await this.ensureReady();
    return usdToNanos(await this.readUsd(this.config.spendRow));
  }

  async remainingNanos(): Promise<number> {
    const [budget, spend] = await Promise.all([this.budgetLimitNanos(), this.currentSpendNanos()]);
    return budget - spend;
  }

  async writeCumulativeActualSpend(runSpendNanos: number): Promise<void> {
    await this.ensureReady();
    try {
      if (this.runBaseSpendNanos === null) this.runBaseSpendNanos = await this.currentSpendNanos();
      const total = this.runBaseSpendNanos + runSpendNanos;
      const usd = Number(nanosToUsd(total).toFixed(9));
      const result = await this.client.callTool('edit_table_blocks', {
