        skipped: false,
      });
    } else {
      planned.push({
        taskId: task.taskId,
        title: task.title,
        size: estimate.size,
        tier: null,
        model: null,
        harness: null,
        ceilingNanos: null,
        decision: route.reason,
        skipped: true,
      });
    }
  }
