import { existsSync, readFileSync } from 'node:fs';
import { basename, dirname, resolve } from 'node:path';
import { contentHash, configHash, installRecordPath, type InstallRecord } from './install-record.js';
import { applyInitTransaction, finishInitTransaction, pendingInitPath, readPendingInit, type InitTransaction } from './init-transaction.js';
import { validateConfig, type TallyConfig } from '../schema/index.js';
import { parse as parseYaml, stringify as stringifyYaml } from 'yaml';
import { runDoctor, type DoctorLine } from './doctor.js';
import { tierPriceNote } from './pricing.js';
import { CommandError, resolveAoBinary, runCommand } from '../adapters/command.js';
import { checkCfoaiConnection } from '../adapters/cfoai.js';
import { loadEnv } from './env.js';
import { configureIntegrations } from '../onboarding/index.js';
import { loadConfig } from './config.js';
import { applyReinit, finishReinit, prepareReinit, readReinit, reinitPath } from './reinit.js';

export interface InitCommandResult {
  stdout: string;
  stderr: string;
}

export class InitError extends Error {}

export type InitCommandRunner = (file: string, args: string[], options?: { cwd?: string }) => Promise<InitCommandResult>;
export type PromptReader = (question: string, defaultValue?: string) => Promise<string>;

export interface InitOptions {
  cwd?: string;
  configPath?: string;
  command?: InitCommandRunner;
  readLine?: PromptReader;
  doctor?: (configPath: string) => Promise<DoctorLine[]>;
  print?: (line: string) => void;
  yes?: boolean;
  dryRun?: boolean;
  env?: Record<string, string>;
  cfoaiCheck?: typeof checkCfoaiConnection;
  onboarding?: typeof configureIntegrations;
}

export interface InitResult {
  applied: boolean;
  configPath: string;
  projectId: string;
  testCommand: string;
  setupCommand: string | null;
  baseBranch: string;
  tiers: string[];
  doctor: DoctorLine[];
}

const CODEx_TIERS = [
  ['cheap', 'gpt-5.6-luna', 0.2, 0.02, 1.2, 0.2],
  ['middle', 'gpt-5.6-terra', 2, 0.2, 12, 0.5],
  ['top', 'gpt-5.6-sol', 4, 0.4, 20, 1],
] as const;

const CLAUDE_TIERS = [
  ['cheap', 'claude-haiku-4-5-20251001', 1, 0.1, 5, 0.2],
  ['middle', 'claude-sonnet-5-5', 2, 0.2, 10, 0.5],
  ['top', 'claude-opus-5-5', 4, 0.4, 20, 1],
] as const;

export async function defaultCommand(file: string, args: string[], options?: { cwd?: string; aoBin?: string }): Promise<InitCommandResult> {
  if (file === 'ao') resolveAoBinary(options);
  // The CLI config mirror drops fields such as effort; use the full daemon object.
  if (file === 'ao' && args[0] === 'project' && (args[1] === 'get' || args[1] === 'set-config')) {
    const id = encodeURIComponent(args[2]!);
    const editing = args[1] === 'set-config';
    const response = await fetch(`http://127.0.0.1:3001/api/v1/projects/${id}${editing ? '/config' : ''}`, {
      method: editing ? 'PUT' : 'GET',
      ...(editing ? { headers: { 'content-type': 'application/json' }, body: JSON.stringify({ config: JSON.parse(args[args.indexOf('--config-json') + 1]!) }) } : {}),
      signal: AbortSignal.timeout(10_000),
    }).catch(() => { throw new InitError('AO project API could not be reached; start AO and retry.'); });
    if (!response.ok) throw new InitError(`AO project ${args[1]} failed: HTTP ${response.status}; check AO is running before retrying.`);
    return { stdout: JSON.stringify(await response.json()), stderr: '' };
  }
  return runCommand(file, args, options);
}

async function projectOrNull(command: InitCommandRunner, projectId: string, cwd: string): Promise<string | null> {
  try { return (await command('ao', ['project', 'get', projectId, '--json'], { cwd })).stdout; }
  catch (error) {
    if (error instanceof Error && /missing project|not found|HTTP 404/i.test(error.message)) return null;
    throw error;
  }
}

export async function defaultReadLine(question: string, defaultValue = ''): Promise<string> {
  const { createInterface } = await import('node:readline/promises');
  const readline = createInterface({ input: process.stdin, output: process.stdout });
  try {
    const suffix = defaultValue ? ` [${defaultValue}]` : '';
    const answer = await readline.question(`${question}${suffix}: `);
    return answer.trim() || defaultValue;
  } finally {
    readline.close();
  }
}

async function commandOrNull(command: InitCommandRunner, file: string, args: string[], cwd: string): Promise<string | null> {
  try {
    return (await command(file, args, { cwd })).stdout.trim();
  } catch (error) {
    if (file === 'ao' && error instanceof CommandError) throw error;
    return null;
  }
}

function hasMakeTarget(cwd: string, target: string): boolean {
  const path = resolve(cwd, 'Makefile');
  if (!existsSync(path)) return false;
  return new RegExp(`^${target}[ \\t]*:`, 'm').test(readFileSync(path, 'utf8'));
}

function packageJsonScript(cwd: string, script: string): boolean {
  const path = resolve(cwd, 'package.json');
  if (!existsSync(path)) return false;
  try {
    const parsed = JSON.parse(readFileSync(path, 'utf8')) as { scripts?: Record<string, unknown> };
    const value = parsed.scripts?.[script];
    return typeof value === 'string' && value.trim().length > 0;
  } catch {
    return false;
  }
}

function detectTestCommand(cwd: string): string | null {
  if (hasMakeTarget(cwd, 'test')) return 'make test';
  if (packageJsonScript(cwd, 'test')) return 'npm test';
  for (const [file, section] of [
    ['pyproject.toml', 'tool.pytest.ini_options'], ['pytest.ini', 'pytest'],
    ['tox.ini', 'pytest'], ['setup.cfg', 'tool:pytest'],
  ] as const) {
    const path = resolve(cwd, file);
    if (!existsSync(path)) continue;
    const text = readFileSync(path, 'utf8');
    if (text.split('\n').some((line) => line.trim().split('#')[0]!.trim() === `[${section}]`)) return 'pytest';
  }
  if (existsSync(resolve(cwd, 'Cargo.toml'))) return 'cargo test';
  if (existsSync(resolve(cwd, 'go.mod'))) return 'go test ./...';
  return null;
}

function detectSetupCommand(cwd: string): string | null {
  if (hasMakeTarget(cwd, 'setup')) return 'make setup';
  if (packageJsonScript(cwd, 'setup')) return 'npm run setup';
  if (existsSync(resolve(cwd, 'package.json'))) {
    if (existsSync(resolve(cwd, 'package-lock.json'))) return 'npm ci';
    if (existsSync(resolve(cwd, 'pnpm-lock.yaml'))) return 'pnpm install --frozen-lockfile';
    if (existsSync(resolve(cwd, 'yarn.lock'))) return 'yarn install --frozen-lockfile';
  }
  if (existsSync(resolve(cwd, 'pyproject.toml')) && existsSync(resolve(cwd, 'uv.lock'))) return 'uv sync';
  return null;
}

function slugFromRemote(remote: string | null): string | undefined {
  if (!remote) return undefined;
  const match = /[:/]([^/:]+\/[^/]+?)(?:\.git)?$/.exec(remote);
  return match?.[1];
}

function parseYes(value: string): boolean {
  return /^y(?:es)?$/i.test(value.trim());
}

function parseBudget(value: string): number {
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 40;
}

function parseAoAgents(output: string | null): Set<string> {
  const found = new Set<string>();
  if (!output) return found;
  try {
    const parsed = JSON.parse(output) as { installed?: unknown };
    // AO also lists every supported harness; those are not evidence of installation.
    const agents = parsed.installed;
    if (!Array.isArray(agents)) return found;
    for (const agent of agents) {
      if (agent && typeof agent === 'object' && agent.installed !== false &&
          (agent.id === 'codex' || agent.id === 'claude-code')) found.add(agent.id);
    }
  } catch {
    // An unavailable or malformed installation report must not invent a harness.
  }
  return found;
}

function tiersFor(agents: Set<string>) {
  if (!agents.has('codex') && !agents.has('claude-code')) {
    throw new InitError('No installed Codex or Claude Code agent detected. Install and sign in to one, then check `ao agent ls --refresh --json` before running tally init.');
  }
  const harness = agents.has('codex') ? 'codex' : 'claude-code';
  const source = harness === 'codex' ? CODEx_TIERS : CLAUDE_TIERS;
  const provider = harness === 'codex' ? 'openai' : 'anthropic';
  return source.map(([name, model, input, cached, output, ceilingFraction]) => ({
    name,
    harness,
    sessionMode: 'tui' as const,
    provider,
    model,
    price: { inputUsdPerMTok: input, cachedInputUsdPerMTok: cached, outputUsdPerMTok: output },
    priceNote: tierPriceNote({ model, provider, price: { inputUsdPerMTok: input, cachedInputUsdPerMTok: cached, outputUsdPerMTok: output } }),
    ceilingFraction,
  }));
}

function withPostCreate(config: unknown, setupCommand: string | null): Record<string, unknown> {
  const base = typeof config === 'object' && config !== null && !Array.isArray(config) ? { ...(config as Record<string, unknown>) } : {};
  if (!setupCommand) return base;
  const current = Array.isArray(base.postCreate) ? base.postCreate.filter((item): item is string => typeof item === 'string') : [];
  base.postCreate = current.includes(setupCommand) ? current : [...current, setupCommand];
  return base;
}

async function initPrerequisites(config: TallyConfig, command: InitCommandRunner, cwd: string, options: InitOptions): Promise<void> {
  await command('ao', ['status'], { cwd });
  await command('git', ['--version'], { cwd });
  await command('gh', ['auth', 'status'], { cwd });
  const env = options.env ?? { ...loadEnv(), ...process.env };
  if (config.integrations.neatlogs && !env.NEATLOGS_API_KEY) throw new InitError('neatlogs was requested but NEATLOGS_API_KEY is missing; add it to ~/.tally/.env before rerunning init; nothing was changed.');
  if (config.integrations.cfoai) {
    const status = await (options.cfoaiCheck ?? checkCfoaiConnection)();
    if (status.status !== 'ok') throw new InitError('cfo.ai was requested but is not connected; run tally login cfoai, then rerun init; nothing was changed.');
  }
  if (config.integrations.entire) {
    await command('entire', ['--version'], { cwd });
    await command('entire', ['graph', '--help'], { cwd });
    const status = JSON.parse((await command('entire', ['status', '--json'], { cwd })).stdout);
    if (status.enabled !== true) throw new InitError(`Entire was requested but is not enabled in ${cwd}; run cd ${JSON.stringify(cwd)} && entire enable, review its repository/hook changes and trust the harness hooks, then rerun init; nothing was changed.`);
  }
}

async function finishInit(options: InitOptions, transaction: InitTransaction, command: InitCommandRunner, recordPath: string): Promise<DoctorLine[]> {
  await applyInitTransaction(transaction, command, recordPath);
  try {
    const doctor = await (options.doctor ?? ((path) => runDoctor({ configPath: path })))(transaction.configPath);
    finishInitTransaction(transaction.configPath);
    return doctor;
  } catch (error) {
    throw new InitError(`Init configured AO and wrote ${transaction.configPath} and ${recordPath}, but doctor failed: ${error instanceof Error ? error.message : 'unknown error'}; rerun tally init --config ${JSON.stringify(transaction.configPath)} to resume from ${pendingInitPath(transaction.configPath)}; files will not be overwritten.`);
  }
}

async function reconfigureInit(options: InitOptions, configPath: string, print: (line: string) => void, readLine: PromptReader): Promise<InitResult> {
  const pending = readReinit(configPath);
  const before = pending ? parseYaml(pending.beforeConfig) as TallyConfig : loadConfig(configPath);
  const config = pending ? parseYaml(pending.afterConfig) as TallyConfig : structuredClone(before);
  if (!validateConfig(before).ok || !validateConfig(config).ok) throw new InitError('Re-init recovery configuration is invalid; no changes made.');
  const targetRepo = resolve(dirname(configPath), config.repo.path);
  if (!pending) {
    for (const name of ['neatlogs', 'entire', 'cfoai'] as const) {
      const label = name === 'cfoai' ? 'cfo.ai' : name === 'entire' ? 'Entire' : name;
      config.integrations[name] = parseYes(await readLine(`Enable ${label} integration? y/N`, before.integrations[name] ? 'y' : 'N'));
    }
    if (before.integrations.cfoai && !config.integrations.cfoai && config.budget.source === 'cfoai') {
      config.budget = { source: 'config', usd: before.budget.usd };
    }
    const newlyEnabled = (['cfoai', 'neatlogs', 'entire'] as const).filter((name) => config.integrations[name] && !before.integrations[name]);
    if (newlyEnabled.length > 0) {
      await (options.onboarding ?? configureIntegrations)({
        config,
        repoRoot: targetRepo,
        integrationNames: newlyEnabled,
        ui: {
          print,
          confirm: async (question) => !options.yes && parseYes(await readLine(`${question} y/N`, 'N')),
          select: async (question, choices) => {
            if (options.yes) return null;
            choices.forEach((choice, index) => print(`${index + 1}. ${choice}`));
            const value = (await readLine(`${question}; enter a number, or blank to skip`, '')).trim();
            const index = Number(value) - 1;
            return /^\d+$/.test(value) && index >= 0 && index < choices.length ? index : null;
          },
        },
      });
    }
  }
  const result = { configPath, projectId: config.repo.aoProject ?? '', testCommand: config.test.command, setupCommand: config.test.setupCommand ?? null, baseBranch: config.repo.baseBranch, tiers: config.tiers.map((tier) => `${tier.name}:${tier.harness}/${tier.model}`) };
  if (!pending && configHash(config) === configHash(before)) {
    print('No changes proposed; existing configuration and installation ownership are unchanged.');
    return { ...result, applied: false, doctor: [] };
  }
  const command: InitCommandRunner = options.command ?? ((file, args, commandOptions) => defaultCommand(file, args, { ...commandOptions, aoBin: config.repo.aoBin ? resolve(dirname(configPath), config.repo.aoBin) : undefined }));
  await initPrerequisites(config, command, targetRepo, options);
  const plan = pending ?? prepareReinit(configPath, stringifyYaml(config));
  print(`Tally re-init proposed diff for ${configPath}:`);
  for (const key of Object.keys(config) as (keyof TallyConfig)[]) {
    if (configHash(before[key]) !== configHash(config[key])) {
      print(`- ${key}: ${JSON.stringify(before[key])}`);
      print(`+ ${key}: ${JSON.stringify(config[key])}`);
    }
  }
  print(`Preserve all other settings; ${plan.beforeRecord === null ? 'no installation ownership record will be created' : 'preserve installation ownership and update only its config hash'}. AO project, setup hooks and worker permissions will not change.`);
  if (pending) print(`Resume interrupted re-init from ${reinitPath(configPath)}.`);
  if (options.dryRun || (!options.yes && !parseYes(await readLine('Apply these changes? y/N', 'N')))) return { ...result, applied: false, doctor: [] };
  applyReinit(plan);
  try {
    const doctor = await (options.doctor ?? ((path) => runDoctor({ configPath: path })))(configPath);
    finishReinit(configPath);
    return { ...result, applied: true, doctor };
  } catch (error) {
    throw new InitError(`Re-init updated ${configPath} and preserved installation ownership, but doctor failed: ${error instanceof Error ? error.message : 'unknown error'}; AO settings were unchanged; rerun tally init --config ${JSON.stringify(configPath)} to resume safely.`);
  }
}

export async function runInit(options: InitOptions = {}): Promise<InitResult> {
  const command = options.command ?? defaultCommand;
  const print = options.print ?? console.log;
  const readLine = options.readLine ?? (options.yes || options.dryRun ? async (_question: string, defaultValue = '') => defaultValue : defaultReadLine);
  const cwd = options.cwd ?? process.cwd();
  const repoRoot = (await commandOrNull(command, 'git', ['rev-parse', '--show-toplevel'], cwd)) ?? cwd;
  const configPath = resolve(repoRoot, options.configPath ?? 'tally.yaml');
  const recordPath = installRecordPath(configPath);
  const pending = readPendingInit(configPath);
  if (pending) {
    const saved = parseYaml(pending.configText) as TallyConfig;
    const validation = validateConfig(saved);
    if (!validation.ok || resolve(pending.repoRoot) !== resolve(repoRoot)) throw new InitError('Init recovery configuration is invalid or belongs to a different repository; no changes made.');
    const resumeCommand: InitCommandRunner = options.command ?? ((file, args, commandOptions) => defaultCommand(file, args, { ...commandOptions, aoBin: saved.repo.aoBin ? resolve(dirname(configPath), saved.repo.aoBin) : undefined }));
    try { await initPrerequisites(saved, resumeCommand, repoRoot, options); }
    catch (error) { throw new InitError(`Incomplete init remains at ${pendingInitPath(configPath)}; ${configPath} ${existsSync(configPath) ? 'exists' : 'was not written'}, ${recordPath} ${existsSync(recordPath) ? 'exists' : 'was not written'}; no additional changes made: ${error instanceof Error ? error.message : 'prerequisites failed'}; fix the prerequisite and rerun tally init --config ${JSON.stringify(configPath)}.`); }
    print(`Resume incomplete init from ${pendingInitPath(configPath)}; preserve matching files and existing AO settings.\n${pending.configText}`);
    print(`AO project ${pending.record.projectId}; setup entry: ${pending.record.addedSetupCommand ?? 'none'}; worker allow-list: not installed; no global harness settings changed.`);
    const result = { configPath, projectId: pending.record.projectId, testCommand: saved.test.command, setupCommand: saved.test.setupCommand ?? null, baseBranch: saved.repo.baseBranch, tiers: saved.tiers.map((tier) => `${tier.name}:${tier.harness}/${tier.model}`) };
    if (options.dryRun || (!options.yes && !parseYes(await readLine('Resume these changes? y/N', 'N')))) return { ...result, applied: false, doctor: [] };
    return { ...result, applied: true, doctor: await finishInit(options, pending, resumeCommand, recordPath) };
  }
  if (existsSync(configPath) || readReinit(configPath)) return reconfigureInit(options, configPath, print, readLine);
  if (existsSync(recordPath)) throw new InitError(`An install record exists without ${configPath}; preserve it and use tally uninstall --config ${JSON.stringify(configPath)} to remove the owned partial installation before retrying.`);

import { Ajv2020 } from 'ajv/dist/2020.js';
import {
  CfoaiBudgetAdapter, cfoaiMonthColumn, checkCfoaiConnection, createCfoaiClient, loginCfoai,
  type CfoaiMcpClient,
} from '../adapters/cfoai.js';
import type { IntegrationState } from '../schema/types.js';
import type { IntegrationOnboarding, OnboardingContext, OnboardingResult } from './types.js';

type ObjectValue = Record<string, unknown>;
const object = (value: unknown): ObjectValue => value && typeof value === 'object' && !Array.isArray(value)
  ? value as ObjectValue : {};
const text = (value: unknown): string | undefined => typeof value === 'string' && value.trim() ? value : undefined;
const https = (value: unknown): string | undefined => {
  try {
    const url = new URL(String(value));
    return url.protocol === 'https:' && !url.username && !url.password ? url.href : undefined;
  } catch { return undefined; }
};

function payload(result: unknown): ObjectValue {
  const r = object(result);
  if (r.isError === true) throw new Error('cfo.ai refused the operation');
  if (r.structuredContent) return object(r.structuredContent);
  const blocks = Array.isArray(r.content) ? r.content : [];
  for (const block of blocks) {
    const b = object(block);
    if (b.type === 'text' && typeof b.text === 'string') {
      try { return object(JSON.parse(b.text)); } catch { /* Try the next content block. */ }
    }
  }
  throw new Error('cfo.ai returned an unreadable response');
}

async function choose(context: OnboardingContext, question: string, values: ObjectValue[], name: (v: ObjectValue) => string): Promise<ObjectValue | null> {
  if (values.length === 1) return values[0]!;
  if (!values.length) return null;
  const index = await context.ui.select(question, values.map(name));
  return index === null ? null : values[index] ?? null;
}

export interface CfoaiOnboardingOptions {
  client?: () => CfoaiMcpClient;
  check?: () => Promise<IntegrationState>;
  login?: () => Promise<unknown>;
  now?: () => Date;
}

/** No init-file writes, no other harness's credentials, and no model edits without consent. */
export class CfoaiOnboarding implements IntegrationOnboarding {
  private readonly options: CfoaiOnboardingOptions;
  constructor(options: CfoaiOnboardingOptions = {}) { this.options = options; }

  async check(): Promise<IntegrationState> {
    try { return await (this.options.check ?? checkCfoaiConnection)(); }
    catch { return { status: 'missing', detail: 'cfo.ai is unavailable; run tally login cfoai.' }; }
  }

  async connect(context: OnboardingContext): Promise<IntegrationState> {
    const current = await this.check();
    if (current.status === 'ok') return current;
    context.ui.print('cfo.ai needs a Tally connection. No account? Sign up at https://app.cfo.ai; you can skip for now.');
    if (!await context.ui.confirm('Open the browser to connect Tally to cfo.ai?')) {
      return { status: 'off', detail: 'cfo.ai skipped; the tally.yaml budget remains available.' };
    }
    try {
      await (this.options.login ?? loginCfoai)();
      return await this.check();
    } catch {
      return { status: 'missing', detail: 'cfo.ai login did not complete; run tally login cfoai to retry.' };
    }
  }

  async configure(context: OnboardingContext): Promise<OnboardingResult> {
    const off = (detail: string): OnboardingResult => ({
      enabled: false, state: { status: 'off', detail },
      budget: { source: 'config', usd: context.config.budget.usd },
    });
    const connection = await this.connect(context);
    if (connection.status !== 'ok') {
      context.ui.print(connection.detail ?? 'cfo.ai skipped.');
      return { ...off(connection.detail ?? 'cfo.ai unavailable'), state: connection };
    }
    const client = (this.options.client ?? createCfoaiClient)();
    try {
      await client.connect();
      const listed = await client.listTools();
      const tools = new Map(listed.tools.map(tool => [tool.name, tool]));
      const call = async (name: string, args: ObjectValue): Promise<ObjectValue> => {
        const tool = tools.get(name);
        if (!tool) throw new Error(`Missing ${name}`);
        // Refuse an unvalidated write if a server does not publish its edit schema.
        if (name.startsWith('edit_') && !tool.inputSchema) throw new Error('Missing edit schema');
        if (tool.inputSchema) {
          const validator = new Ajv2020({ strict: false, allErrors: true }).compile(tool.inputSchema);
          if (!validator(args)) throw new Error(`Incompatible ${name} schema`);
        }
        return payload(await client.callTool(name, args));
      };
      const orgs = await call('list_orgs', {});
      const workspace = await choose(context, 'Choose a cfo.ai workspace (or skip)',
        Array.isArray(orgs.orgs) ? orgs.orgs.map(object) : [], v => `${v.name} (${v.org_id})`);
      if (!workspace) return off('cfo.ai skipped: no workspace selected. Sign up at https://app.cfo.ai.');
      const orgId = text(workspace.org_id) ?? (typeof workspace.org_id === 'number' ? String(workspace.org_id) : undefined);
      if (!orgId) throw new Error('Workspace has no ID');
      const scenarioResult = await call('inspect_scenarios', { org_id: orgId, list: {} });
      const scenarioObject = await choose(context, 'Choose a cfo.ai scenario (or skip)',
        Array.isArray(scenarioResult.scenarios) ? scenarioResult.scenarios.map(object) : [], v => String(v.display_name));
      if (!scenarioObject) return off('cfo.ai skipped: no scenario selected.');
      const scenario = text(scenarioObject.display_name);
      if (!scenario) throw new Error('Scenario has no name');
      const existing = context.config.budget.cfoai;
      const table = existing?.table ?? 'Tally agent budget';
      const detailTable = existing?.spendDetailTable ?? 'Tally spend detail';
      const budgetRow = existing?.budgetRow ?? 'Agent budget';
      const spendRow = existing?.spendRow ?? 'Agent spend';
      const remainingRow = existing?.remainingRow ?? 'Budget remaining';
      const tierSpendRows = Object.fromEntries(context.config.tiers.map(tier => [
        tier.name, existing?.tierSpendRows?.[tier.name] ?? `Tier spend - ${tier.name}`,
      ]));
      const runSpendRow = existing?.runSpendRow ?? 'Run spend - current';
      const cumulativeRunSpendRow = existing?.cumulativeRunSpendRow ?? 'Run spend - cumulative';
      const scope = { org_id: orgId, scenario };
      const inspect = async (): Promise<ObjectValue[]> => {
        const result = await call('inspect_table_blocks', { ...scope, list: { target: [table, detailTable] } });
        if (!Array.isArray(result.blocks)) throw new Error('Missing table discovery');
        return result.blocks.map(object);
      };
      let blocks = await inspect();
      const find = (name: string) => {
        const matches = blocks.filter(b => b.display_name === name);
        if (matches.length > 1) throw new Error('Ambiguous table');
        return matches[0];
      };
      const now = (this.options.now ?? (() => new Date()))();
      const month = cfoaiMonthColumn(now);
      const budgetRows = [budgetRow, spendRow, remainingRow];
      const detailRows = [...Object.values(tierSpendRows), runSpendRow, cumulativeRunSpendRow];
      const missing = [!find(table) ? table : null, !find(detailTable) ? detailTable : null].filter((x): x is string => x !== null);
      if (missing.length) {
        context.ui.print(`Create on page Tally in ${workspace.name}, scenario ${scenario}, monthly USD columns starting ${month}:`);
        if (missing.includes(table)) context.ui.print(`${table}: ${budgetRow} = $${context.config.budget.usd}; ${spendRow} = $0; ${remainingRow} = ${budgetRow} - ${spendRow} (formula).`);
        if (missing.includes(detailTable)) context.ui.print(`${detailTable}: ${detailRows.join(', ')} = $0 each.`);
        context.ui.print('Existing tables and spend are not reset. New tables get their own variables.');
        if (!await context.ui.confirm('Create these missing cfo.ai tables?')) return off('cfo.ai skipped: table creation declined.');
        const end = `${now.getUTCFullYear() + 1}-12-31`;
        for (const name of missing) {
          const rows = name === table ? budgetRows : detailRows;
          const create: ObjectValue = {
            name, page: 'Tally', columns: [{ time: 'MONTH' }],
            rows: rows.map(variable => ({ variable, new: true })),
            variables: rows.map(target => ({ target, currency: 'USD', format: 'CURRENCY' })),
            window: { start: `${month}-01`, end, granularity: 'MONTH' },
          };
          // Inputs apply only to the new table's current month; never reset an existing table.
          create.values = { columns: [month], rows: rows.filter(row => row !== remainingRow).map(row => [row, row === budgetRow ? context.config.budget.usd : 0]) };
          if (name === table) create.rows = [
            { variable: budgetRow, new: true }, { variable: spendRow, new: true },
            { variable: remainingRow, new: true, formula: `\`${budgetRow}\` - \`${spendRow}\`` },
          ];
          const receipt = await call('edit_table_blocks', { ...scope, create });
          if (receipt.status !== 'applied') throw new Error('Creation not applied');
        }
        blocks = await inspect();
      }
      const budgetBlock = find(table);
      const detailBlock = find(detailTable);
      for (const [block, rows] of [[budgetBlock, budgetRows], [detailBlock, detailRows]] as const) {
        if (!block) throw new Error('Created table not found');
        const layout = object(block.layout);
        const names = new Set(Array.isArray(layout.rows) ? layout.rows.map(row => object(row).display_name) : []);
        if (rows.some(row => !names.has(row))) throw new Error('Existing table lacks required rows');
        const columns = Array.isArray(layout.columns) ? layout.columns.map(object) : [];
        if (!columns.some(c => c.time === 'MONTH' || (c.grain === 'MONTH' && String(c.dimension).startsWith('Date')))) throw new Error('Table needs monthly Date columns');
      }
      const pageUrl = https(object(budgetBlock!.page).url);
      const tableUrl = https(budgetBlock!.url);
      const spendDetailTableUrl = https(detailBlock!.url);
      if (!pageUrl || !tableUrl || !spendDetailTableUrl) throw new Error('Missing discovered HTTPS table/page URL');
      const cfoai = { orgId, scenario, table, budgetRow, spendRow, remainingRow,
        spendDetailTable: detailTable, tierSpendRows, runSpendRow, cumulativeRunSpendRow,
        pageUrl, tableUrl, spendDetailTableUrl };
      // Verify the adapter can read the chosen budget before proposing budget.source=cfoai.
      const budgetClient = (this.options.client ?? createCfoaiClient)();
      const adapter = new CfoaiBudgetAdapter({ client: budgetClient, config: cfoai, now: () => now });
      try { await adapter.remainingNanos(); } finally { await budgetClient.close(); }
      return { enabled: true, state: { status: 'ok', detail: `cfo.ai configured for ${workspace.name}, ${scenario}.` },
        budget: { source: 'cfoai', usd: context.config.budget.usd, cfoai } };
    } catch {
      context.ui.print('cfo.ai setup could not be verified; using the local budget. You can rerun onboarding to retry; existing model data was not reset.');
      return off('cfo.ai setup incomplete; local budget selected.');
    } finally { await client.close().catch(() => undefined); }
  }
}
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { chmodSync, constants, copyFileSync, existsSync } from 'node:fs';
import { homedir } from 'node:os';
import { loadEnv } from '../engine/env.js';
import type { IntegrationState } from '../schema/types.js';
import type { IntegrationOnboarding, OnboardingContext, OnboardingResult } from './types.js';
import { readHiddenSecret, saveSecrets } from './secrets.js';

// Confirmed from the public app's route manifest; authentication is still required.
export const NEATLOGS_KEYS_URL = 'https://app.neatlogs.com/settings/api-keys';
const PUBLIC_API = 'https://app.neatlogs.com/api/v1/public';
type Env = Record<string, string>;

async function openBrowser(url: string): Promise<void> {
  const file = process.platform === 'darwin' ? 'open' : process.platform === 'win32' ? 'cmd' : 'xdg-open';
  await promisify(execFile)(file, process.platform === 'win32' ? ['/c', 'start', '', url] : [url], { timeout: 15_000 });
}

async function probe(key: string): Promise<boolean> {
  try {
    const entry = createRequire(import.meta.url).resolve('neatlogs');
    const result = await promisify(execFile)(process.execPath, [join(dirname(entry), 'cli.mjs'), 'doctor', '--probe', '--json'], {
      env: { ...process.env, NEATLOGS_API_KEY: key, NEATLOGS_ENDPOINT: 'https://ingest.neatlogs.com' },
      timeout: 90_000, maxBuffer: 1_000_000,
    });
    return JSON.parse(result.stdout).status === 'pass';
  } catch { return false; }
}

async function projects(token: string): Promise<{ id: string; name: string }[]> {
  const response = await fetch(`${PUBLIC_API}/projects`, {
    headers: { authorization: `Bearer ${token}` }, signal: AbortSignal.timeout(15_000), redirect: 'error',
  });
  if (!response.ok) throw new Error('Read token was not accepted');
  const result = await response.json() as { data?: { projects?: { id?: string; name?: string }[] } };
  if (!Array.isArray(result.data?.projects)) throw new Error('Unreadable project listing');
  return result.data.projects.filter((p): p is { id: string; name: string } => typeof p.id === 'string' && typeof p.name === 'string');
}

export async function installGlobalNeatlogsHooks(env: Env, options: {
  home?: string;
  run?: (file: string, args: string[], env: Env) => Promise<void>;
} = {}): Promise<void> {
  for (const relative of ['.claude/settings.json', '.codex/hooks.json']) {
    const file = join(options.home ?? homedir(), relative);
    const backup = `${file}.pre-tally-neatlogs`;
    if (existsSync(file) && !existsSync(backup)) {
      copyFileSync(file, backup, constants.COPYFILE_EXCL);
      chmodSync(backup, 0o600);
    }
  }
  // Credentials travel only in the subprocess environment, never its argv or output.
  const run = options.run ?? (async (file, args, values) => {
    await promisify(execFile)(file, args, { env: { ...process.env, ...values }, timeout: 180_000, maxBuffer: 1_000_000 });
  });
  await run('npm', ['install', '--global', '@neatlogs/claude-code', '@neatlogs/codex'], env);
  await run('neatlogs-claude-code', ['setup', '--global'], env);
  await run('neatlogs-codex', ['setup', '--global'], env);
}

export interface NeatlogsOnboardingOptions {
  env?: () => Env;
  probe?: (key: string) => Promise<boolean>;
  openBrowser?: (url: string) => Promise<void>;
  readSecret?: (question: string) => Promise<string | null>;
  save?: (values: Env) => void;
  projects?: (token: string) => Promise<{ id: string; name: string }[]>;
  verifyProject?: (token: string, projectId: string) => Promise<boolean>;
  installHooks?: (env: Env) => Promise<void>;
}

export class NeatlogsOnboarding implements IntegrationOnboarding {
  private key: string | null = null;
  constructor(private readonly options: NeatlogsOnboardingOptions = {}) {}
  private env(): Env { return (this.options.env ?? loadEnv)(); }
  async check(): Promise<IntegrationState> {
    const key = this.env().NEATLOGS_API_KEY;
    // A passive check does not export a probe. Verification is a consented connect step.
    return { status: key ? 'ok' : 'missing', detail: key ? 'neatlogs key is configured; connection verification is separate.' : 'neatlogs needs a project API key.' };
  }
  async connect(context: OnboardingContext): Promise<IntegrationState> {
    this.key = null;
    const ui = context.ui;
    let key = this.env().NEATLOGS_API_KEY ?? null;
    ui.print('neatlogs needs a US project API key; sign up at https://app.neatlogs.com or skip. Verification exports only SDK-generated probe spans, not repository data.');
    if (!await ui.confirm(key ? 'Verify the configured neatlogs key with the SDK probe?' : 'Open the neatlogs API keys page and connect?')) {
      return { status: 'off', detail: 'neatlogs skipped; decisions remain in the local ledger.' };
    }
    try {
      if (!key) {
        await (this.options.openBrowser ?? openBrowser)(NEATLOGS_KEYS_URL);
        key = await (this.options.readSecret ?? readHiddenSecret)('neatlogs project API key');
      }
      if (!key) return { status: 'off', detail: 'neatlogs skipped: no API key supplied.' };
      if (!await (this.options.probe ?? probe)(key)) {
        ui.print('The neatlogs SDK probe rejected that key; it was not saved.');
        if (!await ui.confirm('Open API keys and try a replacement key?')) return { status: 'missing', detail: 'neatlogs SDK probe failed; the key was not saved.' };
        await (this.options.openBrowser ?? openBrowser)(NEATLOGS_KEYS_URL);
        key = await (this.options.readSecret ?? readHiddenSecret)('replacement neatlogs project API key');
        if (!key || !await (this.options.probe ?? probe)(key)) return { status: 'missing', detail: 'Replacement key was not verified or saved.' };
      }
      if (key !== this.env().NEATLOGS_API_KEY) (this.options.save ?? saveSecrets)({ NEATLOGS_API_KEY: key });
      this.key = key;
      return { status: 'ok', detail: 'neatlogs SDK probe passed.' };
    } catch { return { status: 'missing', detail: 'neatlogs connection did not complete; credentials were not printed.' }; }
  }
  async configure(context: OnboardingContext): Promise<OnboardingResult> {
    const state = await this.connect(context);
    if (state.status !== 'ok' || !this.key) return { enabled: false, state };
    if (await context.ui.confirm('Connect optional neatlogs read access for past costs and outcomes?')) {
      try {
        const token = this.env().NEATLOGS_TOKEN ?? await (this.options.readSecret ?? readHiddenSecret)('neatlogs service-account read token');
        if (token) {
          const available = await (this.options.projects ?? projects)(token);
          const index = available.length === 1 ? 0 : await context.ui.select('Choose the neatlogs project (or skip)', available.map(p => p.name));
          const selected = index === null ? undefined : available[index];
          if (selected) {
            const verified = this.options.verifyProject ? await this.options.verifyProject(token, selected.id) : await this.verifyProject(token, selected.id);
            if (!verified) throw new Error('Project read failed');
